// #region 📦Factory

// Factory function to instantiate the sketchpad actor.

/**
 * Instantiates and returns a sketchpad XState actor from the given input.
 **/
export function createSketchpadActor(input: SketchpadMachineInput) {
  return createActor(sketchpadMachine, {
    input,
    inspect: (inspectionEvent) => {
      if (inspectionEvent.type === "@xstate.snapshot") {
        const { snapshot, event, actorRef } = inspectionEvent;
        if (event.type === "xstate.init") return;
        const stateValue = "value" in (snapshot as any) ? (typeof (snapshot as any).value === "object" ? JSON.stringify((snapshot as any).value) : (snapshot as any).value) : JSON.stringify(snapshot);
      }
    },
  });
}

// #endregion 📦Factory

// #region 📍Sketchpad type exports
// Kit machine types, Yjs-backed kit events, and sketchpad/kit selectors (stable public surface).

/**
 * Transaction context interface with typed edits.
 **/
export interface TransactionContext<TEdit = any> {
  isTransactionActive: boolean;
  currentTransactionStack: TEdit[];
  pastTransactionsStack: TEdit[];
  redoStack: TEdit[];
  lastDeletedEdit?: TEdit;
}

/**
 * Kit machine input with sync document and map references.
 **/
export interface KitMachineInput {
  syncDoc: SyncDoc;
  syncKit: SyncMap<any>;
  id: Id;
  kind?: KitKind;
}

/**
 * Kit context with Sync-backed state and caching.
 **/
export interface KitContext {
  syncDoc: SyncDoc;
  syncKit: SyncMap<any>;
  id: Id;
  kind: KitKind;
  dirty: boolean;
  cache?: Kit;
}

/**
 * Kit event union for CRUD and synchronization operations.
 **/
export type KitEvent =
  | { type: "CHANGE"; diff: KitDiff }
  | { type: "CREATE_TYPE"; typeData: any }
  | { type: "UPDATE_TYPE"; id: Id; diff: any }
  | { type: "DELETE_TYPE"; id: Id }
  | { type: "CREATE_DESIGN"; design: any }
  | { type: "UPDATE_DESIGN"; id: Id; diff: any }
  | { type: "DELETE_DESIGN"; id: Id }
  | { type: "Y_UPDATE"; data: any }
  | { type: "MARK_DIRTY" };

/** buildKitSnapshot holds the data fields for a buildKitSnapshot record.
 **/
/**
 **/
function buildKitSnapshot(syncKit: SyncMap<any>): Partial<Kit> {
  return {
    id: syncKit.get("id") as string,
    name: syncKit.get("name") as string,
    version: syncKit.get("version") as string | undefined,
    description: syncKit.get("description") as string | undefined,
    homepage: syncKit.get("homepage") as string | undefined,
    license: syncKit.get("license") as string | undefined,
    icon: syncKit.get("icon") as string | undefined,
    image: syncKit.get("image") as string | undefined,
    createdAt: syncKit.get("createdAt") as string | undefined,
    updatedAt: syncKit.get("updatedAt") as string | undefined,
  };
}

