// #region 💧Details
// Details MUST render the Kit app detail panels for kit, type, port, tag, design, file, folder, and multi-artifact sections.

/**
 * @emoji 🧾 Stringify optional type parent reference for read-only display rows.
 */
function formatTypeParentRefForInput(value: unknown): string {
  if (value == null) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object" && "id" in (value as object)) {
    const id = (value as { id?: unknown }).id;
    return id != null ? String(id) : "";
  }
  return "";
}

// #region 🔖SegregatedFieldRows

/**
 * @emoji 📥📝 Read+write segregated text row: explicit `value` (read lane) and `commit`+`status` (write lane).
 * Eliminates the legacy `[value, setter, status]` triadic prop shape.
 */
function SketchpadInputRow(props: {
  value: string | null | undefined;
  commit: (next: unknown) => Promise<unknown>;
  status: OperationStatus;
  id: string;
  placeholder?: string;
  placeholderId?: string;
  readOnly?: boolean;
  mapCommit?: (raw: string) => unknown;
}): React.ReactElement {
  const { value, commit, status, id, placeholder, placeholderId, readOnly, mapCommit } = props;
  const { spinning, error, disabled } = useWriteIndicator(status);
  const display = value == null ? "" : typeof value === "string" ? value : String(value);
  const isReadOnly = readOnly === true || disabled;
  return (
    <TreeRow>
      <div className="flex min-w-0 w-full flex-col gap-tiny">
        <div className="flex min-w-0 w-full items-center gap-single">
          <div className="min-w-0 flex-1">
            <Input lazy id={id} value={display} readOnly={isReadOnly} placeholder={placeholder} placeholderId={placeholderId} onLazyChange={isReadOnly ? undefined : (v) => void commit(mapCommit != null ? mapCommit(v) : v)} showLabel />
          </div>
          {spinning ? <Spinner size="small" className="text-muted-foreground shrink-0" /> : null}
        </div>
        {error?.message ? <p className="pl-tiny text-xs text-destructive">{error.message}</p> : null}
      </div>
    </TreeRow>
  );
}

/** @emoji 📥📝 Multiline counterpart to {@link SketchpadInputRow} (same segregated value+command shape). */
function SketchpadTextareaRow(props: {
  value: string | null | undefined;
  commit: (next: unknown) => Promise<unknown>;
  status: OperationStatus;
  id: string;
  placeholder?: string;
  placeholderId?: string;
  readOnly?: boolean;
  mapCommit?: (raw: string) => unknown;
}): React.ReactElement {
  const { value, commit, status, id, placeholder, placeholderId, readOnly, mapCommit } = props;
  const { spinning, error, disabled } = useWriteIndicator(status);
  const display = value == null ? "" : typeof value === "string" ? value : String(value);
  const isReadOnly = readOnly === true || disabled;
  return (
    <TreeRow>
      <div className="flex min-w-0 w-full flex-col gap-tiny">
        <div className="flex min-w-0 w-full items-center gap-single">
          <div className="min-w-0 flex-1">
            <Textarea lazy id={id} value={display} readOnly={isReadOnly} placeholder={placeholder} placeholderId={placeholderId} onLazyChange={isReadOnly ? undefined : (v) => void commit(mapCommit != null ? mapCommit(v) : v)} showLabel />
          </div>
          {spinning ? <Spinner size="small" className="text-muted-foreground shrink-0" /> : null}
        </div>
        {error?.message ? <p className="pl-tiny text-xs text-destructive">{error.message}</p> : null}
      </div>
    </TreeRow>
  );
}

// #endregion 🔖SegregatedFieldRows

/**
 * Detail section component for the currently open kit.
 *MUST render the kit metadata form fields within a detail panel section.
 **/
export const KitSection: FC = () => {
  const isInActiveKitTab = useIsInActiveKitTab();
  if (!isInActiveKitTab) return null;
  return <KitSectionForm />;
};

/** KitSectionForm holds the data fields for a KitSectionForm record.
 **/
/**
 **/
const KitSectionForm: FC = () => {
  const kit = useWipKitOptional();
  if (kit == null) return null;
  const { run: kitRun, status: renameKitStatus } = useKitCommand();
  const changeKitDescriptionStatus = renameKitStatus;
  const { spinning, error, disabled } = useWriteIndicator(renameKitStatus);
  // 📥 Read lane — value-only hooks follow the active kit read scope.
  const kitNameValue = useKitName();
  const description = useKitDescription();
  const icon = useKitIcon();
  const image = useKitImage();
  const homepage = useKitHomepage();
  const license = useKitLicense();
  const notAvailableLabel = useLabel("semio.sketchpad.app.kit.notAvailable");
  const descriptionPlaceholder = useLabel("semio.sketchpad.app.kit.descriptionPlaceholder.label");
  const iconPlaceholder = useLabel("semio.sketchpad.app.kit.iconPlaceholder.label");
  const imagePlaceholder = useLabel("semio.sketchpad.app.kit.imagePlaceholder.label");
  const homepagePlaceholder = useLabel("semio.sketchpad.app.kit.homepagePlaceholder.label");
  const licensePlaceholder = useLabel("semio.sketchpad.app.kit.licensePlaceholder.label");

  if (!kit) {
    return (
      <HelperRow propertyAligned>
        <p className="text-sm text-muted-foreground">{notAvailableLabel}</p>
      </HelperRow>
    );
  }

  return (
    <>
      <TreeRow>
        <div className="flex min-w-0 w-full flex-col gap-tiny">
          <div className="flex min-w-0 w-full items-center gap-single">
            <div className="min-w-0 flex-1">
              <Input lazy id="semio.sketchpad.app.kit.panel.details.section.kit.name" value={kitNameValue ?? ""} readOnly={disabled} onLazyChange={disabled ? undefined : (v) => void kitRun.rename(v)} showLabel />
            </div>
            {spinning ? <Spinner size="small" className="text-muted-foreground shrink-0" /> : null}
          </div>
          {error?.message ? <p className="pl-tiny text-xs text-destructive">{error.message}</p> : null}
        </div>
      </TreeRow>
      <SketchpadTextareaRow
        value={description ?? ""}
        commit={async (value) => kitRun.changeDescription(String(value))}
        status={changeKitDescriptionStatus}
        id="semio.sketchpad.app.kit.panel.details.section.kit.description"
        placeholder={descriptionPlaceholder}
      />
      <SketchpadInputRow value={icon ?? ""} commit={async () => ({ ok: true }) as const} status={OPERATION_STATUS_IDLE} id="semio.sketchpad.app.kit.panel.details.section.kit.icon" placeholder={iconPlaceholder} readOnly />
      <SketchpadInputRow value={image ?? ""} commit={async () => ({ ok: true }) as const} status={OPERATION_STATUS_IDLE} id="semio.sketchpad.app.kit.panel.details.section.kit.image" placeholder={imagePlaceholder} readOnly />
      <SketchpadInputRow value={homepage ?? ""} commit={async () => ({ ok: true }) as const} status={OPERATION_STATUS_IDLE} id="semio.sketchpad.app.kit.panel.details.section.kit.homepage" placeholder={homepagePlaceholder} readOnly />
      <SketchpadInputRow value={license ?? ""} commit={async () => ({ ok: true }) as const} status={OPERATION_STATUS_IDLE} id="semio.sketchpad.app.kit.panel.details.section.kit.license" placeholder={licensePlaceholder} readOnly />
    </>
  );
};

