// #region 🌱AlternativeSelector
/** @emoji 🌱 Sentinel option value for the main kit line (Radix Select rejects empty string). */
const SEMIO_SKETCHPAD_THE_KIT_ALT_VALUE = "__semio_sketchpad_the_kit__";

/**
 * @emoji 🌱 Footer dropdown: the kit vs WIP alternatives; unsaved count via {@link Alternative#unsavedChangeCount}.
 **/
const KitAlternativeFooterSelector: FC = () => {
  const addFooterItem = useAddFooterItem();
  const removeFooterItem = useRemoveFooterItem();
  const appType = useAppType();
  const [selectedAlternativeId, setSelectedAlternativeId] = useKitAlternativeSelection();
  const alternatives = useKitAlternatives();
  const store = useStoreOptional();
  const session = store?.session ?? null;
  const newAltInputRef = useRef<HTMLInputElement>(null);
  const [creatingAlt, setCreatingAlt] = useState(false);
  const [unsavedCount, setUnsavedCount] = useState(0);
  const [hubUser, setHubUser] = useState("");
  const [hubPass, setHubPass] = useState("");
  const [hubUrl, setHubUrl] = useState("");

  const handleCreateAlternative = useCallback(async () => {
    const name = newAltInputRef.current?.value?.trim() ?? "";
    if (store == null || name === "" || creatingAlt) return;
    setCreatingAlt(true);
    try {
      const result = await store.startAlternative(name);
      if (!result.ok) return;
      const alts = await store.wip().alternatives();
      let match = alts.at(-1) ?? null;
      for (const a of alts) {
        if ((await a.name()) === name) {
          match = a;
          break;
        }
      }
      if (match != null) setSelectedAlternativeId(match.id);
      if (newAltInputRef.current) newAltInputRef.current.value = "";
    } catch {
      /* ignore */
    } finally {
      setCreatingAlt(false);
    }
  }, [store, creatingAlt, setSelectedAlternativeId]);

  useEffect(() => {
    if (store == null || selectedAlternativeId == null) {
      setUnsavedCount(0);
      return;
    }
    const alt = store.wip().alternative(selectedAlternativeId);
    let cancelled = false;
    const pull = (): void => {
      void alt.unsavedChangeCount().then((n) => {
        if (!cancelled) setUnsavedCount(n);
      });
    };
    pull();
    const off = alt.onUnsavedChangeCountChanged(() => pull());
    return () => {
      cancelled = true;
      off();
    };
  }, [store, selectedAlternativeId]);

  useEffect(() => {
    if (appType !== "kit" && appType !== "design" && appType !== "type") return;
    const value = selectedAlternativeId ?? SEMIO_SKETCHPAD_THE_KIT_ALT_VALUE;
    const altStamp = alternatives.map((a) => a.id).join(",");
    const footerEquivClass = `semio-sketchpad-footer-alt-${value.replace(/[^a-zA-Z0-9_-]/g, "_")}--${altStamp.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 160)}`;
    addFooterItem({
      id: "semio.sketchpad.footer.alternative",
      order: -1000,
      className: footerEquivClass,
      content: (
        <div className="flex items-center gap-1 flex-wrap">
          <Select id="semio.sketchpad.footer.alternative.select" value={value} onValueChange={(v: string) => setSelectedAlternativeId(v === SEMIO_SKETCHPAD_THE_KIT_ALT_VALUE ? null : v)} showLabel={false}>
            <SelectTrigger className="min-w-[10rem]">
              <SelectValue placeholder="the kit" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={SEMIO_SKETCHPAD_THE_KIT_ALT_VALUE}>the kit</SelectItem>
              {alternatives.map((a) => (
                <SelectItem key={a.id} value={a.id}>
                  {a.name?.trim() ? a.name : a.id.slice(0, 8)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {unsavedCount > 0 ? (
            <span className="text-xs tabular-nums rounded border border-amber-600/50 px-1.5 py-0.5 text-amber-700 dark:text-amber-300" title="Unsaved changes on the selected alternative">
              {unsavedCount} unsaved
            </span>
          ) : null}
          <Input
            ref={newAltInputRef}
            className="h-8 min-w-[7rem] max-w-[12rem] text-xs"
            placeholder="Branch name"
            disabled={store == null}
            aria-label="New alternative name"
            onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => {
              if (e.key === "Enter") void handleCreateAlternative();
            }}
          />
          <Button type="button" variant="outline" size="sm" className="h-8 min-w-8 px-2" disabled={store == null || creatingAlt} aria-label="Create alternative from current checkpoint" onClick={() => void handleCreateAlternative()}>
            +
          </Button>
          <Input className="h-8 min-w-[6rem] max-w-[9rem] text-xs" placeholder="hub user" value={hubUser} onChange={(e) => setHubUser(e.target.value)} aria-label="Hub username" />
          <Input className="h-8 min-w-[6rem] max-w-[9rem] text-xs" type="password" placeholder="password hash" value={hubPass} onChange={(e) => setHubPass(e.target.value)} aria-label="Hub password hash" />
          <Input className="h-8 min-w-[6rem] max-w-[10rem] text-xs" placeholder="hub url (opt)" value={hubUrl} onChange={(e) => setHubUrl(e.target.value)} aria-label="Hub base URL" />
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 px-2 text-xs"
            disabled={session == null}
            onClick={() => {
              if (session == null) return;
              void session.login(hubUser, hubPass, hubUrl || undefined);
            }}
          >
            login
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 px-2 text-xs"
            disabled={session == null}
            onClick={() => {
              if (session == null) return;
              void session.logout();
            }}
          >
            logout
          </Button>
        </div>
      ),
    });
    return () => removeFooterItem("semio.sketchpad.footer.alternative");
  }, [appType, addFooterItem, removeFooterItem, selectedAlternativeId, alternatives, setSelectedAlternativeId, store, session, creatingAlt, handleCreateAlternative, unsavedCount, hubUser, hubPass, hubUrl]);

  return null;
};
