// registerDesignAppStoreFactory, registerKitAppStoreFactory, registerQualityAppStoreFactory, registerTypeAppStoreFactory are already declared above
/**
 * SyncSketchpadVal holds the data fields for a SyncSketchpadVal record.
 **/
type SyncSketchpadVal = string | number | boolean;
/**
 * SyncSketchpad holds the data fields for a SyncSketchpad record.
 **/
type SyncSketchpad = SyncMap<SyncSketchpadVal>;

let designAppModuleCache: any;
let homeAppModuleCache: any;
let kitAppModuleCache: any;
let typeAppModuleCache: any;
let qualityAppModuleCache: any;
/**
 * Central store managing Sync-backed sketchpad state with reactive subscriptions.
 **/
export class SketchpadStore {
  private static _modulesLoaded = false;
  public static _loadModules() {
    if (SketchpadStore._modulesLoaded) return;
    SketchpadStore._modulesLoaded = true;
    // All modules are now consolidated in this file, no dynamic imports needed
  }
  private readonly id: string | undefined;
  private readonly remote: RemoteProviders | undefined;
  private readonly syncDoc: SyncDoc;
  private readonly syncSketchpad: SyncSketchpad;
  private readonly syncKits: SyncKitMetadatas;
  private homeStore?: HomeStoreInstance;
  private readonly syncKitApps: SyncKitApps;
  private readonly kitApps: Map<string, KitAppStoreInstance>;
  private readonly typeApps: Map<string, TypeAppStoreInstance>;
  private readonly qualityApps: Map<string, QualityAppStoreInstance>;
  private readonly designApps: Map<string, Map<string, DesignAppStoreInstance>>;
  private readonly persistence?: PersistenceProvider;
  private readonly persistenceFactory?: PersistenceFactory;
  private readonly commandRegistry: Map<string, (context: SketchpadCommandContext, ...rest: any[]) => SketchpadCommandResult>;
  private readonly commandMetadata: Map<string, { user?: boolean }>;
  private cache?: SketchpadState;
  private cacheHash?: string;
  private readonly kitCreatedSubscribers: Set<() => void>;
  private readonly kitDeletedSubscribers: Set<() => void>;
  private readonly kitAppCreatedSubscribers: Set<() => void>;
  private readonly kitAppDeletedSubscribers: Set<() => void>;
  private readonly typeAppCreatedSubscribers: Set<() => void>;
  private readonly typeAppDeletedSubscribers: Set<() => void>;
  private readonly qualityAppCreatedSubscribers: Set<() => void>;
  private readonly qualityAppDeletedSubscribers: Set<() => void>;
  private readonly designAppCreatedSubscribers: Set<() => void>;
  private readonly designAppDeletedSubscribers: Set<() => void>;
  private readonly tutorialStoreInstance: any;
  private readonly temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly folderKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly fileKitStoreFactory?: SketchpadKitStoreFactory;
  private readonly remoteKitStoreFactory?: SketchpadKitStoreFactory;
  /** When true (Electron desktop), no kit snapshots are written to localStorage/IndexedDB (kits reopen via Open only). */
  private readonly skipBrowserKitSnapshotPersistence: boolean;
  actor?: SketchpadActorRef;
  private actorUnsubscribe?: () => void;

  constructor(
    id?: string,
    remote?: RemoteProviders,
    initialState?: ExtendedInitialState,
    persistenceFactory?: PersistenceFactory,
    temporaryKitStoreFactory?: SketchpadKitStoreFactory,
    folderKitStoreFactory?: SketchpadKitStoreFactory,
    fileKitStoreFactory?: SketchpadKitStoreFactory,
    remoteKitStoreFactory?: SketchpadKitStoreFactory,
    skipBrowserKitSnapshotPersistence?: boolean,
  ) {
    this.id = id;
    this.remote = remote;
    this.persistenceFactory = persistenceFactory;
    this.temporaryKitStoreFactory = temporaryKitStoreFactory;
    this.folderKitStoreFactory = folderKitStoreFactory;
    this.fileKitStoreFactory = fileKitStoreFactory;
    this.remoteKitStoreFactory = remoteKitStoreFactory;
    this.skipBrowserKitSnapshotPersistence = Boolean(skipBrowserKitSnapshotPersistence);
    this.syncDoc = createSyncDocFactory()();
    this.kitApps = new Map();
    this.typeApps = new Map();
    this.qualityApps = new Map();
    this.designApps = new Map();
    this.commandRegistry = new Map();
    this.commandMetadata = new Map();
    this.kitCreatedSubscribers = new Set();
    this.kitDeletedSubscribers = new Set();
    this.kitAppCreatedSubscribers = new Set();
    this.kitAppDeletedSubscribers = new Set();
    this.typeAppCreatedSubscribers = new Set();
    this.typeAppDeletedSubscribers = new Set();
    this.qualityAppCreatedSubscribers = new Set();
    this.qualityAppDeletedSubscribers = new Set();
    this.designAppCreatedSubscribers = new Set();
    this.designAppDeletedSubscribers = new Set();

    if (id && this.persistenceFactory) {
      this.persistence = this.persistenceFactory(this.syncDoc, `semio-sketchpad-${id}`);
      this.persistence.once("synced", () => {
        const isMobile = typeof window !== "undefined" ? window.innerWidth < 768 : false;
        this.syncSketchpad.set("isMobile", isMobile);
      });
      if (this.remote) {
        this.remote.syncProvider(this.syncDoc, id);
      }
    }

    this.syncSketchpad = this.syncDoc.getMap("sketchpad");
    this.syncKits = this.syncDoc.getArray("kits");
    this.syncKitApps = this.syncDoc.getMap("kitApps");

    const syncTutorials = this.syncDoc.getMap("tutorials");
    this.tutorialStoreInstance = new TutorialStore(syncTutorials, (fn) => this.syncDoc.transact(fn));

    this.loadPersistedKits();

    this.syncDoc.transact(() => {
      if (!this.syncSketchpad.has("navigation")) {
        this.syncSketchpad.set("navigation", "/");
      }
      if (!this.syncSketchpad.has("navigationHistory")) {
        this.syncSketchpad.set("navigationHistory", JSON.stringify(["/"]));
      }
      if (!this.syncSketchpad.has("navigationHistoryIndex")) {
        this.syncSketchpad.set("navigationHistoryIndex", 0);
      }
      if (!this.syncSketchpad.has("recentSearches")) {
        this.syncSketchpad.set("recentSearches", JSON.stringify([]));
      }
      if (!this.syncSketchpad.has("recentFocusItems")) {
        this.syncSketchpad.set("recentFocusItems", JSON.stringify({}));
      }
      if (!this.syncSketchpad.has("theme")) {
        this.syncSketchpad.set("theme", Theme.SYSTEM);
      }
      if (!this.syncSketchpad.has("language")) {
        this.syncSketchpad.set("language", "en");
      }
      if (!this.syncSketchpad.has("device")) {
        this.syncSketchpad.set("device", JSON.stringify("desktop"));
      }
      if (!this.syncSketchpad.has("expertise")) {
        this.syncSketchpad.set("expertise", Expertise.BEGINNER);
      }
      if (!this.syncSketchpad.has("mode")) {
        this.syncSketchpad.set("mode", Mode.USER);
      }
      if (!this.syncSketchpad.has("isFullscreen")) {
        this.syncSketchpad.set("isFullscreen", false);
      }
      const isMobile = typeof window !== "undefined" ? window.innerWidth < 768 : false;
      this.syncSketchpad.set("isMobile", isMobile);
      if (!this.syncSketchpad.has("activeInteraction")) {
        this.syncSketchpad.set("activeInteraction", "");
      }
      if (!this.syncSketchpad.has("settings")) {
        this.syncSketchpad.set(
          "settings",
          JSON.stringify({
            apps: {
              design: {
                diagram: { proximityConnectDistance: 10 },
                scene: { gridSize: 24 },
              },
            },
          }),
        );
      }
      if (!this.syncSketchpad.has("panelSizes")) {
        this.syncSketchpad.set(
          "panelSizes",
          JSON.stringify({
            toolbarHeight: 52,
            toolsWidth: 230,
            hudWidth: 230,
            statsWidth: 230,
            detailsWidth: 230,
            consoleHeight: 200,
          }),
        );
      }
    });

    Object.entries(sketchpadCommands).forEach(([commandId, command]) => {
      this.registerCommand(commandId, command);
    });
    Object.entries(devCommands).forEach(([commandId, command]) => {
      this.registerCommand(commandId, command, { user: false });
    });

    if (initialState) {
      this.syncDoc.transact(() => {
        if (initialState.navigation !== undefined) this.syncSketchpad.set("navigation", initialState.navigation);
        if (initialState.navigationHistory !== undefined) this.syncSketchpad.set("navigationHistory", JSON.stringify(initialState.navigationHistory));
        if (initialState.navigationHistoryIndex !== undefined) this.syncSketchpad.set("navigationHistoryIndex", initialState.navigationHistoryIndex);
        if (initialState.recentSearches !== undefined) this.syncSketchpad.set("recentSearches", JSON.stringify(initialState.recentSearches));
        if (initialState.recentFocusItems !== undefined) this.syncSketchpad.set("recentFocusItems", JSON.stringify(initialState.recentFocusItems));
        if (initialState.theme !== undefined) this.syncSketchpad.set("theme", initialState.theme);
        if (initialState.language !== undefined) this.syncSketchpad.set("language", initialState.language);
        if (initialState.device !== undefined) this.syncSketchpad.set("device", JSON.stringify(initialState.device));
        if (initialState.expertise !== undefined) this.syncSketchpad.set("expertise", initialState.expertise);
        if (initialState.mode !== undefined) this.syncSketchpad.set("mode", initialState.mode);
        if (initialState.settings !== undefined) this.syncSketchpad.set("settings", JSON.stringify(initialState.settings));
        if (initialState.panelSizes !== undefined) this.syncSketchpad.set("panelSizes", JSON.stringify(initialState.panelSizes));
        if (initialState.isFullscreen !== undefined) this.syncSketchpad.set("isFullscreen", initialState.isFullscreen);
        if (initialState.hotkeyOverrides !== undefined) this.syncSketchpad.set("hotkeyOverrides", JSON.stringify(initialState.hotkeyOverrides));
        if (initialState.activeHotkeySetting !== undefined) this.syncSketchpad.set("activeHotkeySetting", initialState.activeHotkeySetting);
      });

      if (initialState.kits) {
        const kitsToOpen = initialState.kits.slice();
        /** Defer so `createKit` → `openKitInRegistry` never runs during React render (registry `bump` would setState on `KitRegistryProvider` while a child is rendering). */
        queueMicrotask(() => {
          kitsToOpen.forEach(({ kit, kind, source, session }) => {
            void this.createKit(kit, kind, source, false, session);
          });
        });
      }
    }
  }

  setActor = (actor: SketchpadActorRef) => {
    if (this.actorUnsubscribe) {
      this.actorUnsubscribe();
      this.actorUnsubscribe = undefined;
    }
    this.actor = actor;
    this.cache = undefined;
    this.cacheHash = undefined;
    if (this.id) {
      writeSketchpadStateToLocalStorage(this.id, actor.getSnapshot().context.sketchpad);
      const subscription = actor.subscribe((snapshot) => {
        writeSketchpadStateToLocalStorage(this.id!, snapshot.context.sketchpad);
      });
      this.actorUnsubscribe = () => subscription.unsubscribe();
    }
  };

  private persistKitsToStorage = () => {
    if (!this.id) return;
    if (this.skipBrowserKitSnapshotPersistence) {
      clearSketchpadKitSnapshotsInBrowserStorage(this.id);
      return;
    }
    const reg = getKitRegistryBridge();
    const kitIds = new Set<string>();
    if (reg) {
      for (const k of reg.list()) {
        kitIds.add(k);
      }
    }
    const persistedKits: InitialStateKit[] = Array.from(kitIds, (kid) => {
      const kitStore = this.kitStore(kid);
      const kit = kitStore.getSnapshot().kit;
      const persistenceKind = (kitStore as any).__semioKitPersistenceKind as KitKind | undefined;
      return {
        kit,
        kind: persistenceKind ?? "temporary",
        source: this.getKitPersistenceSource(kitStore),
      };
    });
    writeSketchpadKitsToLocalStorage(this.id, persistedKits);
    void writeSketchpadKitsToIndexedDb(this.id, persistedKits);
  };

  private schedulePersistKitsToStorage = () => {
    if (this.persistKitsTimer) {
      clearTimeout(this.persistKitsTimer);
    }
    this.persistKitsTimer = setTimeout(() => {
      this.persistKitsTimer = undefined;
      this.persistKitsToStorage();
    }, 150);
  };

  hash = (state: SketchpadState): string => {
    return JSON.stringify(state);
  };

  snapshot = (): SketchpadState => {
    if (this.actor) {
      return this.actor.getSnapshot().context.sketchpad;
    }
    const settingsStr = this.syncSketchpad.get("settings") as string;
    const settings = settingsStr
      ? JSON.parse(settingsStr)
      : {
          apps: {
            design: {
              diagram: { proximityConnectDistance: 10 },
              scene: { gridSize: 24 },
            },
          },
        };
    const panelSizesStr = this.syncSketchpad.get("panelSizes") as string;
    const panelSizes = panelSizesStr
      ? JSON.parse(panelSizesStr)
      : {
          toolbarHeight: 52,
          toolsWidth: 230,
          hudWidth: 230,
          statsWidth: 230,
          detailsWidth: 230,
          consoleHeight: 200,
        };
    const navigationHistoryStr = this.syncSketchpad.get("navigationHistory") as string;
    const navigationHistory = navigationHistoryStr ? JSON.parse(navigationHistoryStr).map(migratePath) : ["/"];
    const recentSearchesStr = this.syncSketchpad.get("recentSearches") as string;
    const recentSearches = recentSearchesStr ? JSON.parse(recentSearchesStr) : [];
    const recentFocusItemsStr = this.syncSketchpad.get("recentFocusItems") as string;
    const recentFocusItems = recentFocusItemsStr ? JSON.parse(recentFocusItemsStr) : {};
    const hotkeyOverridesStr = this.syncSketchpad.get("hotkeyOverrides") as string;
    const hotkeyOverrides = hotkeyOverridesStr ? JSON.parse(hotkeyOverridesStr) : {};
    const deviceStr = this.syncSketchpad.get("device") as string;
    const device: Device = deviceStr ? JSON.parse(deviceStr) : "desktop";
    const currentValues = {
      navigation: migratePath((this.syncSketchpad.get("navigation") as string) || "/"),
      navigationHistory: navigationHistory,
      navigationHistoryIndex: (this.syncSketchpad.get("navigationHistoryIndex") as number) ?? 0,
      recentSearches: recentSearches,
      recentFocusItems: recentFocusItems,
      theme: this.syncSketchpad.get("theme") as Theme,
      language: (this.syncSketchpad.get("language") as string) || (typeof navigator !== "undefined" && navigator.language?.toLowerCase().startsWith("de") ? "de" : "en"),
      device: device,
      expertise: (this.syncSketchpad.get("expertise") as Expertise) ?? Expertise.BEGINNER,
      mode: (this.syncSketchpad.get("mode") as Mode) ?? Mode.USER,
      settings: settings,
      panelSizes: panelSizes,
      isFullscreen: (this.syncSketchpad.get("isFullscreen") as boolean) || false,
      isMobile: (this.syncSketchpad.get("isMobile") as boolean) || false,
      activeInteraction: (this.syncSketchpad.get("activeInteraction") as string) || undefined,
      hotkeyOverrides: hotkeyOverrides,
      activeHotkeySetting: (this.syncSketchpad.get("activeHotkeySetting") as string) || undefined,
    };
    const currentHash = this.hash(currentValues);
    if (!this.cache || this.cacheHash !== currentHash) {
      this.cache = currentValues;
      this.cacheHash = currentHash;
    }
    return this.cache;
  };

  private inferKitPersistenceKind = (kitStore: KitHostStore): KitKind => {
    const existingKind = (kitStore as any).__semioKitPersistenceKind as KitKind | undefined;
    if (existingKind) {
      return existingKind;
    }
    const constructorName = (kitStore as any)?.constructor?.name ?? "";
    if (constructorName === "FolderKitStore") {
      return "folder";
    }
    if (constructorName === "JsonFileKitStore") {
      return "file";
    }
    return "temporary";
  };

  private getKitPersistenceSource = (kitStore: KitHostStore): InitialStateKit["source"] | undefined => {
    const source = (kitStore as any).__semioKitPersistenceSource as InitialStateKit["source"] | undefined;
    if (!source || typeof source !== "object") return undefined;
    if (source.kind === "folder" || source.kind === "file" || source.kind === "remote") {
      return source;
    }
    return undefined;
  };

  private resolveKitFileProviderFactory = (kind: KitKind): FileProviderFactory => {
    if (kind === "remote" && this.remote?.fileProvider) {
      return this.remote.fileProvider;
    }
    return createMemoryFileProvider();
  };

  /** @emoji 🔗 Wire autosave + file providers after {@link getKitRegistryBridge} has opened the kit. */
  private wireRegistryKitStore = (kitStore: KitHostStore, kind: KitKind, source?: InitialStateKit["source"]): void => {
    (kitStore as any).__semioKitPersistenceKind = kind;
    if (source) {
      (kitStore as any).__semioKitPersistenceSource = source;
    }
    getOrCreateKitFileState(kitStore).providerFactory = this.resolveKitFileProviderFactory(kind);
    const kid = kitStore.getSnapshot().kit.id;
    attachSketchpadKitReadShell(kitStore);

    let autoSaveTimer: ReturnType<typeof setTimeout> | undefined;
    const scheduleAutoSave = () => {
      const snapshot = kitStore.getSnapshot();
      if (snapshot.sync.dirty && snapshot.sync.status === "ready") {
        if (autoSaveTimer !== undefined) clearTimeout(autoSaveTimer);
        autoSaveTimer = setTimeout(() => {
          autoSaveTimer = undefined;
          const current = kitStore.getSnapshot();
          if (current.sync.dirty && current.sync.status === "ready") {
            kitStore.save();
          }
        }, 300);
      }
    };
    kitStore.subscribe(() => {
      this.schedulePersistKitsToStorage();
      scheduleAutoSave();
    });
    scheduleAutoSave();

    this.kitCreatedSubscribers.forEach((subscriber) => subscriber());
    if (this.actor) {
      this.actor.send({ type: "UI.OPEN_KIT.PUSH", kitId: kid } as any);
      this.actor.send({ type: "UI.OPEN_KIT.ACTIVATE", kitId: kid } as any);
    }
  };

  /** @emoji 🔗 Open via {@link KitRegistryValue}; prefer `backbone` / built-in `openJsonFile` over passing a pre-built host store. */
  private registryOpenInit = async (kitStore: KitHostStore, wasmSession?: Session): Promise<Parameters<KitRegistryValue["open"]>[1]> => {
    if (wasmSession == null) return { store: kitStore };
    const stores = await wasmSession.stores();
    return { store: kitStore, session: wasmSession, jsStoreId: stores[0]?.id };
  };

  private openKitInRegistry = async (
    kitId: string,
    init: Parameters<KitRegistryValue["open"]>[1],
    kind: KitKind,
    source?: InitialStateKit["source"],
    wasmSession?: Session,
  ): Promise<void> => {
    const reg = getKitRegistryBridge();
    if (!reg) {
      throw new Error("[sketchpad] KitStoreProvider / KitRegistryProvider required (getKitRegistryBridge is null).");
    }
    if (reg.get(kitId)) {
      return;
    }
    const merged =
      wasmSession != null && init.store != null
        ? await this.registryOpenInit(init.store, wasmSession)
        : init;
    try {
      await reg.open(kitId, merged);
    } catch (e) {
      console.error(`[sketchpad] KitRegistry open failed for ${kitId}`, e);
      throw e;
    }
    const row = reg.get(kitId);
    if (!row) {
      throw new Error(`[sketchpad] registry open produced no row for ${kitId}`);
    }
    this.wireRegistryKitStore(row.store, kind, source);
  };

  private openJsonFileInRegistry = async (kitId: string, adapter: KitJsonFileAdapter, kind: KitKind, source?: InitialStateKit["source"]): Promise<void> => {
    const reg = getKitRegistryBridge();
    if (!reg) {
      throw new Error("[sketchpad] KitStoreProvider / KitRegistryProvider required (getKitRegistryBridge is null).");
    }
    if (reg.get(kitId)) {
      return;
    }
    await reg.openJsonFile(kitId, adapter);
    const row = reg.get(kitId);
    if (!row) {
      throw new Error(`[sketchpad] registry openJsonFile produced no row for ${kitId}`);
    }
    this.wireRegistryKitStore(row.store, kind, source);
  };

  supportedKitKinds = (): SketchpadKitKindAvailability => {
    const hasConfiguredKitStoreFactories = Boolean(this.temporaryKitStoreFactory || this.folderKitStoreFactory || this.fileKitStoreFactory || this.remoteKitStoreFactory);
    return {
      temporary: hasConfiguredKitStoreFactories ? Boolean(this.temporaryKitStoreFactory) : true,
      file: Boolean(this.fileKitStoreFactory),
      folder: Boolean(this.folderKitStoreFactory),
      remote: Boolean(this.remoteKitStoreFactory),
    };
  };

  /** 🧾 Open-toolbar: in-app memory kits only; file/folder/remote open use native pickers elsewhere. */
  availableKitKinds = (): SketchpadKitKindAvailability => ({
    temporary: true,
    file: false,
    folder: false,
    remote: false,
  });

  createKit = async (kit: Kit, kind?: KitKind, source?: InitialStateKit["source"], interactive: boolean = true, wasmSession?: Session): Promise<Id> => {
    const localKitStoreFactory = this.folderKitStoreFactory ?? this.fileKitStoreFactory;
    const regKind = kind ?? "temporary";

    if (regKind === "remote" && this.remoteKitStoreFactory) {
      const remoteKit = source?.kind === "remote" && source.url ? ({ ...kit, name: source.url } as Kit) : kit;
      const kitStore = await this.remoteKitStoreFactory(remoteKit);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, { store: kitStore }, "remote", source?.kind === "remote" ? source : undefined, wasmSession);
      return kid;
    }
    if (regKind === "folder" && this.folderKitStoreFactory && (interactive || source?.kind === "folder")) {
      const kitStore = await this.folderKitStoreFactory(Object.assign({}, kit, { __semioKitPersistenceSource: source }) as Kit);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, { store: kitStore }, "folder", source, wasmSession);
      return kid;
    }
    if (regKind === "file" && this.fileKitStoreFactory && (interactive || source?.kind === "file")) {
      const kitStore = await this.fileKitStoreFactory(Object.assign({}, kit, { __semioKitPersistenceSource: source }) as Kit);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, { store: kitStore }, "file", source, wasmSession);
      return kid;
    }
    if ((regKind === "folder" || regKind === "file") && !interactive) {
      await this.openKitInRegistry(kit.id, { backbone: { kind: "memory", initialKit: kit }, initialKit: kit as any }, regKind, source);
      return kit.id;
    }
    if (regKind === "temporary" && this.temporaryKitStoreFactory) {
      const kitStore = await this.temporaryKitStoreFactory(kit);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, { store: kitStore }, "temporary", undefined, wasmSession);
      return kid;
    }
    if (wasmSession != null) {
      const kitStore = this.temporaryKitStoreFactory ? await this.temporaryKitStoreFactory(kit) : new InMemoryKitStore(kit as Record<string, unknown>);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, await this.registryOpenInit(kitStore, wasmSession), "temporary", source, wasmSession);
      return kid;
    }
    if (regKind === "file" && !this.fileKitStoreFactory) {
      await this.openKitInRegistry(kit.id, { backbone: { kind: "memory", initialKit: kit }, initialKit: kit as any }, "temporary");
      return kit.id;
    }
    if (regKind === "folder" && !this.folderKitStoreFactory) {
      await this.openKitInRegistry(kit.id, { backbone: { kind: "memory", initialKit: kit }, initialKit: kit as any }, "temporary");
      return kit.id;
    }
    if (regKind === "remote" && !this.remoteKitStoreFactory) {
      await this.openKitInRegistry(kit.id, { backbone: { kind: "memory", initialKit: kit }, initialKit: kit as any }, "temporary");
      return kit.id;
    }
    if (interactive && localKitStoreFactory) {
      const inferredKind: KitKind = this.folderKitStoreFactory ? "folder" : "file";
      const kitStore = await localKitStoreFactory(kit);
      const kid = kitStore.getSnapshot().kit.id;
      await this.openKitInRegistry(kid, { store: kitStore }, inferredKind, undefined, wasmSession);
      return kid;
    }
    await this.openKitInRegistry(kit.id, { backbone: { kind: "memory", initialKit: kit }, initialKit: kit as any }, "temporary", undefined, wasmSession);
    return kit.id;
  };

  openKit = async (kind: string, serverUrl?: string): Promise<Id> => {
    const dummyKit: Kit = { id: id(), name: "", types: [], designs: [] };
    switch (kind) {
      case "folder": {
        const factory = this.folderKitStoreFactory;
        if (!factory) throw new Error("Folder kit store not available in this environment");
        const kitStore = await factory(dummyKit);
        await this.openKitInRegistry(kitStore.getSnapshot().kit.id, { store: kitStore }, "folder", this.getKitPersistenceSource(kitStore));
        return kitStore.getSnapshot().kit.id;
      }
      case "file": {
        const factory = this.fileKitStoreFactory;
        if (!factory) throw new Error("File kit store not available in this environment");
        const kitStore = await factory(dummyKit);
        await this.openKitInRegistry(kitStore.getSnapshot().kit.id, { store: kitStore }, "file", this.getKitPersistenceSource(kitStore));
        return kitStore.getSnapshot().kit.id;
      }
      case "remote": {
        const factory = this.remoteKitStoreFactory;
        if (!factory) throw new Error("Remote kit store not available in this environment");
        const remoteKit: Kit = { ...dummyKit, name: serverUrl ?? "" };
        const kitStore = await factory(remoteKit);
        await this.openKitInRegistry(kitStore.getSnapshot().kit.id, { store: kitStore }, "remote", this.getKitPersistenceSource(kitStore) ?? { kind: "remote", url: serverUrl ?? "" });
        return kitStore.getSnapshot().kit.id;
      }
      default:
        throw new Error(`Unknown kit kind for openKit: ${kind}`);
    }
  };

  private loadKitFilesFromPublic = async (kitId: string) => {
    try {
      const zipUrl = `/public/${kitId}.zip`;
      const response = await fetch(zipUrl);

      if (!response.ok) {
        return;
      }

      const blob = await response.blob();

      const JSZip = (await import("jszip")).default;
      const zip = await JSZip.loadAsync(blob);

      const filePromises: Promise<void>[] = [];
      zip.forEach((relativePath, zipEntry) => {
        if (!zipEntry.dir) {
          filePromises.push(
            zipEntry.async("blob").then(async (fileBlob) => {
              const file: SemioFile = {
                id: id(),
                name: relativePath.split("/").pop() || relativePath,
                size: fileBlob.size,
                hash: undefined,
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              };
              let loadKitStore: KitHostStore;
              try {
                loadKitStore = this.kitStore(kitId);
              } catch {
                return;
              }
              if (loadKitStore) await executeSemioKitCommand(loadKitStore, "semio.kit.addFile", "system.loadKitFiles", file, fileBlob);
            }),
          );
        }
      });

      await Promise.all(filePromises);
    } catch (error) {}
  };

  createKitApp = (kit: Id) => {
    this.syncDoc.transact(() => {
      const kitStore = this.kit(kit);
      let syncKitApp = this.syncKitApps.get(kit) as SyncMap<SyncKitAppVal>;
      if (!syncKitApp) {
        syncKitApp = createSyncDocFactory()().createMap<SyncKitAppVal>();
        this.syncKitApps.set(kit, syncKitApp);
      }
      const kitAppFactory = getKitAppStoreFactory();
      const kitAppInstance = kitAppFactory(this, syncKitApp, (fn: () => void) => this.syncDoc.transact(fn), { kit });
      this.kitApps.set(kit, kitAppInstance);
    });
    this.kitAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  createDesignApp = (kit: Id, design: Id) => {
    const designAppFactory = getDesignAppStoreFactory();
    const designApp = designAppFactory(this, { kit, design });

    let designAppsMap = this.designApps.get(kit);
    if (!designAppsMap) {
      designAppsMap = new Map();
      this.designApps.set(kit, designAppsMap);
    }
    designAppsMap.set(design, designApp);
    this.designAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  change(diff: SketchpadDiff) {
    if (this.actor) {
      this.actor.send({ type: "CHANGE", diff });
      return;
    }
    this.syncDoc.transact(() => {
      if (diff.navigationHistory !== undefined) {
        this.syncSketchpad.set("navigationHistory", JSON.stringify(diff.navigationHistory));
      }
      if (diff.navigationHistoryIndex !== undefined) {
        this.syncSketchpad.set("navigationHistoryIndex", diff.navigationHistoryIndex);
      }
      if (diff.navigation) {
        this.syncSketchpad.set("navigation", diff.navigation);
      }
      if ("recentSearches" in diff) {
        this.syncSketchpad.set("recentSearches", JSON.stringify(diff.recentSearches || []));
      }
      if ("recentFocusItems" in diff) {
        const current = JSON.parse((this.syncSketchpad.get("recentFocusItems") as string) || "{}");
        this.syncSketchpad.set("recentFocusItems", JSON.stringify({ ...current, ...(diff.recentFocusItems || {}) }));
      }
      if (diff.theme) this.syncSketchpad.set("theme", diff.theme);
      if (diff.language !== undefined) {
        this.syncSketchpad.set("language", diff.language);
      }
      if (diff.device) this.syncSketchpad.set("device", JSON.stringify(diff.device));
      if (diff.expertise) this.syncSketchpad.set("expertise", diff.expertise);
      if (diff.mode) this.syncSketchpad.set("mode", diff.mode);
      if (diff.isFullscreen !== undefined) this.syncSketchpad.set("isFullscreen", diff.isFullscreen);
      if (diff.isMobile !== undefined) this.syncSketchpad.set("isMobile", diff.isMobile);
      if ("activeInteraction" in diff) this.syncSketchpad.set("activeInteraction", diff.activeInteraction || "");
      if (diff.settings) {
        const current = JSON.parse((this.syncSketchpad.get("settings") as string) || "{}");
        const merged = { ...current, apps: { ...current.apps, ...diff.settings.apps } };
        this.syncSketchpad.set("settings", JSON.stringify(merged));
      }
      if (diff.panelSizes) {
        const current = JSON.parse((this.syncSketchpad.get("panelSizes") as string) || "{}");
        this.syncSketchpad.set("panelSizes", JSON.stringify({ ...current, ...diff.panelSizes }));
      }
      if (diff.hotkeyOverrides) {
        const current = JSON.parse((this.syncSketchpad.get("hotkeyOverrides") as string) || "{}");
        this.syncSketchpad.set("hotkeyOverrides", JSON.stringify({ ...current, ...diff.hotkeyOverrides }));
      }
      if ("activeHotkeySetting" in diff) this.syncSketchpad.set("activeHotkeySetting", diff.activeHotkeySetting || "");
    });
  }

  deleteKit = (id: Id) => {
    if (!this.hasKit(id)) {
      return;
    }
    this.syncDoc.transact(() => {
      const index = this.syncKits.toArray().findIndex((kitMeta) => kitMeta.get("id") === id);
      if (index !== -1) {
        this.syncKits.delete(index, 1);
      }
    });
    getKitRegistryBridge()?.close(id);
    this.schedulePersistKitsToStorage();
    this.kitDeletedSubscribers.forEach((subscriber) => subscriber());
    this.actor?.send({ type: "UI.OPEN_KIT.CLOSE", kitId: id } as any);
  };

  deleteKitApp = (kit: Id) => {
    const kitApp = this.kitApps.get(kit);
    if (kitApp) {
      this.kitApps.delete(kit);
      this.syncDoc.transact(() => {
        this.syncKitApps.delete(kit);
      });
      this.kitAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  deleteDesignApp = (kit: Id, design: Id) => {
    const designApp = this.designApps.get(kit)?.get(design);
    if (designApp) {
      this.designApps.get(kit)?.delete(design);
      if (this.designApps.get(kit)?.size === 0) {
        this.designApps.delete(kit);
      }
      this.designAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  onKitCreated = (callback: () => void): Unsubscribe => {
    this.kitCreatedSubscribers.add(callback);
    return () => {
      this.kitCreatedSubscribers.delete(callback);
    };
  };

  onKitAppCreated = (callback: () => void): Unsubscribe => {
    this.kitAppCreatedSubscribers.add(callback);
    return () => {
      this.kitAppCreatedSubscribers.delete(callback);
    };
  };

  onDesignAppCreated = (callback: () => void): Unsubscribe => {
    this.designAppCreatedSubscribers.add(callback);
    return () => {
      this.designAppCreatedSubscribers.delete(callback);
    };
  };

  onKitDeleted = (callback: () => void): Unsubscribe => {
    this.kitDeletedSubscribers.add(callback);
    return () => {
      this.kitDeletedSubscribers.delete(callback);
    };
  };

  onKitAppDeleted = (callback: () => void): Unsubscribe => {
    this.kitAppDeletedSubscribers.add(callback);
    return () => {
      this.kitAppDeletedSubscribers.delete(callback);
    };
  };

  onDesignAppDeleted = (callback: () => void): Unsubscribe => {
    this.designAppDeletedSubscribers.add(callback);
    return () => {
      this.designAppDeletedSubscribers.delete(callback);
    };
  };

  onChanged = (subscribe: Subscribe): Unsubscribe => {
    if (this.actor) {
      const subscription = this.actor.subscribe(() => {
        subscribe(() => {});
      });
      return () => subscription.unsubscribe();
    }
    return createObserver(this.syncSketchpad, subscribe);
  };

  onChangedDeep = (subscribe: Subscribe): Unsubscribe => {
    if (this.actor) {
      const subscription = this.actor.subscribe(() => {
        subscribe(() => {});
      });
      return () => subscription.unsubscribe();
    }
    return createObserver(this.syncSketchpad, subscribe, true);
  };

  async executeCommand<T>(command: string, ...args: any[]): Promise<T> {
    let origin: string | undefined;
    let rest: any[];

    if (typeof args[0] === "string" && args[0].startsWith("semio.sketchpad.")) {
      origin = args[0];
      rest = args.slice(1);
    } else {
      origin = undefined;
      rest = args;
    }

    this.tutorialStoreInstance.checkCommandCompletion(command, origin, rest);
    const tutorialState = this.tutorialStoreInstance.snapshot();
    if (tutorialState.recordingState === "recording") {
      this.tutorialStoreInstance.recordEvent({
        type: "command",
        data: { command, origin, args: rest },
      });
    }

    if (command === "semio.sketchpad.createKit") {
      const kit = rest[0] as Kit;
      const kindCandidate = rest[1] as unknown;
      const sourceCandidate = rest[2] as unknown;
      const interactiveCandidate = rest[3] as unknown;
      const kind = kindCandidate === "temporary" || kindCandidate === "file" || kindCandidate === "folder" || kindCandidate === "remote" ? kindCandidate : undefined;
      const source = sourceCandidate && typeof sourceCandidate === "object" && (sourceCandidate as { kind?: unknown }).kind ? (sourceCandidate as InitialStateKit["source"]) : undefined;
      const interactive = typeof interactiveCandidate === "boolean" ? interactiveCandidate : typeof sourceCandidate === "boolean" ? sourceCandidate : typeof kindCandidate === "boolean" ? kindCandidate : true;
      const wasmSession = rest[4] as Session | undefined;
      const kitId = await this.createKit(kit, kind, source, interactive, wasmSession);
      return { kitId } as T;
    }
    if (command === "semio.sketchpad.openKit") {
      const kind = rest[0] as string;
      const serverUrl = rest[1] as string | undefined;
      const kitId = await this.openKit(kind, serverUrl);
      return { kitId } as T;
    }
    if (command === "semio.sketchpad.createKitApp") {
      const id = rest[0] as KitAppId;
      this.createKitApp(id.kit);
      return {} as T;
    }
    if (command === "semio.sketchpad.createDesignApp") {
      const id = rest[0] as DesignAppId;
      this.createDesignApp(id.kit, id.design);
      return {} as T;
    }
    if (command === "semio.sketchpad.importKit") {
      const Id = rest[0] as Id;
      const url = rest[1] as string;
      if (this.hasKit(Id)) {
        const kitStore = this.kitStore(Id);
        await executeSemioKitCommand(kitStore, "semio.kit.import", origin, url);
      }
      return {} as T;
    }
    if (command === "semio.sketchpad.freeze") {
      const completeState = this.dumpState();
      const stateJson = JSON.stringify(completeState, null, 2);
      const blob = new Blob([stateJson], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `semio-freeze-${new Date().toISOString().replace(/[:.]/g, "-")}.json`;
      a.click();
      URL.revokeObjectURL(url);
      return {} as T;
    }
    if (command === "semio.sketchpad.timetravel") {
      const input = document.createElement("input");
      input.type = "file";
      input.accept = ".json";
      input.onchange = async (e: Event) => {
        const file = (e.target as HTMLInputElement).files?.[0];
        if (file) {
          const text = await file.text();
          const state = JSON.parse(text) as CompleteState;
          this.loadState(state);
        }
      };
      input.click();
      return {} as T;
    }
    if (command === "semio.sketchpad.copyJsonToClipboard") {
      const payload = rest.length > 1 ? rest[1] : undefined;
      let serializedState: unknown = payload;
      if (serializedState === undefined) {
        const navigation = this.snapshot().navigation ?? "";
        const activeKitId = navigation.match(/^\/kits\/([^/?#]+)/)?.[1] ?? navigation.match(/^\/kit\/([^/?#]+)/)?.[1];
        if (activeKitId && this.hasKit(activeKitId)) {
          serializedState = this.kit(activeKitId).getSnapshot().kit;
        } else {
          const reg = getKitRegistryBridge();
          const kitIds = new Set<string>(reg ? reg.list() : []);
          const firstId = kitIds.values().next().value as string | undefined;
          serializedState = firstId ? this.kitStore(firstId).getSnapshot().kit : {};
        }
      }
      const stateJson = JSON.stringify(serializedState, null, 2);
      if (typeof navigator !== "undefined" && navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
        await navigator.clipboard.writeText(stateJson);
        return {} as T;
      }
      const textarea = document.createElement("textarea");
      textarea.value = stateJson;
      textarea.style.position = "fixed";
      textarea.style.left = "-9999px";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      return {} as T;
    }
    const callback = this.commandRegistry.get(command);
    if (!callback) {
      throw new Error(`Command "${command}" not found in sketchpad store`);
    }
    const context: SketchpadCommandContext = {
      sketchpad: this.snapshot(),
      origin,
    };
    const result = callback(context, ...rest);
    if (result.diff) {
      this.change(result.diff);
    }
    return result as T;
  }

  execute<T>(command: string, ...rest: any[]): Promise<T> {
    return this.executeCommand(command, ...rest);
  }

  registerCommand(command: string, callback: (context: SketchpadCommandContext, ...rest: any[]) => SketchpadCommandResult, metadata?: { user?: boolean }): Disposable {
    this.commandRegistry.set(command, callback);
    if (metadata) {
      this.commandMetadata.set(command, metadata);
    }
    return () => {
      this.commandRegistry.delete(command);
      this.commandMetadata.delete(command);
    };
  }

  isUserCommand(command: string): boolean {
    const metadata = this.commandMetadata.get(command);
    return metadata?.user !== false;
  }

  get commands() {
    return {
      execute: this.executeCommand.bind(this),
      register: this.registerCommand.bind(this),
      isUserCommand: this.isUserCommand.bind(this),
    };
  }

  dumpState(): CompleteState {
    const sketchpad = this.snapshot();

    const reg = getKitRegistryBridge();
    const kitIdSet = new Set<string>(reg ? reg.list() : []);
    const kits = Array.from(kitIdSet, (id) => {
      const kitStore = this.kitStore(id);
      const persistenceKind = (kitStore as any).__semioKitPersistenceKind as KitKind | undefined;
      return {
        id,
        local: persistenceKind === "file" || persistenceKind === "folder" || persistenceKind === "remote",
        remote: persistenceKind === "remote",
        kit: kitStore.getSnapshot().kit,
      };
    });

    const kitApps: Record<string, any> = {};
    this.kitApps.forEach((app, id) => {
      kitApps[id] = app.snapshot();
    });

    const typeApps: Record<string, any> = {};
    this.typeApps.forEach((app, key) => {
      typeApps[key] = app.snapshot();
    });

    const qualityApps: Record<string, any> = {};
    this.qualityApps.forEach((app, key) => {
      qualityApps[key] = app.snapshot();
    });

    const designApps: Record<string, Record<string, any>> = {};
    this.designApps.forEach((designMap, kitId) => {
      designApps[kitId] = {};
      designMap.forEach((app, designId) => {
        designApps[kitId][designId] = app.snapshot();
      });
    });

    const home = this.homeStore?.snapshot();
    const tutorials = this.tutorialStoreInstance.snapshot();

    return {
      sketchpad,
      kits,
      kitApps,
      typeApps,
      qualityApps,
      designApps,
      home,
      tutorials,
    };
  }

  loadState(state: CompleteState): void {
    this.syncDoc.transact(() => {
      const reg = getKitRegistryBridge();
      if (reg) {
        for (const kid of [...reg.list()]) {
          reg.close(kid);
        }
      }
      this.kitApps.clear();
      this.typeApps.clear();
      this.qualityApps.clear();
      this.designApps.clear();

      this.syncKits.delete(0, this.syncKits.length);
      this.syncKitApps.forEach((_, key) => this.syncKitApps.delete(key));

      this.syncSketchpad.set("navigation", state.sketchpad.navigation);
      this.syncSketchpad.set("navigationHistory", JSON.stringify(state.sketchpad.navigationHistory));
      this.syncSketchpad.set("navigationHistoryIndex", state.sketchpad.navigationHistoryIndex);
      this.syncSketchpad.set("recentSearches", JSON.stringify(state.sketchpad.recentSearches));
      this.syncSketchpad.set("recentFocusItems", JSON.stringify(state.sketchpad.recentFocusItems));
      this.syncSketchpad.set("theme", state.sketchpad.theme);
      this.syncSketchpad.set("device", JSON.stringify(state.sketchpad.device));
      this.syncSketchpad.set("expertise", state.sketchpad.expertise);
      this.syncSketchpad.set("mode", state.sketchpad.mode);
      this.syncSketchpad.set("settings", JSON.stringify(state.sketchpad.settings));
      this.syncSketchpad.set("panelSizes", JSON.stringify(state.sketchpad.panelSizes));
      this.syncSketchpad.set("isFullscreen", state.sketchpad.isFullscreen);
      this.syncSketchpad.set("isMobile", state.sketchpad.isMobile);
      if (state.sketchpad.activeInteraction) {
        this.syncSketchpad.set("activeInteraction", state.sketchpad.activeInteraction);
      }
      if (state.sketchpad.hotkeyOverrides) {
        this.syncSketchpad.set("hotkeyOverrides", JSON.stringify(state.sketchpad.hotkeyOverrides));
      }
      if (state.sketchpad.activeHotkeySetting) {
        this.syncSketchpad.set("activeHotkeySetting", state.sketchpad.activeHotkeySetting);
      }

      state.kits.forEach(({ id, local, remote, kit }) => {
        const kind: KitKind = remote ? "remote" : local ? "file" : "temporary";
        void this.createKit(kit, kind);
        this.loadKitFilesFromPublic(kit.id);
      });

      Object.entries(state.kitApps).forEach(([id, appState]) => {
        this.createKitApp(id);
        const kitApp = this.kitApps.get(id);
        if (kitApp && kitApp.loadState) {
          kitApp.loadState(appState);
        }
      });

      Object.entries(state.typeApps).forEach(([key, appState]) => {
        const [kitId, typeId] = key.split(":");
        this.createTypeApp(kitId, typeId);
        const typeApp = this.typeApps.get(key);
        if (typeApp && typeApp.loadState) {
          typeApp.loadState(appState);
        }
      });

      Object.entries(state.qualityApps).forEach(([key, appState]) => {
        const [kitId, qualityId] = key.split(":");
        this.createQualityApp(kitId, qualityId);
        const qualityApp = this.qualityApps.get(key);
        if (qualityApp && qualityApp.loadState) {
          qualityApp.loadState(appState);
        }
      });

      Object.entries(state.designApps).forEach(([kitId, designs]) => {
        Object.entries(designs).forEach(([designId, appState]) => {
          this.createDesignApp(kitId, designId);
          const designApp = this.designApps.get(kitId)?.get(designId);
          if (designApp && designApp.loadState) {
            designApp.loadState(appState);
          }
        });
      });

      if (state.home && this.homeStore && this.homeStore.loadState) {
        this.homeStore.loadState(state.home);
      }

      if (state.tutorials && this.tutorialStoreInstance.loadState) {
        this.tutorialStoreInstance.loadState(state.tutorials);
      }
    });
  }

  hasKit(id: string): boolean {
    return Boolean(getKitRegistryBridge()?.get(id));
  }

  kit(id: string): KitHostStore {
    return this.kitStore(id);
  }

  kitStore(id: string): KitHostStore {
    const fromReg = getKitRegistryBridge()?.get(id)?.store;
    if (fromReg) {
      return fromReg;
    }
    throw new Error(`Kit with id ${id} not found`);
  }

  kits(): Kit[] {
    const reg = getKitRegistryBridge();
    const kitIds = new Set<string>(reg ? reg.list() : []);
    return Array.from(kitIds, (kid) => this.kitStore(kid).getSnapshot().kit as Kit);
  }

  hasKitApp(kitApp: KitAppId): boolean {
    /** 🧾 {@link Store.id} is a random sync-store id string; kit-app rows are keyed by kit uuid in {@link kitApps}. */
    return this.kitApps.has(kitApp.kit);
  }

  home(): HomeStoreInstance {
    if (!this.homeStore) {
      const homeFactory = resolveHomeStoreFactory();
      this.homeStore = homeFactory(this);
    }
    return this.homeStore;
  }

  tutorialStore(): TutorialStore {
    return this.tutorialStoreInstance;
  }

  kitApp(id: string): KitAppStoreInstance {
    let app = this.kitApps.get(id);
    if (!app) {
      if (!this.hasKit(id)) {
        throw new Error(`Cannot create kit app: Kit with id ${id} does not exist`);
      }
      this.createKitApp(id);
      app = this.kitApps.get(id)!;
    }
    return app;
  }

  kitAppIds(): KitAppId[] {
    return Array.from(this.kitApps.keys(), (kid) => ({ kit: kid }));
  }

  getAllKitApps(): KitAppStoreInstance[] {
    return Array.from(this.kitApps.values());
  }

  getAllDesignApps(): DesignAppStoreInstance[] {
    const allDesignApps: DesignAppStoreInstance[] = [];
    for (const kitMap of this.designApps.values()) {
      allDesignApps.push(...Array.from(kitMap.values()));
    }
    return allDesignApps;
  }

  createTypeApp = (kit: Id, type: Id) => {
    const id: TypeAppId = { kit, type };
    const key = `${kit}:${type}`;
    const typeAppFactory = getTypeAppStoreFactory();
    const typeApp = typeAppFactory(this, id);
    this.typeApps.set(key, typeApp);
    this.typeAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  deleteTypeApp = (kit: Id, type: Id) => {
    const key = `${kit}:${type}`;
    const typeApp = this.typeApps.get(key);
    if (typeApp) {
      this.typeApps.delete(key);
      this.typeAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  hasTypeApp(typeApp: TypeAppId): boolean {
    const key = `${typeApp.kit}:${typeApp.type}`;
    return this.typeApps.has(key);
  }

  typeApp(kit: Id, type: Id): TypeAppStoreInstance {
    const key = `${kit}:${type}`;
    let app = this.typeApps.get(key);
    if (!app) {
      this.createTypeApp(kit, type);
      app = this.typeApps.get(key)!;
    }
    return app;
  }

  typeAppIds(): TypeAppId[] {
    return Array.from(this.typeApps.values()).map((t) => ({ kit: t.id.kit, type: t.id.type }));
  }

  createQualityApp = (kit: Id, quality: Id) => {
    const Id: QualityAppId = { kit, quality };
    const key = `${kit}:${quality}`;
    const qualityAppFactory = getQualityAppStoreFactory();
    const qualityApp = qualityAppFactory(this, Id);
    this.qualityApps.set(key, qualityApp);
    this.qualityAppCreatedSubscribers.forEach((subscriber) => subscriber());
  };

  deleteQualityApp = (kit: Id, quality: Id) => {
    const key = `${kit}:${quality}`;
    const qualityApp = this.qualityApps.get(key);
    if (qualityApp) {
      this.qualityApps.delete(key);
      this.qualityAppDeletedSubscribers.forEach((subscriber) => subscriber());
    }
  };

  hasQualityApp(qualityApp: QualityAppId): boolean {
    const key = `${qualityApp.kit}:${qualityApp.quality}`;
    return this.qualityApps.has(key);
  }

  qualityApp(kit: Id, quality: Id): QualityAppStoreInstance {
    const key = `${kit}:${quality}`;
    let app = this.qualityApps.get(key);
    if (!app) {
      this.createQualityApp(kit, quality);
      app = this.qualityApps.get(key)!;
    }
    return app;
  }

  qualityAppIds(): QualityAppId[] {
    return Array.from(this.qualityApps.values()).map((q) => ({ kit: q.Id.kit, quality: q.Id.quality }));
  }

  hasDesignApp(designApp: DesignAppId): boolean {
    const allDesignApps: DesignAppStoreInstance[] = [];
    for (const kitMap of this.designApps.values()) {
      allDesignApps.push(...Array.from(kitMap.values()));
    }
    return hasSameDesignApp(
      designApp,
      allDesignApps.map((designApp) => designApp.id()),
    );
  }

  designApp(kitId: string, designId: string): DesignAppStoreInstance {
    let kitMap = this.designApps.get(kitId);
    if (!kitMap) {
      kitMap = new Map();
      this.designApps.set(kitId, kitMap);
    }
    let app = kitMap.get(designId);
    if (!app) {
      this.createDesignApp(kitId, designId);
      app = kitMap.get(designId)!;
    }
    return app;
  }

  designAppIds(): DesignAppId[] {
    const allDesignApps: DesignAppStoreInstance[] = [];
    for (const kitMap of this.designApps.values()) {
      allDesignApps.push(...Array.from(kitMap.values()));
    }
    return allDesignApps.map((d) => d.id());
  }

  private async loadPersistedKits() {
    if (this.persistence) {
      await new Promise<void>((resolve) => {
        this.persistence!.once("synced", () => resolve());
      });
    }
    // Kit list: `KitRegistryProvider` + `initialState.kits` / browser persistence — not Yjs `syncKits` (plan: hooks-only).
  }
}

SketchpadStore._loadModules();
/**
 * stores holds the data fields for a stores record.
 **/
let stores: Map<Id, SketchpadStore>;
if (import.meta.hot?.data.stores) {
  stores = import.meta.hot.data.stores;
} else {
  stores = new Map();
  if (import.meta.hot) {
    import.meta.hot.data.stores = stores;
  }
}
/**
 * actors holds the data fields for a actors record.
 **/
let actors: Map<Id, SketchpadActorRef>;
if (import.meta.hot?.data.actors) {
  actors = import.meta.hot.data.actors;
} else {
  actors = new Map();
  if (import.meta.hot) {
    import.meta.hot.data.actors = actors;
  }
}

/** @emoji 🏠 React context for the mounted sketchpad instance (id, remote, desktop). */
export const SketchpadInstanceContext = createContext<SketchpadInstance | null>(null);

/**
 * Startup shell shown while sketchpad state and app configuration are hydrating.
 * The root MUST never render as a visually empty white page during boot.
 **/
const SketchpadStartupFallback: FC = () => {
  return (
    <div id="semio.sketchpad.startup" className="flex h-screen w-screen items-center justify-center bg-base text-foreground">
      <div className="flex items-center gap-single">
        <Spinner id="semio.sketchpad.startup.spinner" />
        <span id="semio.sketchpad.startup.label">Loading sketchpad...</span>
      </div>
    </div>
  );
};

// #region 🌧️Sketchpad Instance Id
// Stable fallback instance ids for standalone sketchpad roots.

/**
 * Default instance id used when a sketchpad root is mounted without an explicit id.
 * A stable fallback keeps persisted state and kit snapshots addressable across reloads.
 **/
const DEFAULT_SKETCHPAD_INSTANCE_ID = "semio.sketchpad";

/**
 * Returns the deterministic fallback instance id for standalone sketchpad mounts.
 * Embedded or multi-root callers MUST pass an explicit id when isolation is required.
 **/
function getDefaultSketchpadInstanceId(): string {
  return DEFAULT_SKETCHPAD_INSTANCE_ID;
}
// #endregion 🌧️Sketchpad Instance Id

type SketchpadInstanceProviderProps = {
  id?: string;
  store?: SketchpadStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  folderKitStoreFactory?: SketchpadKitStoreFactory;
  fileKitStoreFactory?: SketchpadKitStoreFactory;
  remoteKitStoreFactory?: SketchpadKitStoreFactory;
  desktop?: Desktop;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  children: React.ReactNode;
};

/**
 * Mounts {@link SketchpadStore} only after {@link KitStoreProvider} is active (see {@link getKitRegistryBridge}).
 */
const SketchpadInstanceWithKitRegistry: FC<SketchpadInstanceProviderProps & { instanceId: string; hydratedInitialState: ExtendedInitialState | undefined; configsReady: boolean }> = (props) => {
  const {
    instanceId: id,
    hydratedInitialState: initialState,
    configsReady,
    children,
    importKitUrls,
    store: storeProp,
    remote,
    persistenceFactory,
    temporaryKitStoreFactory,
    folderKitStoreFactory,
    fileKitStoreFactory,
    remoteKitStoreFactory,
    desktop,
  } = props;

  if (!stores.has(id)) {
    const store = storeProp ?? new SketchpadStore(id, remote, initialState, persistenceFactory, temporaryKitStoreFactory, folderKitStoreFactory, fileKitStoreFactory, remoteKitStoreFactory, Boolean(desktop));
    stores.set(id, store);

    const actor = createSketchpadActor({ id, initialState: mergeSketchpadState(mergeSketchpadState(store.snapshot(), readSketchpadStateFromLocalStorage(id)), toSketchpadInitialState(initialState)) });
    actor.start();
    actors.set(id, actor);
    store.setActor(actor);

    if (typeof window !== "undefined") {
      (window as any).__SEMIO_STORE__ = store;
      (window as any).__SEMIO_ACTOR__ = actor;
      (window as any).__SEMIO_EXECUTE_SEMIO_KIT_COMMAND__ = executeSemioKitCommand;
      (window as any).__SEMIO_KIT_REGISTRY__ = getKitRegistryBridge;
    }
  }

  const actor = actors.get(id) ?? null;
  const store = stores.get(id) ?? null;

  useEffect(() => {
    if (!configsReady || !store || !importKitUrls || importKitUrls.length === 0) return;

    const doImportKits = async () => {
      for (const url of importKitUrls) {
        try {
          const { kit, session } = await importKit(url);

          await store.execute("semio.sketchpad.createKit", "semio.sketchpad.importKitUrls", kit, "temporary", undefined, false, session);
        } catch (error) {
          console.error(`[Sketchpad] Failed to auto-import kit from ${url}:`, error);
        }
      }
    };

    doImportKits();
  }, [configsReady, importKitUrls, store]);

  if (!actor || !store) {
    return <SketchpadStartupFallback />;
  }

  return React.createElement(
    SketchpadInstanceContext.Provider,
    { value: { id, remote: props.remote, desktop: props.desktop } },
    React.createElement(SketchpadActorContext.Provider, { value: actor }, configsReady ? children : React.createElement(SketchpadStartupFallback)),
  );
};

/**
 * React context provider initializing and scoping the sketchpad store and actor.
 **/
export const SketchpadInstanceProvider: FC<SketchpadInstanceProviderProps> = (props) => {
  const id = useMemo(() => props.id || getDefaultSketchpadInstanceId(), [props.id]);
  const [initialState, setInitialState] = useState<ExtendedInitialState | undefined>(props.initialState);
  const [persistedKitsReady, setPersistedKitsReady] = useState(false);
  const [configsReady, setConfigsReady] = useState(false);

  useEffect(() => {
    void loadAppConfigs()
      .then(() => setConfigsReady(true))
      .catch((err) => {
        console.error("[DEBUG] loadAppConfigs failed:", err);
        setConfigsReady(true);
      });
  }, []);

  useEffect(() => {
    let cancelled = false;
    const hydrateInitialState = async () => {
      try {
        let persistedKits: InitialStateKit[] | undefined;
        if (props.desktop) {
          clearSketchpadKitSnapshotsInBrowserStorage(id);
          persistedKits = undefined;
        } else {
          persistedKits = (await readSketchpadKitsFromIndexedDb(id)) ?? readSketchpadKitsFromLocalStorage(id);
        }
        if (cancelled) return;
        setInitialState(mergeExtendedInitialStateWithPersistedKits(props.initialState, persistedKits));
      } catch (err) {
        console.error("[DEBUG] hydrateInitialState failed:", err);
        if (!cancelled) {
          setInitialState(mergeExtendedInitialStateWithPersistedKits(props.initialState, undefined));
        }
      } finally {
        if (!cancelled) {
          setPersistedKitsReady(true);
        }
      }
    };
    void hydrateInitialState();
    return () => {
      cancelled = true;
    };
  }, [id, props.initialState, props.desktop]);

  if (!persistedKitsReady) {
    return <SketchpadStartupFallback />;
  }

  // Single {@link KitStoreProvider} lives in {@link Sketchpad} (outer shell). Nested providers
  // overwrite/clear {@link getKitRegistryBridge}'s module singleton on inner unmount and break registry opens.
  return React.createElement(SketchpadInstanceWithKitRegistry, {
    ...props,
    instanceId: id,
    hydratedInitialState: initialState,
    configsReady,
  });
};

/**
 * Hook returning the current sketchpad scope context.
 **/
export const useSketchpadInstance = () => useContext(SketchpadInstanceContext);

/**
 * Hook returning the sketchpad store instance for the current scope.
 **/
export function useSketchpadStore(id?: string): SketchpadStore {
  const scope = useSketchpadInstance();
  const storeId = scope?.id ?? id;
  if (!storeId) throw new Error("useSketchpadStore must be called within a SketchpadInstanceProvider or be directly provided with an id");
  if (!stores.has(storeId)) throw new Error(`Sketchpad store was not found for id ${storeId}`);
  const store = stores.get(storeId)!;
  return store;
}

/**
 * Hook returning the sketchpad state with optional selector.
 **/
export function useSketchpad<T>(selector?: (state: SketchpadState) => T, _id?: string): T | SketchpadState | null {
  const actor = useSketchpadActor();
  return useSelector(actor, (snapshot) => {
    const state = snapshot.context.sketchpad;
    return selector ? selector(state) : (state as unknown as T);
  });
}

/**
 * Hook returning the current navigation path from the router.
 **/
export function useNavigation(): string {
  const location = useLocation();
  return location.pathname;
}

/**
 * Hook returning the current app kind based on navigation path.
 **/
export function useAppType(): AppKind {
  const navigation = useNavigation();
  const [appsTick, setAppsTick] = useState(0);
  useEffect(() => {
    return appRegistry.subscribe(() => setAppsTick((t) => t + 1));
  }, []);
  return useMemo(() => {
    void appsTick;
    const pathParts = navigation.split("/").filter((p: string) => p);
    const app = appRegistry.getAppForPath(pathParts);
    return app?.id ?? "home";
  }, [navigation, appsTick]);
}

/**
 * Returns the app kind for a given navigation path.
 **/
export function getAppTypeFromPath(path: string): AppKind {
  const pathParts = path.split("/").filter((p) => p);
  const app = appRegistry.getAppForPath(pathParts);
  return app?.id ?? "home";
}

/**
 * Hook returning the current theme with setter.
 **/
export function useTheme(): HookResult<Theme> {
  const actor = useSketchpadActor();
  const value = useSelector(actor, (snapshot) => selectTheme(snapshot.context));
  const canSet = useSketchpadMachineCan(SKETCHPAD_CAPABILITY_PROBES.SET_THEME);
  const setter = useMemo(() => {
    if (!canSet) return undefined;
    return (theme: Theme) => actor.send({ type: "SET_THEME", theme });
  }, [actor, canSet]);
  return conditionalHookResult(canSet, value, setter);
}

/**
 * Hook returning the current language with setter.
 **/
export function useLanguage(): HookResult<string> {
  const actor = useSketchpadActor();
  const value = useSelector(actor, (snapshot) => selectLanguage(snapshot.context));
  const canSet = useSketchpadMachineCan(SKETCHPAD_CAPABILITY_PROBES.SET_LANGUAGE);
  const setter = useMemo(() => {
    if (!canSet) return undefined;
    return (language: string) => actor.send({ type: "SET_LANGUAGE", language });
  }, [actor, canSet]);
  return conditionalHookResult(canSet, value, setter);
}

