/** useAppPanelVisibility holds the data fields for a useAppPanelVisibility record.
 **/
export function useAppPanelVisibility(): PanelVisibility {
  const navigation = useNavigation();
  const appType = useAppType();
  const actor = useSketchpadActor();

  const pathMatch = navigation.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
  const kitId = pathMatch?.[1];
  const itemId = pathMatch?.[3];

  const selector = useMemo(() => {
    switch (appType) {
      case "home":
        return selectHomePanelVisibility;
      case "kit":
        if (kitId) return createKitPanelVisibilitySelector(kitId);
        return () => defaultPanelVisibility;
      case "design":
        if (kitId && itemId) return createDesignPanelVisibilitySelector(kitId, itemId);
        return () => defaultPanelVisibility;
      case "type":
        if (kitId && itemId) return createTypePanelVisibilitySelector(kitId, itemId);
        return () => defaultPanelVisibility;
      case "quality":
        if (kitId && itemId) return createQualityPanelVisibilitySelector(kitId, itemId);
        return () => defaultPanelVisibility;
      case "docs":
        return selectDocsAppPanelVisibility;
      case "feedback":
        return (snapshot: any) => snapshot.context.feedbackApp?.panelVisibility ?? defaultPanelVisibility;
      default:
        return () => defaultPanelVisibility;
    }
  }, [appType, kitId, itemId]);

  return useSelector(actor, selector);
}

/**
 * Hook returning command dispatchers for the current app.
 **/
export function useAppCommands() {
  const navigation = useNavigation();
  const appType = useAppType();
  const store = useSketchpadStore();
  const actor = useSketchpadActor();

  const pathMatch = navigation.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
  const kitId = pathMatch?.[1];
  const itemId = pathMatch?.[3];

  return useMemo(() => {
    switch (appType) {
      case "home":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            actor.send({ type: "HOME.TOGGLE_PANEL", panel: panelKey } as any);
          },
          execute: (_origin: string, _command: string, ..._args: any[]) => {},
        };
      case "kit":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            if (kitId) {
              actor.send({ type: "KIT.TOGGLE_PANEL", kitId, panel: panelKey } as any);
            }
          },
          execute: (origin: string, command: string, ...args: any[]) => {
            if (!kitId) return;
            try {
              const app = store.kitApp(kitId);
              return app?.execute(command, origin, ...args);
            } catch (e) {}
          },
        };
      case "design":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            if (kitId && itemId) {
              actor.send({ type: "DESIGN.TOGGLE_PANEL", kitId, designId: itemId, panel: panelKey } as any);
            }
          },
          execute: (origin: string, command: string, ...args: any[]) => {
            if (!kitId || !itemId) return;
            try {
              const app = store.designApp(kitId, itemId);
              return app?.execute(command, origin, ...args);
            } catch (e) {}
          },
        };
      case "type":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            if (kitId && itemId) {
              actor.send({ type: "TYPE.TOGGLE_PANEL", kitId, typeId: itemId, panel: panelKey } as any);
            }
          },
          execute: (origin: string, command: string, ...args: any[]) => {
            if (!kitId || !itemId) return;
            try {
              const app = store.typeApp(kitId, itemId);
              return app?.execute(command, origin, ...args);
            } catch (e) {}
          },
        };
      case "quality":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            if (kitId && itemId) {
              actor.send({ type: "QUALITY.TOGGLE_PANEL", kitId, qualityId: itemId, panel: panelKey } as any);
            }
          },
          execute: (origin: string, command: string, ...args: any[]) => {
            if (!kitId || !itemId) return;
            try {
              const app = store.qualityApp(kitId, itemId);
              return app?.execute(command, origin, ...args);
            } catch (e) {}
          },
        };
      case "docs":
        return {
          togglePanel: (_origin: string, panelKey: keyof PanelVisibility) => {
            actor.send({ type: "DOCS.TOGGLE_PANEL", panel: panelKey } as any);
          },
          execute: (_origin: string, _command: string, ..._args: any[]) => {},
        };
      default:
        return {
          togglePanel: (_origin: string, _panelKey: keyof PanelVisibility) => {},
          execute: (_origin: string, _command: string, ..._args: any[]) => {},
        };
    }
  }, [store, appType, kitId, itemId, actor]);
}

