// #region 🎁Apps Registry
// Dynamic app panel loader for registering app-specific panels.

// #region 📋AppPanelGlob
/** 🗂️ Vite-static glob map so esbuild can resolve optional `./apps/<id>/panels.ts` modules (no dynamic template imports). */
const appPanelLoaders = import.meta.glob<{ panels?: PanelConfig[] }>("./apps/*/panels.ts");
// #endregion 📋AppPanelGlob

/**
 * Loads panel configurations for a given app from the glob map (same optional modules as before).
 **/
export async function loadAppPanels(appId: string): Promise<PanelConfig[]> {
  const panelsModulePath = `./apps/${appId}/panels.ts`;
  const load = appPanelLoaders[panelsModulePath];
  if (!load) return [];
  try {
    const module = await load();
    return module.panels ?? [];
  } catch {
    return [];
  }
}

/** AppRegistry holds the data fields for a AppRegistry record.
 **/
/**
 **/
class AppRegistry {
  private apps: Map<string, AppRegistration> = new Map();
  private autoDiscovered = false;
  private _initialized = false;
  private listeners = new Set<() => void>();

  get isInitialized(): boolean {
    return this._initialized || this.apps.size > 0;
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private notify() {
    this.listeners.forEach((listener) => listener());
  }

  private async autoDiscover(): Promise<void> {
    if (this.autoDiscovered) return;
    this.autoDiscovered = true;

    const appModules = import.meta.glob<{ config: AppConfig }>("./apps/*/App.tsx");

    for (const [path, importFn] of Object.entries(appModules)) {
      const module = await importFn();
      if (module.config) {
        this.register(module.config);
      }
    }
  }

  register(registration: AppRegistration): void {
    if (this.apps.has(registration.id)) return;
    this.apps.set(registration.id, registration);
    this.cachedApps = null;
    this.notify();
  }

  unregister(id: string): void {
    this.apps.delete(id);
    this.cachedApps = null;
    this.notify();
  }

  getApp(id: string): AppRegistration | undefined {
    return this.apps.get(id);
  }

  private cachedApps: AppRegistration[] | null = null;

  getAllApps(): AppRegistration[] {
    if (!this.cachedApps) {
      this.cachedApps = Array.from(this.apps.values()).sort((a, b) => (a.order || 0) - (b.order || 0));
    }
    return this.cachedApps;
  }

  getAppForPath(pathParts: string[]): AppRegistration | undefined {
    const matches = this.getAllApps().filter((app) => app.matchesPath && app.matchesPath(pathParts));
    if (matches.length === 0) return undefined;
    return matches.sort((a, b) => {
      const aSegmentCount = a.routeSegments?.length || 0;
      const bSegmentCount = b.routeSegments?.length || 0;
      if (aSegmentCount !== bSegmentCount) {
        return bSegmentCount - aSegmentCount;
      }
      return (a.order || 0) - (b.order || 0);
    })[0];
  }

  getPanelConfigs(getLabelFn: (key: string) => string, getHotkeyFn?: (key: string) => string): Record<string, PanelDefinition[]> {
    const configs: Record<string, PanelDefinition[]> = {};
    for (const [id, app] of this.apps.entries()) {
      configs[id] = app.getPanels(getLabelFn, getHotkeyFn || getLabelFn);
    }
    return configs;
  }
  async initialize(): Promise<void> {
    if (this._initialized) return;
    await this.autoDiscover();
    await loadAppConfigs();
    this._initialized = true;
  }
}

/** appRegistry holds the data fields for a appRegistry record.
 **/
/**
 **/
const appRegistry = new AppRegistry();
/**
 * appConfigsLoadPromise holds the data fields for a appConfigsLoadPromise record.
 **/
let appConfigsLoadPromise: Promise<void> | null = null;
/**
 * loadAppConfigs holds the data fields for a loadAppConfigs record.
 **/
async function loadAppConfigs() {
  if (appConfigsLoadPromise) return appConfigsLoadPromise;
  appConfigsLoadPromise = (async () => {
    // ⚙️All modules are now consolidated in this file, register configs directly.
    const configs = [homeConfig, kitConfig, typeConfig, designConfig, docsConfig, feedbackConfig];
    for (const config of configs) {
      if (!config) continue;
      appRegistry.register(config as AppConfig);
    }
  })();

  return appConfigsLoadPromise;
}

export { appRegistry, loadAppConfigs };

// #endregion 🎁Apps Registry

// #region 🩺Navbar
// Focus / panel / footer / origin hooks backed by `sketchpadMachine` (`context.ui`).

const _emptyUiPanelSections: PanelSection[] = [];
const _emptyUiSideTabs: SidePanelTab[] = [];
const _emptyUiFooter: FooterItem[] = [];
const _emptyUiFocus: FocusItem[] = [];

/** Focus and navbar search integration (XState). */
export interface FocusApi {
  focusItems: FocusItem[];
  setFocusItems: (items: FocusItem[]) => void;
  setOnFocusItem: (callback: ((itemId: string) => void) | undefined) => void;
  triggerFocusItem: (itemId: string) => void;
}

/**
 * 🧭 Listens to pointer/keydown/focusin and updates `ui.origin` on the sketchpad actor. `pointerdown` is registered in the bubble phase so embedded canvases receive gestures before this handler runs.
 * Mount once under the sketchpad actor; renders nothing.
 */
export const OriginDocumentListener: FC = () => {
  const actor = useSketchpadActorSafe();
  useEffect(() => {
    if (!actor) return;
    const handler = (event: Event) => {
      actor.send({ type: "UI.ORIGIN.SET", origin: resolveOriginFromEventTarget(event.target) });
    };
    document.addEventListener("pointerdown", handler);
    document.addEventListener("keydown", handler, true);
    document.addEventListener("focusin", handler, true);
    return () => {
      document.removeEventListener("pointerdown", handler);
      document.removeEventListener("keydown", handler, true);
      document.removeEventListener("focusin", handler, true);
    };
  }, [actor]);
  return null;
};

export const useFocus = (): FocusApi => {
  const actor = useSketchpadActor();
  const focusItems = useSelector(actor, (snapshot) => snapshot.context.ui.focusItems);
  const setFocusItems = useCallback(
    (items: FocusItem[]) => {
      actor.send({ type: "UI.FOCUS.SET_ITEMS", items });
    },
    [actor],
  );
  const setOnFocusItem = useCallback(
    (callback: ((itemId: string) => void) | undefined) => {
      actor.send({ type: "UI.FOCUS.SET_HANDLER", handler: callback });
    },
    [actor],
  );
  const triggerFocusItem = useCallback(
    (itemId: string) => {
      actor.send({ type: "UI.FOCUS.TRIGGER", itemId });
    },
    [actor],
  );
  return useMemo(() => ({ focusItems, setFocusItems, setOnFocusItem, triggerFocusItem }), [focusItems, setFocusItems, setOnFocusItem, triggerFocusItem]);
};

export const useFocusSafe = (): FocusApi | null => {
  const actor = useSketchpadActorSafe();
  const [focusItems, setFocusItemsState] = useState<FocusItem[]>(_emptyUiFocus);
  useEffect(() => {
    if (!actor) {
      setFocusItemsState(_emptyUiFocus);
      return;
    }
    setFocusItemsState(actor.getSnapshot().context.ui.focusItems);
    const sub = actor.subscribe(() => {
      setFocusItemsState(actor.getSnapshot().context.ui.focusItems);
    });
    return () => sub.unsubscribe();
  }, [actor]);
  const setFocusItems = useCallback(
    (items: FocusItem[]) => {
      actor?.send({ type: "UI.FOCUS.SET_ITEMS", items });
    },
    [actor],
  );
  const setOnFocusItem = useCallback(
    (callback: ((itemId: string) => void) | undefined) => {
      actor?.send({ type: "UI.FOCUS.SET_HANDLER", handler: callback });
    },
    [actor],
  );
  const triggerFocusItem = useCallback(
    (itemId: string) => {
      actor?.send({ type: "UI.FOCUS.TRIGGER", itemId });
    },
    [actor],
  );
  return useMemo(() => {
    if (!actor) return null;
    return { focusItems, setFocusItems, setOnFocusItem, triggerFocusItem };
  }, [actor, focusItems, setFocusItems, setOnFocusItem, triggerFocusItem]);
};

