// #region 🎋ConceptFilter
// Filter component for narrowing results by architectural concepts.

/**
 * Component rendering a concept filter strip with toggle actions.
 **/
export const ConceptFilter: FC<{ allConcepts: string[]; paramName?: string }> = ({ allConcepts, paramName = "concepts" }) => {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedConcepts = paramName === "c" ? searchParams.getAll("c") : searchParams.get(paramName)?.split(",").filter(Boolean) || [];

  const toggleConcept = useCallback(
    (concept: string) => {
      const newParams = new URLSearchParams(searchParams);
      if (paramName === "c") {
        const currentConcepts = newParams.getAll("c");
        if (currentConcepts.includes(concept)) {
          newParams.delete("c");
          currentConcepts.filter((c) => c !== concept).forEach((c) => newParams.append("c", c));
        } else {
          newParams.append("c", concept);
        }
      } else {
        const currentConcepts = newParams.get(paramName)?.split(",").filter(Boolean) || [];
        if (currentConcepts.includes(concept)) {
          const updated = currentConcepts.filter((c) => c !== concept);
          if (updated.length > 0) {
            newParams.set(paramName, updated.join(","));
            newParams.delete(paramName);
          }
        } else {
          newParams.set(paramName, [...currentConcepts, concept].join(","));
        }
      }
      setSearchParams(newParams);
    },
    [searchParams, setSearchParams, paramName],
  );

  if (allConcepts.length === 0) return null;

  return (
    <Strip
      id="semio.sketchpad.filter.concepts"
      items={allConcepts.map((concept) => ({
        key: concept,
        content: <Action onClick={() => toggleConcept(concept)} id={`semio.sketchpad.filter.concept.${concept}`} text={concept} className={selectedConcepts.includes(concept) ? "bg-active-base" : ""} />,
      }))}
    />
  );
};

// #endregion 🎋ConceptFilter

// #region 🌍ToolGroup
// Toolbar group component for switching between tool modes.

/**
 * Component rendering a tool group with mode selection popover.
 **/
export const ToolGroup: FC<ToolGroupProps> = ({ tools, activeTool, onToolChange }) => {
  const getActiveToolDefinition = () => {
    for (const tool of tools) {
      const matchingMode = tool.modes.find((mode) => mode.id === activeTool);
      if (matchingMode) {
        return { tool, mode: matchingMode };
      }
    }
    return null;
  };

  const activeToolDef = getActiveToolDefinition();
  const currentTool = activeToolDef?.tool || tools[0];
  const currentMode = activeToolDef?.mode || currentTool.modes[0];

  const handleToolClick = (tool: (typeof tools)[0]) => {
    if (tool.modes.length === 1) {
      onToolChange(tool.modes[0].id);
    } else {
      const currentIndex = tool.modes.findIndex((m) => m.id === activeTool);
      const nextIndex = currentIndex >= 0 && currentIndex < tool.modes.length - 1 ? currentIndex + 1 : 0;
      onToolChange(tool.modes[nextIndex].id);
    }
  };

  const handleModeSelect = (modeId: string) => {
    onToolChange(modeId);
  };

  if (tools.length === 0) return null;

  return (
    <div className="flex items-center gap-single">
      {tools.map((tool) => {
        const isActive = tool.modes.some((m) => m.id === activeTool);
        const activeMode = tool.modes.find((m) => m.id === activeTool) || tool.modes[0];

        if (tool.modes.length > 1) {
          return (
            <Toggle
              key={tool.id}
              kind="dropdown"
              id={`semio.sketchpad.tool.${tool.id}`}
              items={tool.modes.map((mode) => ({
                value: mode.id,
                label: mode.icon || mode.label || mode.id,
              }))}
              value={activeMode.id}
              onValueChange={handleModeSelect}
              pressed={isActive}
              onPressedChange={(pressed) => {
                if (pressed) handleToolClick(tool);
              }}
            />
          );
        } else {
          const mode = tool.modes[0];
          return <Toggle key={tool.id} id={mode.tooltipId || `semio.sketchpad.tool.${mode.id}`} pressed={isActive} onPressedChange={() => handleToolClick(tool)} icon={mode.icon} />;
        }
      })}
    </div>
  );
};

// #endregion 🌍ToolGroup

// #region 🌥️DragDrop
/** Current drag-and-drop affordances for type/design placement (XState `ui.dragDrop`). */
export interface DragDropApi {
  activeDraggedType: Type | null;
  activeDraggedDesign: Design | null;
  setActiveDraggedType: (type: Type | null) => void;
  setActiveDraggedDesign: (design: Design | null) => void;
}

/**
 * @deprecated No-op; drag/drop state lives in `sketchpadMachine`.
 */
export const DragDropProvider: FC<{ children: ReactNode }> = ({ children }) => <>{children}</>;

export const useDragDrop = (): DragDropApi => {
  const actor = useSketchpadActor();
  const activeDraggedType = useSelector(actor, (snapshot) => snapshot.context.ui.dragDrop.activeType);
  const activeDraggedDesign = useSelector(actor, (snapshot) => snapshot.context.ui.dragDrop.activeDesign);
  const setActiveDraggedType = useCallback(
    (ty: Type | null) => {
      actor.send({ type: "UI.DRAGDROP.SET_TYPE", draggedType: ty });
    },
    [actor],
  );
  const setActiveDraggedDesign = useCallback(
    (design: Design | null) => {
      actor.send({ type: "UI.DRAGDROP.SET_DESIGN", draggedDesign: design });
    },
    [actor],
  );
  return useMemo(() => ({ activeDraggedType, activeDraggedDesign, setActiveDraggedType, setActiveDraggedDesign }), [activeDraggedType, activeDraggedDesign, setActiveDraggedType, setActiveDraggedDesign]);
};

// #endregion 🌥️DragDrop

// #region ⭐Hotkeys
// Keyboard shortcut hook with configurable hotkey overrides.

/**
 * Hook binding a keyboard shortcut with optional override resolution.
 **/
export function useHotkeys(hotkeyOrPath: string, callback: () => void, options?: { enableOnFormTags?: boolean }, deps?: React.DependencyList) {
  const hotkeyOverrides = useSketchpad((s) => s.hotkeyOverrides) as Record<string, string> | undefined;
  const translatedHotkey = useHotkey(hotkeyOrPath);

  useCommandHotkey(hotkeyOrPath, callback, options || {}, deps || [], {
    overrides: hotkeyOverrides,
    translatedHotkey,
  });
}

// #endregion ⭐Hotkeys

/**
 * Hook returning the enriched panel configurations for all panel definitions.
 **/
export function usePanelConfigs(): Record<string, EnrichedPanelDefinition[]> {
  const { t } = useI18nTranslation();

  const getHotkeyFn = useCallback(
    (id: string) => {
      const value = t(id as any) as any;
      if (typeof value === "object" && value?.hotkey) {
        return typeof value.hotkey === "string" ? value.hotkey : "";
      }
      const hotkeyValue = t(`${id}.hotkey` as any) as any;
      if (typeof hotkeyValue === "string") return hotkeyValue;
      if (hotkeyValue && typeof hotkeyValue === "object" && hotkeyValue.hotkey) {
        return typeof hotkeyValue.hotkey === "string" ? hotkeyValue.hotkey : "";
      }
      return "";
    },
    [t],
  );

  const [apps, setApps] = useState(() => appRegistry.getAllApps());
  useEffect(() => {
    setApps(appRegistry.getAllApps());
    return appRegistry.subscribe(() => setApps(appRegistry.getAllApps()));
  }, []);

  const panelConfigsByApp = useMemo(() => {
    const emptyLabelFn = () => "";
    const configs: Record<string, PanelDefinition[]> = {};
    for (const app of apps) {
      configs[app.id] = app.getPanels(emptyLabelFn, getHotkeyFn);
    }
    return configs;
  }, [apps, getHotkeyFn]);

  const allPanelIds = useMemo(() => {
    const ids: string[] = [];
    for (const panels of Object.values(panelConfigsByApp)) {
      panels.forEach((p) => ids.push(p.id));
    }
    return ids;
  }, [panelConfigsByApp]);

  const hotkeysMap = useMemo(() => {
    const map = new Map<string, string | undefined>();
    allPanelIds.forEach((id) => {
      const value = t(id as any) as any;
      let hotkey: string | undefined;
      if (typeof value === "object" && value?.hotkey) {
        hotkey = typeof value.hotkey === "string" ? value.hotkey : undefined;
      } else {
        const hotkeyValue = t(`${id}.hotkey` as any) as any;
        if (typeof hotkeyValue === "string") {
          hotkey = hotkeyValue;
        } else if (hotkeyValue && typeof hotkeyValue === "object" && hotkeyValue.hotkey) {
          hotkey = typeof hotkeyValue.hotkey === "string" ? hotkeyValue.hotkey : undefined;
        }
      }
      map.set(id, hotkey);
    });
    return map;
  }, [allPanelIds, t]);

  const enrich = (panels: PanelDefinition[]) =>
    panels.map((panel) => {
      const i18nHotkey = hotkeysMap.get(panel.id);
      const config = panelKindConfigs[panel.kind];
      return enrichPanelDefinition({
        ...panel,
        hotkey: panel.hotkey ?? i18nHotkey ?? config.hotkey,
      });
    });

  return useMemo(() => {
    const result: Record<string, EnrichedPanelDefinition[]> = {};
    for (const [appId, panels] of Object.entries(panelConfigsByApp)) {
      result[appId] = enrich(panels);
    }
    return result;
  }, [panelConfigsByApp, hotkeysMap]);
}

/** NavigationProps holds the data fields for a NavigationProps record.
 **/
/**
 **/
interface NavigationProps {
  mobile?: boolean;
}
/**
 * Navigation holds the data fields for a Navigation record.
 **/
const Navigation: FC<NavigationProps> = ({ mobile = false }) => {
  const navigate = useNavigate();
  const navigation = useNavigation();
  const [searchParams] = useSearchParams();
  const kits = useKits() ?? [];

  const [mode] = useMode();
  const isMobile = useIsMobile();
  const isNavbarExpanded = useIsNavbarExpanded();

  const pathParts = navigation.split("/").filter((p) => p);
  const isUuidPattern = (str: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str);
  const isKitsPath = pathParts[0] === "kits";

  const homeKind = !isKitsPath || pathParts.length === 1 ? (searchParams.get("kind") as KitKind | null) : null;
  const homeName = !isKitsPath || pathParts.length === 1 ? searchParams.get("name") : null;
  const homeVersion = !isKitsPath || pathParts.length === 1 ? searchParams.get("version") : null;

  const kitId = isKitsPath && pathParts[1] ? pathParts[1] : null;

  const secondPart = pathParts[2];
  const thirdPart = pathParts[3];
  const isDesignApp = isKitsPath && secondPart === "designs" && thirdPart && isUuidPattern(thirdPart);
  const isTypeApp = isKitsPath && secondPart === "types" && thirdPart && isUuidPattern(thirdPart);
  const itemId = isDesignApp || isTypeApp ? thirdPart : null;

  const filteredKind = kitId && !isDesignApp && !isTypeApp ? (searchParams.get("kind") as "designs" | "types" | "qualities" | "files" | "authors" | null) : null;
  const filteredName = kitId && !isDesignApp && !isTypeApp ? searchParams.get("name") : null;

  const isKitApp = kitId && !isDesignApp && !isTypeApp;

  const kitFromScope = useWipKitOptional();
  const designFromScope = useDesignContext();
  const typeFromScope = useTypeContext();
  const kit: Kit | null | undefined = (kitFromScope as Kit | null | undefined) ?? kits.find((k) => k.id === kitId);
  const kitKind = useKitKind(kitId || "");

  const kitKindItems = [
    { label: <TemporaryKitIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.temporary", href: "/?kind=temporary" },
    { label: <DocumentIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.file", href: "/?kind=file" },
    { label: <FolderIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.folder", href: "/?kind=folder" },
    { label: <RemoteKitIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.remote", href: "/?kind=remote" },
  ];

  const filteredKits = useFilteredKits(kitKind);
  const createKitLabel = useLabel("semio.sketchpad.navbar.createKit");
  const kitItemsWithCreate = useMemo(() => {
    const items = filteredKits.map((k) => ({ label: k.name, href: `/kits/${k.id}` }));
    items.push({ label: "+ " + createKitLabel, href: "#create-kit" });
    return items;
  }, [filteredKits, createKitLabel]);

  const sketchpadCommands = useSketchpadCommands();
  const { run: kitRun } = useKitCommand();
  const wipKit = useWipKitOptional();
  const kitDesignsLive = useKitDesigns();
  const kitTypesLive = useKitTypes();

  const artifactKinds = [
    { label: <LayoutIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.designs", kind: "designs", href: kitId ? `/kits/${kitId}?kind=designs` : "/kits?kind=designs" },
    { label: <TypeIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.types", kind: "types", href: kitId ? `/kits/${kitId}?kind=types` : "/kits?kind=types" },
    { label: <AwardIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.qualities", kind: "qualities", href: kitId ? `/kits/${kitId}?kind=qualities` : "/kits?kind=qualities" },
    { label: <DocumentIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.files", kind: "files", href: kitId ? `/kits/${kitId}?kind=files` : "/kits?kind=files" },
    { label: <UserIcon size={16} />, id: "semio.sketchpad.navbar.breadcrumb.authors", kind: "authors", href: kitId ? `/kits/${kitId}?kind=authors` : "/kits?kind=authors" },
  ];

  const allDesigns: Design[] = useMemo(() => {
    if (!kit?.designs) return [];
    return (kit.designs as any[]).filter((d): d is Design => typeof d === "object" && d.id !== undefined);
  }, [kit?.designs]);

  const allTypes: Type[] = useMemo(() => {
    if (!kit?.types) return [];
    return (kit.types as any[]).filter((t): t is Type => typeof t === "object" && t.id !== undefined);
  }, [kit?.types]);

  const allFolders: Folder[] = useMemo(() => {
    if (!kit?.folders) return [];
    return (kit.folders as any[]).filter((f): f is Folder => typeof f === "object" && f.id !== undefined);
  }, [kit?.folders]);

  const availableKitKinds = useAvailableKitKinds();
  const defaultCreateKitKind = useMemo((): KitKind => {
    if (availableKitKinds.temporary) return "temporary";
    if (availableKitKinds.file) return "file";
    if (availableKitKinds.folder) return "folder";
    if (availableKitKinds.remote) return "remote";
    return "temporary";
  }, [availableKitKinds]);

  const defaultKitName = useLabel("semio.sketchpad.app.kit.defaultName");
  const handleCreateKit = useCallback(
    (origin: string) => {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const existingNames = kits.map((k) => k.name);
      const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames);
      sketchpadCommands.createKit(
        origin,
        {
          id,
          name: uniqueName,
          version: "",
          createdAt: now,
          updatedAt: now,
        },
        defaultCreateKitKind,
      );
      sketchpadCommands.navigateToKit(id);
    },
    [sketchpadCommands, kits, defaultKitName, defaultCreateKitKind],
  );

  const newVersionLabel = useLabel("semio.sketchpad.app.kit.newVersion");
  const handleCreateVersion = useCallback(
    (origin: string) => {
      if (!kit) return;
      const newId = crypto.randomUUID();
      const now = new Date().toISOString();
      const existingVersions = kits.filter((k) => k.name === kit.name).map((k) => k.version || "");
      const uniqueVersion = generateUniqueName(newVersionLabel ?? "", existingVersions);
      sketchpadCommands.createKit(
        origin,
        {
          id: newId,
          name: kit.name,
          version: uniqueVersion,
          createdAt: now,
          updatedAt: now,
        },
        defaultCreateKitKind,
      );
      sketchpadCommands.navigateToKit(newId);
    },
    [kit, kits, sketchpadCommands, newVersionLabel, defaultCreateKitKind],
  );

  const defaultDesignName = useLabel("semio.sketchpad.app.design.defaultName");
  const resolveCreatedEntityId = useCallback(
    async (kind: "design" | "type", uniqueName: string, beforeCount: number): Promise<string | undefined> => {
      if (wipKit == null) return undefined;
      for (let attempt = 0; attempt < 40; attempt++) {
        const entities = kind === "design" ? await wipKit.designs() : await wipKit.types();
        if (entities.length > beforeCount) {
          for (const entity of entities) {
            if ((await entity.name()) === uniqueName) return entity.id;
          }
          return entities[entities.length - 1]?.id;
        }
        await new Promise((resolve) => setTimeout(resolve, 50));
      }
      return undefined;
    },
    [wipKit],
  );

  const handleCreateDesign = useCallback(
    async (_origin: string, name?: string, _parent?: string) => {
      if (!kitId || wipKit == null) return;
      const designNames = (kitDesignsLive.length > 0 ? kitDesignsLive : allDesigns).map((d) => d.name);
      const uniqueName = name || generateUniqueName(defaultDesignName ?? "", designNames);
      const before = (await wipKit.designs()).length;
      const res = await kitRun.createDesign(uniqueName);
      if (!res.ok) return;
      const createdId = await resolveCreatedEntityId("design", uniqueName, before);
      if (createdId) sketchpadCommands.navigateToDesign(kitId, createdId);
    },
    [kitRun, wipKit, kitId, sketchpadCommands, kitDesignsLive, allDesigns, defaultDesignName, resolveCreatedEntityId],
  );

  const defaultTypeName = useLabel("semio.sketchpad.app.type.defaultName");
  const handleCreateType = useCallback(
    async (_origin: string, name?: string, _parent?: string) => {
      if (!kitId || wipKit == null) return;
      const typeNames = (kitTypesLive.length > 0 ? kitTypesLive : allTypes).map((t) => t.name);
      const uniqueName = name || generateUniqueName(defaultTypeName ?? "", typeNames);
      const before = (await wipKit.types()).length;
      const res = await kitRun.createType(uniqueName);
      if (!res.ok) return;
      const createdId = await resolveCreatedEntityId("type", uniqueName, before);
      if (createdId) sketchpadCommands.navigateToType(kitId, createdId);
    },
    [kitRun, wipKit, kitId, sketchpadCommands, kitTypesLive, allTypes, defaultTypeName, resolveCreatedEntityId],
  );

  const handleCreateChild = useCallback(
    async (origin: string, designOrType: Design | Type, isType: boolean) => {
      if (isType) {
        const typeObj = designOrType as Type;
        const siblingNames = (kitTypesLive.length > 0 ? kitTypesLive : allTypes).filter((t) => t.parent?.id === typeObj.id).map((t) => t.name);
        await handleCreateType(origin, generateUniqueName(typeObj.name, siblingNames));
        return;
      }
      const d = designOrType as Design;
      const siblingNames = (kitDesignsLive.length > 0 ? kitDesignsLive : allDesigns).filter((design) => design.parent?.id === d.id).map((design) => design.name);
      await handleCreateDesign(origin, generateUniqueName(d.name, siblingNames));
    },
    [handleCreateDesign, handleCreateType, kitDesignsLive, kitTypesLive, allDesigns, allTypes],
  );

  const handleCreate = useCallback(
    (origin: string) => {
      if (!kit || !filteredKind) return;

      switch (filteredKind) {
        case "designs":
          void handleCreateDesign(origin);
          break;
        case "types":
          void handleCreateType(origin);
          break;
        case "authors":
        case "qualities":
        case "files":
          break;
      }
    },
    [kit, filteredKind, handleCreateDesign, handleCreateType],
  );

  const design = designFromScope || (isDesignApp ? allDesigns.find((d) => d.id === itemId) : undefined);
  const type = typeFromScope || (isTypeApp ? allTypes.find((t) => t.id === itemId) : undefined);
  const designFolderChain = useMemo(() => {
    if (!design || typeof design !== "object" || !("parent" in design)) return [];
    const designObj = design as Design;

    let rootDesign = designObj;
    while (rootDesign.parent) {
      const parent = allDesigns.find((d) => d.id === rootDesign.parent?.id);
      if (!parent) break;
      rootDesign = parent;
    }

    if (!rootDesign.folder) return [];

    const chain: Folder[] = [];
    let currentFolderId: string | undefined = rootDesign.folder;
    while (currentFolderId) {
      const folder = allFolders.find((f) => f.id === currentFolderId);
      if (!folder) break;
      chain.unshift(folder);
      currentFolderId = folder.parent?.id;
    }
    return chain;
  }, [design, allDesigns, allFolders]);

  const typeFolderChain = useMemo(() => {
    if (!type || typeof type !== "object" || !("parent" in type)) return [];
    const typeObj = type as Type;

    let rootType = typeObj;
    while (rootType.parent) {
      const parent = allTypes.find((t) => t.id === rootType.parent?.id);
      if (!parent) break;
      rootType = parent;
    }

    if (!rootType.folder) return [];

    const chain: Folder[] = [];
    let currentFolderId: string | undefined = rootType.folder;
    while (currentFolderId) {
      const folder = allFolders.find((f) => f.id === currentFolderId);
      if (!folder) break;
      chain.unshift(folder);
      currentFolderId = folder.parent?.id;
    }
    return chain;
  }, [type, allTypes, allFolders]);

  const designParentChain = useMemo(() => {
    if (!design || typeof design !== "object" || !("parent" in design)) return [];
    const designObj = design as Design;
    const chain: Design[] = [];
    let current: Design | undefined = designObj;
    while (current) {
      if (!current.parent) break;
      const parentId: string = current.parent.id;
      const parent: Design | undefined = allDesigns.find((d) => d.id === parentId);
      if (!parent) break;
      chain.unshift(parent);
      current = parent;
    }
    return chain;
  }, [design, allDesigns]);

  const typeParentChain = useMemo(() => {
    if (!type || typeof type !== "object" || !("parent" in type)) return [];
    const typeObj = type as Type;
    const chain: Type[] = [];
    let current: Type | undefined = typeObj;
    while (current) {
      if (!current.parent) break;
      const parentId: string = current.parent.id;
      const parent: Type | undefined = allTypes.find((t) => t.id === parentId);
      if (!parent) break;
      chain.unshift(parent);
      current = parent;
    }
    return chain;
  }, [type, allTypes]);

  const createDesignLabel = useLabel("semio.sketchpad.navbar.createDesign");
  const createChildLabel = useLabel("semio.sketchpad.navbar.createChild");
  const createTypeLabel = useLabel("semio.sketchpad.navbar.createType");
  const createVersionLabel = useLabel("semio.sketchpad.navbar.createVersion");
  const defaultVersionLabel = useLabel("semio.sketchpad.app.kit.defaultVersion");

  const designNameItems = useMemo(() => {
    const currentDesignId = design && typeof design === "object" && "id" in design ? (design as Design).id : undefined;
    const items = allDesigns
      .filter((d) => d.id !== currentDesignId)
      .map((d) => ({
        label: d.name,
        href: `/kits/${kitId}/designs/${d.id}`,
      }));
    items.push({ label: "+ " + createDesignLabel, href: "#create-design" });
    return items;
  }, [allDesigns, kitId, createDesignLabel, design]);

  const designParentChildItems = useMemo(() => {
    return designParentChain.map((parent) => {
      const children = allDesigns.filter((d) => d.parent?.id === parent.id);
      const items = children.map((d) => ({
        label: d.name,
        href: `/kits/${kitId}/designs/${d.id}`,
      }));
      items.push({ label: "+ " + createChildLabel, href: `#create-child-${parent.id}` });
      return { parentId: parent.id, items };
    });
  }, [designParentChain, allDesigns, kitId, createChildLabel]);

  const designChildItems = useMemo(() => {
    if (!design || typeof design !== "object" || !("id" in design)) return [];
    const designObj = design as Design;
    const children = allDesigns.filter((d) => d.parent?.id === designObj.id);
    const items = children.map((d) => ({
      label: d.name,
      href: `/kits/${kitId}/designs/${d.id}`,
    }));
    items.push({ label: "+ " + createChildLabel, href: "#create-child" });
    return items;
  }, [design, allDesigns, kitId, createChildLabel]);

  const typeNameItems = useMemo(() => {
    const currentTypeId = type && typeof type === "object" && "id" in type ? (type as Type).id : undefined;
    const items = allTypes
      .filter((t) => t.id !== currentTypeId)
      .map((t) => ({
        label: t.name,
        href: `/kits/${kitId}/types/${t.id}`,
      }));
    items.push({ label: "+ " + createTypeLabel, href: "#create-type" });
    return items;
  }, [allTypes, kitId, createTypeLabel, type]);

  const typeParentChildItems = useMemo(() => {
    return typeParentChain.map((parent) => {
      const children = allTypes.filter((t) => t.parent?.id === parent.id);
      const items = children.map((t) => ({
        label: t.name,
        href: `/kits/${kitId}/types/${t.id}`,
      }));
      items.push({ label: "+ " + createChildLabel, href: `#create-child-${parent.id}` });
      return { parentId: parent.id, items };
    });
  }, [typeParentChain, allTypes, kitId, createChildLabel]);

  const typeChildItems = useMemo(() => {
    if (!type || typeof type !== "object" || !("id" in type)) return [];
    const typeObj = type as Type;
    const children = allTypes.filter((t) => t.parent?.id === typeObj.id);
    const items = children.map((typeObj) => ({
      label: typeObj.name,
      href: `/kits/${kitId}/types/${typeObj.id}`,
    }));
    items.push({ label: "+ " + createChildLabel, href: "#create-child" });
    return items;
  }, [type, allTypes, kitId, createChildLabel]);

  const kitVersionItems = useMemo(() => {
    if (!kit?.name) return [];
    const sameNameKits = kits.filter((k) => k.name === kit.name && k.id !== kitId);
    const items = sameNameKits.map((k) => ({
      label: k.version || <span className="italic opacity-70">{defaultVersionLabel}</span>,
      href: `/kits/${k.id}`,
    }));
    items.push({ label: "+ " + createVersionLabel, href: "#create-version" });
    return items;
  }, [kit, kits, defaultVersionLabel, createVersionLabel, kitId]);

  const homeKitsByKind = useFilteredKits(homeKind || undefined);
  const homeKitsForKind = useMemo(() => {
    if (!homeKind) return [];
    const items = homeKitsByKind
      .filter((k) => k.name !== homeName)
      .map((k) => ({
        label: k.name,
        href: `/?kind=${homeKind}&name=${encodeURIComponent(k.name)}`,
      }));
    items.push({ label: "+ " + createKitLabel, href: "#create-kit" });
    return items;
  }, [homeKind, homeKitsByKind, createKitLabel, homeName]);

  const homeVersionsForName = useMemo(() => {
    if (!homeName || !homeKind) return [];
    return homeKitsByKind
      .filter((k) => k.name === homeName && k.id !== kitId)
      .map((k) => ({
        label: k.version || <span className="italic opacity-70">{defaultVersionLabel}</span>,
        href: `/kits/${k.id}`,
      }));
  }, [homeName, homeKind, homeKitsByKind, defaultVersionLabel, kitId]);

  const filteredNameItems = useMemo(() => {
    if (!kit || !filteredKind) return [];
    const nameSet = new Set<string>();

    if (filteredKind === "designs") {
      allDesigns.forEach((d) => nameSet.add(d.name));
    } else if (filteredKind === "types") {
      allTypes.forEach((t) => nameSet.add(t.name));
    }

    return Array.from(nameSet).map((name) => ({
      label: name,
      href: `/kits/${kitId}?kind=${filteredKind}&name=${encodeURIComponent(name)}`,
    }));
  }, [kit, filteredKind, allDesigns, allTypes, kitId]);

  const isAtRoot = navigation === "/";
  const hasKindFilter = filteredKind || (kitId && kitKind);

  const breadcrumbItems: Array<{ id?: string; content: React.ReactNode; options?: any[]; onNavigate?: (href: string) => void }> = [];

  breadcrumbItems.push({
    id: "semio.sketchpad.navbar.home",
    content: (
      <a onClick={() => navigate("/")} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
        <HomeIcon size={16} />
      </a>
    ),
    options: kitKindItems,
    onNavigate: (href) => navigate(href),
  });

  if (kitId || homeKind) {
    if (kitKind || homeKind) {
      breadcrumbItems.push({
        id: `semio.sketchpad.navbar.breadcrumb.${kitKind || homeKind}`,
        content: (
          <a onClick={() => navigate(`/?kind=${kitKind || homeKind}`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
            {(kitKind === "temporary" || homeKind === "temporary") && <TemporaryKitIcon size={16} />}
            {(kitKind === "file" || homeKind === "file") && <DocumentIcon size={16} />}
            {(kitKind === "folder" || homeKind === "folder") && <FolderIcon size={16} />}
            {(kitKind === "remote" || homeKind === "remote") && <RemoteKitIcon size={16} />}
          </a>
        ),
        options: kitId ? kitItemsWithCreate : homeKitsForKind,
        onNavigate: (href) => {
          if (href === "#create-kit") handleCreateKit("semio.sketchpad.navbar.kits");
          else navigate(href);
        },
      });
    }

    if (homeName) {
      const kindIndex = breadcrumbItems.findIndex((item) => item.id === `semio.sketchpad.navbar.breadcrumb.${kitKind || homeKind}`);
      if (kindIndex !== -1) {
        breadcrumbItems[kindIndex] = {
          ...breadcrumbItems[kindIndex],
          options: homeKitsForKind,
          onNavigate: (href) => {
            if (href === "#create-kit") handleCreateKit("semio.sketchpad.navbar.kits");
            else navigate(href);
          },
        };
      }

      breadcrumbItems.push({
        id: "semio.sketchpad.navbar.kitName",
        content: (
          <a onClick={() => navigate(`/?kind=${homeKind}&name=${encodeURIComponent(homeName)}`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
            {homeName}
          </a>
        ),
        options: homeVersionsForName,
        onNavigate: (href) => navigate(href),
      });
      if (homeVersion !== null) {
        breadcrumbItems.push({
          id: "semio.sketchpad.navbar.kitVersion",
          content: <span className="text-foreground px-single flex items-center gap-single h-full">{homeVersion || <span className="italic opacity-70">{defaultVersionLabel}</span>}</span>,
        });
      }
    }

    if (kitId) {
      const existingNameIndex = breadcrumbItems.findIndex((item) => item.id === "semio.sketchpad.navbar.kitName");
      if (existingNameIndex === -1) {
        const kindIndex = breadcrumbItems.findIndex((item) => item.id === `semio.sketchpad.navbar.breadcrumb.${kitKind || homeKind}`);
        if (kindIndex !== -1) {
          breadcrumbItems[kindIndex] = {
            ...breadcrumbItems[kindIndex],
            options: kitItemsWithCreate,
            onNavigate: (href) => {
              if (href === "#create-kit") handleCreateKit("semio.sketchpad.navbar.kits");
              else navigate(href);
            },
          };
        }

        breadcrumbItems.push({
          id: "semio.sketchpad.navbar.kitName",
          content: (
            <a
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                navigate(`/?kind=${kitKind}&name=${encodeURIComponent(kit?.name || "")}`);
              }}
              className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
            >
              {kit?.name || kitId}
            </a>
          ),
          options: kitVersionItems,
          onNavigate: (href) => {
            if (href === "#create-version") handleCreateVersion("semio.sketchpad.navbar.versions");
            else navigate(href);
          },
        });
      } else {
        breadcrumbItems[existingNameIndex] = {
          ...breadcrumbItems[existingNameIndex],
          options: kitVersionItems,
          onNavigate: (href) => {
            if (href === "#create-version") handleCreateVersion("semio.sketchpad.navbar.versions");
            else navigate(href);
          },
        };
      }

      const existingVersionIndex = breadcrumbItems.findIndex((item) => item.id === "semio.sketchpad.navbar.kitVersion");
      if (existingVersionIndex === -1) {
        breadcrumbItems.push({
          id: "semio.sketchpad.navbar.kitVersion",
          content: (
            <a
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                const versionParam = kit?.version !== undefined ? `&version=${encodeURIComponent(kit.version)}` : "";
                navigate(`/?kind=${kitKind}&name=${encodeURIComponent(kit?.name || "")}${versionParam}`);
              }}
              className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
            >
              {kit?.version || <span className="italic opacity-70">{defaultVersionLabel}</span>}
            </a>
          ),
          options: artifactKinds,
          onNavigate: (href) => navigate(href),
        });
      }
    }
  }

  if (isKitApp && filteredKind) {
    const versionIndex = breadcrumbItems.findIndex((item) => item.id === "semio.sketchpad.navbar.kitVersion");
    if (versionIndex !== -1) {
      breadcrumbItems[versionIndex] = {
        ...breadcrumbItems[versionIndex],
        options: artifactKinds,
        onNavigate: (href) => navigate(href),
      };
    }

    breadcrumbItems.push({
      id: `semio.sketchpad.navbar.breadcrumb.${filteredKind}`,
      content: (
        <a onClick={() => navigate(`/kits/${kitId}?kind=${filteredKind}`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
          {filteredKind === "designs" && <LayoutIcon size={16} />}
          {filteredKind === "types" && <TypeIcon size={16} />}
          {filteredKind === "qualities" && <AwardIcon size={16} />}
          {filteredKind === "files" && <DocumentIcon size={16} />}
          {filteredKind === "authors" && <UserIcon size={16} />}
        </a>
      ),
      options: filteredKind === "designs" ? designNameItems : filteredKind === "types" ? typeNameItems : undefined,
      onNavigate: (href) => {
        if (href === "#create-design" && filteredKind === "designs") handleCreateDesign("semio.sketchpad.navbar.selectDesign");
        else if (href === "#create-type" && filteredKind === "types") handleCreateType("semio.sketchpad.navbar.selectType");
        else navigate(href);
      },
    });
    if (filteredName !== null) {
      breadcrumbItems.push({
        id: "semio.sketchpad.navbar.name",
        content: (
          <a
            onClick={() => {
              const firstMatchingDesign = (kit?.designs as any[])?.find((d: any) => d.name === filteredName);
              if (firstMatchingDesign) {
                navigate(`/kits/${kitId}?kind=${filteredKind}&name=${encodeURIComponent(filteredName)}&select=${firstMatchingDesign.id}`);
              }
            }}
            className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
          >
            {filteredName}
          </a>
        ),
        options: filteredNameItems,
        onNavigate: (href) => navigate(href),
      });
    }
  }

  if (isDesignApp && design) {
    const versionIndex = breadcrumbItems.findIndex((item) => item.id === "semio.sketchpad.navbar.kitVersion");
    if (versionIndex !== -1) {
      breadcrumbItems[versionIndex] = {
        ...breadcrumbItems[versionIndex],
        options: artifactKinds,
        onNavigate: (href) => navigate(href),
      };
    }

    breadcrumbItems.push({
      id: "semio.sketchpad.navbar.breadcrumb.designs",
      content: (
        <a onClick={() => navigate(`/kits/${kitId}?kind=designs`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
          <LayoutIcon size={16} />
        </a>
      ),
      options: designNameItems,
      onNavigate: (href) => {
        if (href === "#create-design") handleCreateDesign("semio.sketchpad.navbar.selectDesign");
        else navigate(href);
      },
    });
    designFolderChain.forEach((folder) => {
      breadcrumbItems.push({
        id: `semio.sketchpad.navbar.folder.${folder.id}`,
        content: (
          <a onClick={() => navigate(`/kits/${kitId}?kind=folders`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
            {folder.name}
          </a>
        ),
      });
    });
    designParentChain.forEach((parent, index) => {
      const childItems = designParentChildItems.find((s) => s.parentId === parent.id)?.items || [];
      breadcrumbItems.push({
        id: `semio.sketchpad.navbar.design.parent.${parent.id}`,
        content: (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              navigate(`/kits/${kitId}/designs/${parent.id}`);
            }}
            className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
          >
            {parent.name}
          </button>
        ),
        options: childItems,
        onNavigate: (href) => {
          if (href.startsWith("#create-child-")) {
            handleCreateChild(`semio.sketchpad.navbar.design.parent.${parent.id}`, parent, false);
          } else {
            navigate(href);
          }
        },
      });
    });

    breadcrumbItems.push({
      id: "semio.sketchpad.navbar.design",
      content: (
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            if (design && typeof design === "object" && "name" in design && "id" in design) {
              const designObj = design as Design;
              navigate(`/kits/${kitId}?kind=designs&name=${encodeURIComponent(designObj.name)}&select=${designObj.id}`);
            }
          }}
          className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
        >
          {design && typeof design === "object" && "name" in design ? String((design as Design).name) : ""}
        </button>
      ),
      options: designChildItems,
      onNavigate: (href) => {
        if (href === "#create-child" && design && typeof design === "object" && "id" in design) {
          handleCreateChild("semio.sketchpad.navbar.design", design as Design, false);
        } else navigate(href);
      },
    });
  }

  if (isTypeApp && type) {
    const versionIndex = breadcrumbItems.findIndex((item) => item.id === "semio.sketchpad.navbar.kitVersion");
    if (versionIndex !== -1) {
      breadcrumbItems[versionIndex] = {
        ...breadcrumbItems[versionIndex],
        options: artifactKinds,
        onNavigate: (href) => navigate(href),
      };
    }

    breadcrumbItems.push({
      id: "semio.sketchpad.navbar.breadcrumb.types",
      content: (
        <a onClick={() => navigate(`/kits/${kitId}?kind=types`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
          <TypeIcon size={16} />
        </a>
      ),
      options: typeNameItems,
      onNavigate: (href) => {
        if (href === "#create-type") handleCreateType("semio.sketchpad.navbar.selectType");
        else navigate(href);
      },
    });
    typeFolderChain.forEach((folder) => {
      breadcrumbItems.push({
        id: `semio.sketchpad.navbar.folder.${folder.id}`,
        content: (
          <a onClick={() => navigate(`/kits/${kitId}?kind=folders`)} className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable">
            {folder.name}
          </a>
        ),
      });
    });

    typeParentChain.forEach((parent, index) => {
      const childItems = typeParentChildItems.find((s) => s.parentId === parent.id)?.items || [];
      breadcrumbItems.push({
        id: `semio.sketchpad.navbar.type.parent.${parent.id}`,
        content: (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              navigate(`/kits/${kitId}/types/${parent.id}`);
            }}
            className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
          >
            {parent.name}
          </button>
        ),
        options: childItems,
        onNavigate: (href) => {
          if (href.startsWith("#create-child-")) {
            handleCreateChild(`semio.sketchpad.navbar.type.parent.${parent.id}`, parent, true);
          } else {
            navigate(href);
          }
        },
      });
    });

    breadcrumbItems.push({
      id: "semio.sketchpad.navbar.type",
      content: (
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            if (type && typeof type === "object" && "name" in type && "id" in type) {
              const typeObj = type as Type;
              navigate(`/kits/${kitId}?kind=types&name=${encodeURIComponent(typeObj.name)}&select=${typeObj.id}`);
            }
          }}
          className="text-foreground transition-colors px-single flex items-center gap-single h-full hover:bg-hover-base cursor-selectable"
        >
          {type && typeof type === "object" && "name" in type ? String((type as Type).name) : ""}
        </button>
      ),
      options: typeChildItems,
      onNavigate: (href) => {
        if (href === "#create-child" && type && typeof type === "object" && "id" in type) {
          handleCreateChild("semio.sketchpad.navbar.type", type as Type, true);
        } else navigate(href);
      },
    });
  }

  return <Breadcrumb className="flex-1 min-w-0" items={breadcrumbItems} />;
};
/**
 * SearchResult holds the data fields for a SearchResult record.
 **/
type SearchResult = {
  type: "kit" | "design" | "type" | "quality" | "tutorial";
  item: Kit | Design | Type | Quality | { id: string; name: string; description?: string };
  kitId?: string;
};
/**
 * buildSearchResultPath holds the data fields for a buildSearchResultPath record.
 **/
const buildSearchResultPath = (result: SearchResult): string => {
  if (result.type === "kit") return `/kits/${(result.item as Kit).id}`;
  if (result.type === "design") return `/kits/${result.kitId}/designs/${(result.item as Design).id}`;
  if (result.type === "type") return `/kits/${result.kitId}/types/${(result.item as Type).id}`;
  if (result.type === "quality") return `/kits/${result.kitId}?kind=qualities&select=${(result.item as Quality).id}`;
  if (result.type === "tutorial") return `/?tutorial=${(result.item as { id: string }).id}`;
  return "";
};

const Search: FC = ({}) => {
  const navigate = useNavigate();
  const recentSearches = (useSketchpad((s) => s.recentSearches) as string[]) || [];
  const updateRecentSearches = useUpdateRecentSearches();
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const kits = useKits() ?? [];
  const tutorials = useAvailableTutorials();
  useEffect(() => {
    const handler = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "p") {
        const activeElement = document.activeElement as HTMLElement | null;
        if (!open && activeElement && (activeElement.tagName === "INPUT" || activeElement.tagName === "TEXTAREA" || activeElement.isContentEditable)) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        setOpen((prev) => !prev);
      }
    };
    window.addEventListener("keydown", handler, true);
    return () => window.removeEventListener("keydown", handler, true);
  }, [open, setOpen]);

  const searchData = useMemo(() => {
    const results: SearchResult[] = [];
    kits.forEach((kit) => {
      results.push({ type: "kit", item: kit as Kit, kitId: kit.id });
      (kit.designs || []).forEach((design) => {
        if (typeof design === "object") results.push({ type: "design", item: design as Design, kitId: kit.id });
      });
      (kit.types || []).forEach((type) => {
        if (typeof type === "object") results.push({ type: "type", item: type as Type, kitId: kit.id });
      });
      (kit.qualities || []).forEach((quality) => {
        if (typeof quality === "object") results.push({ type: "quality", item: quality as Quality, kitId: kit.id });
      });
    });
    tutorials.forEach((tutorial) => {
      results.push({ type: "tutorial", item: { id: tutorial.id, name: tutorial.name, description: tutorial.description } });
    });
    return results;
  }, [kits, tutorials]);

  const searchIndex = useMemo(() => {
    const map = new Map<string, SearchResult>();
    searchData.forEach((result) => {
      const path = buildSearchResultPath(result);
      if (path) map.set(path, result);
    });
    return map;
  }, [searchData]);

  const fuse = useMemo(
    () =>
      new Fuse(searchData, {
        keys: [
          { name: "item.name", weight: 2 },
          { name: "item.title", weight: 2 },
          { name: "item.description", weight: 0.5 },
          { name: "item.key", weight: 1.5 },
          { name: "item.path", weight: 1 },
        ],
        threshold: 0.4,
        includeScore: true,
      }),
    [searchData],
  );

  const recentResults = useMemo(() => {
    return recentSearches.map((path) => searchIndex.get(path)).filter((result): result is SearchResult => !!result);
  }, [recentSearches, searchIndex]);

  const searchResults = useMemo(() => {
    if (query.trim()) return fuse.search(query).slice(0, 20);

    const base = recentResults.length > 0 ? recentResults : searchData.slice(0, 20);
    return base.map((item, idx) => ({ item, refIndex: idx }) as FuseResult<SearchResult>);
  }, [fuse, query, recentResults, searchData]);

  const groupedSearchResults = useMemo(() => {
    return {
      tutorials: searchResults.filter((r: FuseResult<SearchResult>) => r.item.type === "tutorial"),
      kits: searchResults.filter((r: FuseResult<SearchResult>) => r.item.type === "kit"),
      designs: searchResults.filter((r: FuseResult<SearchResult>) => r.item.type === "design"),
      types: searchResults.filter((r: FuseResult<SearchResult>) => r.item.type === "type"),
      qualities: searchResults.filter((r: FuseResult<SearchResult>) => r.item.type === "quality"),
    };
  }, [searchResults]);

  const store = useSketchpadStore();
  const tutorialStore = store.tutorialStore();

  const handleSelect = useCallback(
    (result: SearchResult) => {
      const path = buildSearchResultPath(result);
      if (path) {
        const next = [path, ...recentSearches.filter((entry) => entry !== path)].slice(0, 20);
        const changed = next.length !== recentSearches.length || next.some((entry, index) => entry !== recentSearches[index]);
        if (changed) updateRecentSearches(next);
      }
      setOpen(false);
      setQuery("");

      if (result.type === "tutorial") {
        const tutorial = result.item as Tutorial;
        tutorialStore.startTutorial(tutorial);
      } else if (path) {
        navigate(path);
      } else {
        const { type, item, kitId } = result;
        if (type === "kit") navigate(`/kits/${(item as Kit).id}`);
        else if (type === "design") navigate(`/kits/${kitId}/designs/${(item as Design).id}`);
        else if (type === "type") navigate(`/kits/${kitId}/types/${(item as Type).id}`);
        else if (type === "quality") navigate(`/kits/${kitId}?kind=qualities&select=${(item as Quality).id}`);
      }
    },
    [navigate, recentSearches, updateRecentSearches, tutorialStore],
  );

  const getIcon = (type: SearchResult["type"]) => {
    if (type === "kit") return <DocumentIcon size={16} />;
    if (type === "design") return <LayoutIcon size={16} />;
    if (type === "type") return <TypeIcon size={16} />;
    if (type === "quality") return <AwardIcon size={16} />;
    if (type === "tutorial") return <TutorialIcon size={16} />;
    return null;
  };

  const getDisplayName = (result: SearchResult) => {
    const { type, item } = result;
    if (type === "quality") return (item as Quality).name;
    if (type === "tutorial") return (item as Tutorial).name;
    return (item as any).name || "";
  };

  const searchTitle = useLabel("semio.sketchpad.navbar.search.title");
  const searchDescription = useLabel("semio.sketchpad.navbar.search.description");
  const searchPlaceholder = useLabel("semio.sketchpad.navbar.search.placeholder");
  const searchNoResults = useLabel("semio.sketchpad.navbar.search.noResults");
  const kitsLabel = useLabel("semio.sketchpad.navbar.kits");
  const designsLabel = useLabel("semio.sketchpad.navbar.breadcrumb.designs");
  const typesLabel = useLabel("semio.sketchpad.navbar.breadcrumb.types");
  const qualitiesLabel = useLabel("semio.sketchpad.navbar.breadcrumb.qualities");
  const tutorialsLabel = useLabel("semio.sketchpad.navbar.tutorials");

  return (
    <>
      <Toggle id="semio.sketchpad.navbar.search.open" i18nPressed="semio.sketchpad.navbar.search.close" pressed={open} onPressedChange={setOpen} icon={<SearchIcon size={16} />} />
      <CommandDialog title={searchTitle} description={searchDescription} open={open} onOpenChange={setOpen}>
        <CommandInput id="semio.sketchpad.navbar.searchInput" placeholder={searchPlaceholder} value={query} onValueChange={setQuery} />
        <CommandList>
          <CommandEmpty>{searchNoResults}</CommandEmpty>
          {groupedSearchResults.kits.length > 0 && (
            <CommandGroup heading={kitsLabel}>
              {groupedSearchResults.kits.map((r: FuseResult<SearchResult>, idx: number) => (
                <CommandItem key={`kit-${(r.item.item as Kit).id}-${idx}`} onSelect={() => handleSelect(r.item)}>
                  <div className="flex items-center gap-single">
                    {getIcon(r.item.type)}
                    <span>{getDisplayName(r.item)}</span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}
          {groupedSearchResults.designs.length > 0 && (
            <CommandGroup heading={designsLabel}>
              {groupedSearchResults.designs.map((r: FuseResult<SearchResult>, idx: number) => (
                <CommandItem key={`design-${(r.item.item as Design).id}-${idx}`} onSelect={() => handleSelect(r.item)}>
                  <div className="flex items-center gap-single">
                    {getIcon(r.item.type)}
                    <span>{getDisplayName(r.item)}</span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}
          {groupedSearchResults.types.length > 0 && (
            <CommandGroup heading={typesLabel}>
              {groupedSearchResults.types.map((r: FuseResult<SearchResult>, idx: number) => (
                <CommandItem key={`type-${(r.item.item as Type).id}-${idx}`} onSelect={() => handleSelect(r.item)}>
                  <div className="flex items-center gap-single">
                    {getIcon(r.item.type)}
                    <span>{getDisplayName(r.item)}</span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}
          {groupedSearchResults.qualities.length > 0 && (
            <CommandGroup heading={qualitiesLabel}>
              {groupedSearchResults.qualities.map((r: FuseResult<SearchResult>, idx: number) => (
                <CommandItem key={`quality-${(r.item.item as Quality).id}-${idx}`} onSelect={() => handleSelect(r.item)}>
                  <div className="flex items-center gap-single">
                    {getIcon(r.item.type)}
                    <span>{getDisplayName(r.item)}</span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}
          {groupedSearchResults.tutorials.length > 0 && (
            <CommandGroup heading={tutorialsLabel}>
              {groupedSearchResults.tutorials.map((r: FuseResult<SearchResult>, idx: number) => (
                <CommandItem key={`tutorial-${(r.item.item as Tutorial).id}-${idx}`} onSelect={() => handleSelect(r.item)}>
                  <div className="flex items-center gap-single">
                    {getIcon(r.item.type)}
                    <span>{getDisplayName(r.item)}</span>
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          )}
        </CommandList>
      </CommandDialog>
    </>
  );
};

const Focus: FC = ({}) => {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const focusContext = useFocusSafe();
  const appType = useAppType();
  const recentFocusMap = (useSketchpad((s) => s.recentFocusItems) as Record<string, string[]>) || {};
  const recentFocusIds = recentFocusMap[appType] || [];
  const updateRecentFocusItems = useUpdateRecentFocusItems();

  const focusItems = focusContext?.focusItems || [];
  const triggerFocusItem = focusContext?.triggerFocusItem;
  const focusItemIndex = useMemo(() => {
    const map = new Map<string, FocusItem>();
    focusItems.forEach((item) => map.set(item.id, item));
    return map;
  }, [focusItems]);
  const recentFocusItems = useMemo(() => {
    return recentFocusIds.map((id) => focusItemIndex.get(id)).filter((item): item is FocusItem => !!item);
  }, [recentFocusIds, focusItemIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "f") {
        e.preventDefault();
        setOpen((prev) => !prev);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const fuse = useMemo(
    () =>
      new Fuse(focusItems, {
        keys: [
          { name: "label", weight: 2 },
          { name: "description", weight: 1 },
          { name: "category", weight: 0.5 },
        ],
        threshold: 0.4,
        includeScore: true,
      }),
    [focusItems],
  );

  const focusResults = useMemo(() => {
    if (query.trim()) return fuse.search(query).slice(0, 20);

    const base = recentFocusItems.length > 0 ? recentFocusItems : focusItems.slice(0, 20);
    return base.map((item, idx) => ({ item, refIndex: idx }));
  }, [fuse, query, recentFocusItems, focusItems]);

  const handleSelect = useCallback(
    (item: FocusItem) => {
      const next = [item.id, ...recentFocusIds.filter((id) => id !== item.id)].slice(0, 20);
      const changed = next.length !== recentFocusIds.length || next.some((id, index) => id !== recentFocusIds[index]);
      if (changed) updateRecentFocusItems(appType, next);
      setOpen(false);
      setQuery("");
      if (triggerFocusItem) triggerFocusItem(item.id);
    },
    [appType, recentFocusIds, updateRecentFocusItems, triggerFocusItem],
  );

  const focusOtherLabel = useLabel("semio.sketchpad.navbar.focus.other");
  const groupedResults = useMemo(() => {
    const groups: Record<string, typeof focusResults> = {};
    focusResults.forEach((result) => {
      const category = result.item.category || focusOtherLabel || "";
      if (!groups[category]) groups[category] = [];
      groups[category].push(result);
    });
    return groups;
  }, [focusResults, focusOtherLabel]);

  if (!focusContext) return null;

  const focusTitle = useLabel("semio.sketchpad.navbar.focus.title");
  const focusDescription = useLabel("semio.sketchpad.navbar.focus.description");
  const focusPlaceholder = useLabel("semio.sketchpad.navbar.focus.placeholder");
  const focusNoResults = useLabel("semio.sketchpad.navbar.search.noResults");

  return (
    <>
      <Toggle id="semio.sketchpad.navbar.focus.open" i18nPressed="semio.sketchpad.navbar.focus.close" pressed={open} onPressedChange={setOpen} icon={<FocusIcon size={16} />} />
      <CommandDialog title={focusTitle} description={focusDescription} open={open} onOpenChange={setOpen}>
        <CommandInput id="semio.sketchpad.navbar.focus.input" placeholder={focusPlaceholder} value={query} onValueChange={setQuery} />
        <CommandList>
          <CommandEmpty>{focusNoResults}</CommandEmpty>
          {Object.entries(groupedResults).map(([category, items]) => (
            <CommandGroup key={category} heading={category}>
              {items.map((result, idx) => (
                <CommandItem key={`${result.item.id}-${idx}`} onSelect={() => handleSelect(result.item)}>
                  <div className="flex flex-col">
                    <span>{result.item.label}</span>
                    {result.item.description && <span className="text-xs text-muted-foreground">{result.item.description}</span>}
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          ))}
        </CommandList>
      </CommandDialog>
    </>
  );
};

const PanelToggles: FC = ({}) => {
  const visiblePanels = useAppPanelVisibility();
  const appCommands = useAppCommands();
  const leftTabs = useSidePanelTabs("left");
  const rightTabs = useSidePanelTabs("right");

  const hasLeftTabs = leftTabs.length > 0;
  const hasRightTabs = rightTabs.length > 0;

  const isLeftOpen = visiblePanels.leftSidePanel ?? false;
  const isRightOpen = visiblePanels.rightSidePanel ?? false;
  const isChatOpen = visiblePanels.chat ?? false;
  const isSettingsOpen = visiblePanels.settings ?? false;

  const handleLeftToggle = useCallback(() => {
    appCommands?.togglePanel?.("semio.sketchpad.navbar.panelToggle.leftSidePanel", "leftSidePanel");
  }, [appCommands]);

  const handleRightToggle = useCallback(() => {
    appCommands?.togglePanel?.("semio.sketchpad.navbar.panelToggle.rightSidePanel", "rightSidePanel");
  }, [appCommands]);

  const handleChatToggle = useCallback(() => {
    appCommands?.togglePanel?.("semio.sketchpad.navbar.panelToggle.chat", "chat");
  }, [appCommands]);

  const handleSettingsToggle = useCallback(() => {
    appCommands?.togglePanel?.("semio.sketchpad.navbar.panelToggle.settings", "settings");
  }, [appCommands]);

  const LeftIcon = leftTabs[0]?.icon;
  const RightIcon = rightTabs[0]?.icon;

  return (
    <div className="flex items-stretch gap-single">
      {(hasLeftTabs || hasRightTabs) && (
        <div className="flex items-stretch border border-element overflow-hidden h-medium divide-x divide-element">
          {hasLeftTabs && <Toggle kind="icon" id="semio.sketchpad.navbar.panelToggle.leftSidePanel" pressed={isLeftOpen} onPressedChange={handleLeftToggle} className="!border-0" icon={LeftIcon ? <LeftIcon size={16} /> : <LayoutIcon size={16} />} />}
          {hasRightTabs && (
            <Toggle kind="icon" id="semio.sketchpad.navbar.panelToggle.rightSidePanel" pressed={isRightOpen} onPressedChange={handleRightToggle} className="!border-0" icon={RightIcon ? <RightIcon size={16} /> : <DocumentIcon size={16} />} />
          )}
        </div>
      )}
      <div className="flex items-stretch border border-element overflow-hidden h-medium divide-x divide-element">
        <Toggle kind="icon" id="semio.sketchpad.navbar.panelToggle.chat" pressed={isChatOpen} onPressedChange={handleChatToggle} className="!border-0" icon={<ChatIcon size={16} />} />
        <Toggle kind="icon" id="semio.sketchpad.navbar.panelToggle.settings" pressed={isSettingsOpen} onPressedChange={handleSettingsToggle} className="!border-0" icon={<SettingsIcon size={16} />} />
      </div>
    </div>
  );
};

// #region 📡Canvas
// Canvas layout components for window management and multi-pane rendering.

// AppWindowConfig, WindowControl, WindowKindDefinition are defined in the Shared section above.

/** CanvasContext holds the data fields for a CanvasContext record.
 **/
/**
 **/
const CanvasContext = createContext<{ activeWindow?: string; onActiveWindowChange?: (windowId: string) => void } | null>(null);

/**
 * Hook returning the canvas context for active window management.
 **/
export function useCanvasContext() {
  const context = useContext(CanvasContext);
  return context;
}

// Canvas, HorizontalWindows, VerticalWindows are re-exported from @semio/ui above.
/**
 * WindowControlsGroup holds the data fields for a WindowControlsGroup record.
 **/
const WindowControlsGroup: FC<{ controls: WindowControl[] }> = ({ controls }) => {
  if (!controls || controls.length === 0) return null;

  return (
    <div className="flex items-stretch border overflow-hidden h-large">
      {controls.map((control) => {
        if (control.kind === "toggle") {
          return (
            <Toggle
              key={control.id}
              id={control.id}
              pressed={control.value === "true" || control.value === "1"}
              onPressedChange={(pressed) => {
                if (control.onChange) {
                  control.onChange(pressed ? "true" : "false");
                }
              }}
              icon={control.icon}
            />
          );
        } else if (control.kind === "dropdown" && control.options) {
          return (
            <Toggle
              key={control.id}
              kind="dropdown"
              id={control.id}
              value={control.value || control.options[0]?.value}
              onValueChange={(value) => {
                if (control.onChange) {
                  control.onChange(value);
                }
              }}
              items={control.options.map((opt) => ({
                value: opt.value,
                label: opt.icon,
                id: `${control.id}.${opt.value}`,
              }))}
              pressed={!!control.value}
            >
              {control.icon}
            </Toggle>
          );
        }
        return null;
      })}
    </div>
  );
};
/**
 * LayoutErrorBoundaryProps holds the data fields for a LayoutErrorBoundaryProps record.
 **/
interface LayoutErrorBoundaryProps {
  children: ReactNode;
  windowId: string;
  onError?: (error: Error, info: React.ErrorInfo) => void;
}
/**
 * LayoutErrorBoundaryState holds the data fields for a LayoutErrorBoundaryState record.
 **/
interface LayoutErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}
/**
 * LayoutErrorBoundary holds the data fields for a LayoutErrorBoundary record.
 **/
class LayoutErrorBoundary extends React.Component<LayoutErrorBoundaryProps, LayoutErrorBoundaryState> {
  constructor(props: LayoutErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }
  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    this.props.onError?.(error, errorInfo);
  }
  componentDidUpdate(prevProps: LayoutErrorBoundaryProps) {
    if (prevProps.children !== this.props.children && this.state.hasError) {
      this.setState({ hasError: false, error: null });
    }
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-full gap-2 p-4">
          <p className="text-sm text-muted-foreground">Error rendering {this.props.windowId}</p>
          <p className="text-xs text-red-500 font-mono whitespace-pre-wrap max-w-full overflow-auto" data-testid="layout-error-message">
            {this.state.error?.message}
          </p>
          <p className="text-xs text-muted-foreground font-mono whitespace-pre-wrap max-w-full overflow-auto max-h-32" data-testid="layout-error-stack">
            {this.state.error?.stack?.split("\n").slice(0, 5).join("\n")}
          </p>
        </div>
      );
    }
    return this.props.children;
  }
}

/**
 * Component rendering the full canvas layout with window configuration.
 **/
export const LayoutCanvas: FC<{
  windowConfig: AppWindowConfig;
  layoutState?: any;
  onLayoutChange?: (layout: any) => void;
  activeWindow?: string;
  onActiveWindowChange?: (windowId: string) => void;
  children?: ReactNode;
}> = ({ windowConfig, layoutState, onLayoutChange, activeWindow, onActiveWindowChange, children }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const layoutRef = useRef<any>(null);
  const [layoutLoaded, setLayoutLoaded] = useState(false);
  const [hoveredSplitter, setHoveredSplitter] = useState<{ element: HTMLElement; direction: "horizontal" | "vertical" } | null>(null);
  const hoveredSplitterElementRef = useRef<HTMLElement | null>(null);
  const handleSplitterHoverRef = useRef<((e: MouseEvent) => void) | null>(null);
  const handleSplitterLeaveRef = useRef<((e: MouseEvent) => void) | null>(null);
  const sketchpadInstance = useSketchpadInstance();
  const sketchpadActor = useSketchpadActorSafe();
  const location = useLocation();
  const navigate = useNavigate();

  const scopeIds = useMemo(() => {
    const pathMatch = location.pathname.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
    return {
      kit: pathMatch?.[1],
      itemType: pathMatch?.[2],
      item: pathMatch?.[3],
    };
  }, [location.pathname]);

  const LayoutContextHost: FC<{ children: ReactNode }> = ({ children }) => {
    const { kit, itemType, item } = scopeIds;

    let wrapped = <>{children}</>;

    if (item && kit) {
      if (itemType === "qualities") {
        wrapped = <QualityContextProvider id={item}>{wrapped}</QualityContextProvider>;
      } else if (itemType === "types") {
        wrapped = <TypeContextProvider id={item}>{wrapped}</TypeContextProvider>;
      } else if (itemType === "designs") {
        wrapped = <DesignContextProvider id={item}>{wrapped}</DesignContextProvider>;
      }
    }
    if (kit) {
      wrapped = <KitTabContextProvider id={kit}>{wrapped}</KitTabContextProvider>;
    }
    if (sketchpadActor) {
      wrapped = <SketchpadActorContext.Provider value={sketchpadActor}>{wrapped}</SketchpadActorContext.Provider>;
    }
    if (sketchpadInstance) {
      wrapped = <SketchpadInstanceContext.Provider value={sketchpadInstance}>{wrapped}</SketchpadInstanceContext.Provider>;
    }
    wrapped = (
      <>
        <OriginDocumentListener />
        {wrapped}
      </>
    );

    return wrapped;
  };

  const contextValue = useMemo(
    () => ({
      activeWindow,
      onActiveWindowChange,
    }),
    [activeWindow, onActiveWindowChange],
  );

  const setActiveSplitter = useCallback((element: HTMLElement, direction: "horizontal" | "vertical") => {
    if (hoveredSplitterElementRef.current && hoveredSplitterElementRef.current !== element) {
      hoveredSplitterElementRef.current.classList.remove("relative", "overflow-visible");
    }
    hoveredSplitterElementRef.current = element;
    element.classList.add("relative", "overflow-visible");
    setHoveredSplitter({ element, direction });
  }, []);

  const clearHoveredSplitter = useCallback(() => {
    if (hoveredSplitterElementRef.current) {
      hoveredSplitterElementRef.current.classList.remove("relative", "overflow-visible");
      hoveredSplitterElementRef.current = null;
    }
    setHoveredSplitter(null);
  }, []);

  const handleAddWindow = useCallback(
    (windowTypeId: string, direction: "horizontal" | "vertical", splitterElement: HTMLElement) => {
      if (!layoutRef.current) {
        return;
      }
      if (!splitterElement) {
        return;
      }

      const windowType = windowConfig.windowKinds.find((wt) => wt.id === windowTypeId);
      if (!windowType) {
        return;
      }

      const newItemConfig = {
        type: "stack",
        content: [
          {
            type: "component",
            componentName: windowTypeId,
          },
        ],
      };

      const splitter = splitterElement;

      try {
        const findAllItems = (item: any): any[] => {
          const items = [item];
          if (item.contentItems && Array.isArray(item.contentItems)) {
            item.contentItems.forEach((child: any) => {
              items.push(...findAllItems(child));
            });
          }
          return items;
        };

        let parent = null;
        let insertIndex = -1;
        const allItems = findAllItems(layoutRef.current.root);

        for (const item of allItems) {
          if (item.type === "row" || item.type === "column") {
            const itemEl = item.element?.[0] || item.element;
            if (itemEl && itemEl.contains && itemEl.contains(splitter)) {
              parent = item;
              if (parent.contentItems && Array.isArray(parent.contentItems)) {
                const children = Array.from(itemEl.children || []);
                let splitterIndex = -1;
                for (let i = 0; i < children.length; i++) {
                  if (children[i] === splitter) {
                    splitterIndex = i;
                    break;
                  }
                }
                if (splitterIndex === -1) {
                  for (let i = 0; i < children.length; i++) {
                    const child = children[i] as HTMLElement;
                    if (child.contains && child.contains(splitter)) {
                      splitterIndex = i;
                      break;
                    }
                  }
                }
                if (splitterIndex >= 0) {
                  let itemsBeforeSplitter = 0;
                  for (let i = 0; i < splitterIndex; i++) {
                    const child = children[i] as HTMLElement;
                    if (!child.classList.contains("lm_splitter")) {
                      itemsBeforeSplitter++;
                    }
                  }
                  insertIndex = itemsBeforeSplitter;
                }
              }
              break;
            }
          }
        }

        if (parent && insertIndex >= 0) {
          layoutRef.current.root.addItem(newItemConfig, parent, insertIndex);
        } else if (parent) {
          layoutRef.current.root.addItem(newItemConfig, parent);
        } else {
          layoutRef.current.root.addItem(newItemConfig);
        }
      } catch (error) {
        console.error("Error adding window:", error);
      }

      clearHoveredSplitter();
    },
    [windowConfig.windowKinds, clearHoveredSplitter],
  );

  useEffect(() => {
    if (!containerRef.current || layoutRef.current) return;

    const loadGoldenLayout = async () => {
      try {
        const goldenLayoutModule = await import("golden-layout");
        const GoldenLayout = (goldenLayoutModule as any).GoldenLayout;

        if (!GoldenLayout || typeof GoldenLayout !== "function") {
          console.error("GoldenLayout is not a constructor", { goldenLayoutModule, GoldenLayout });
          return;
        }

        const normalizeLayoutConfig = (config: any): any => {
          if (Array.isArray(config)) {
            return config.map((item) => normalizeLayoutConfig(item));
          }

          const normalized: any = {};

          for (const [key, value] of Object.entries(config)) {
            const unitKey = `${key}Unit` as string;
            const hasUnitField = unitKey in config;

            if (hasUnitField) {
              const unit = config[unitKey];
              if (typeof value === "string") {
                const numValue = parseFloat(value);
                normalized[key] = !isNaN(numValue) ? `${numValue}${unit}` : `1${unit}`;
              } else if (typeof value === "number") {
                normalized[key] = `${value}${unit}`;
              } else {
                normalized[key] = `1${unit}`;
              }
            } else if (key === "size" || key === "width" || key === "height") {
              if (typeof value === "string") {
                normalized[key] = value.trim() === "" && key === "size" ? "50%" : value;
              } else if (typeof value === "number") {
                normalized[key] = `${value}%`;
              } else {
                normalized[key] = "50%";
              }
            } else if (key === "title" || key === "componentName" || key === "componentType" || key === "type" || key === "id") {
              if (typeof value === "string") {
                if (value.trim() !== "") {
                  normalized[key] = value;
                }
              } else if (value !== null && value !== undefined) {
                normalized[key] = String(value);
              }
            } else if (key === "content" && Array.isArray(value)) {
              if (value.length > 0 || config.type !== "component") {
                normalized[key] = value.map((item) => normalizeLayoutConfig(item));
              }
            } else if (key === "componentState") {
              normalized[key] = value;
            } else if (typeof value === "object" && value !== null) {
              normalized[key] = normalizeLayoutConfig(value);
            } else {
              normalized[key] = value;
            }
          }

          return normalized;
        };

        const parsedLayout = parseWindowLayout(layoutState) ?? parseWindowLayout(windowConfig.defaultLayout);
        if (!parsedLayout) {
          console.error("[LayoutCanvas] No layout config provided!");
          return;
        }
        const config = normalizeLayoutConfig(layoutNodeToGoldenLayoutConfig(parsedLayout));

        const layout = new GoldenLayout(config, containerRef.current!);
        let isInitialized = false;

        windowConfig.windowKinds.forEach((windowType) => {
          layout.registerComponent(windowType.id, (container: any, componentState: any) => {
            const element = container.getElement();
            let domElement: HTMLElement;

            if (element instanceof HTMLElement) {
              domElement = element;
            } else if (Array.isArray(element) && element[0] instanceof HTMLElement) {
              domElement = element[0];
            } else if (element && (element as any)[0] instanceof HTMLElement) {
              domElement = (element as any)[0];
            } else if (element && element.nodeType === 1) {
              domElement = element as HTMLElement;
            } else {
              console.error("Could not extract DOM element from container", { element, container });
              return;
            }

            const root = getOrCreateDomRoot(domElement);
            const WindowComponent = windowType.component;

            const WrappedComponent = () => {
              const clickGoldenLayoutControl = (selector: string) => {
                const stackElement = domElement.closest(".lm_item.lm_stack") as HTMLElement | null;
                const controlElement = (stackElement?.querySelector(selector) as HTMLElement | null) ?? null;
                if (controlElement) {
                  controlElement.click();
                }
              };
              return (
                <MemoryRouter initialEntries={[location.pathname + location.search]} initialIndex={0} unstable_useTransitions={false}>
                  <LayoutContextHost>
                    <LayoutErrorBoundary
                      windowId={windowType.id}
                      onError={(error: Error, info: React.ErrorInfo) => {
                        console.error("Error in window:", windowType.id, error, info);
                      }}
                    >
                      <Window
                        id={windowType.id}
                        isVisible={true}
                        showControls={true}
                        onOpenInNewWindow={() => clickGoldenLayoutControl(".lm_popout")}
                        onMaximize={() => clickGoldenLayoutControl(".lm_maximise")}
                        onMinimize={() => clickGoldenLayoutControl(".lm_maximise")}
                        onClose={() => clickGoldenLayoutControl(".lm_close")}
                        controls={windowType.controls ? <WindowControlsGroup controls={windowType.controls} /> : undefined}
                      >
                        <ReactFlowProvider>
                          <WindowComponent />
                        </ReactFlowProvider>
                      </Window>
                    </LayoutErrorBoundary>
                  </LayoutContextHost>
                </MemoryRouter>
              );
            };

            root.render(<WrappedComponent />);
            container.on("destroy", () => {
              setTimeout(() => {
                clearDomRoot(domElement, root);
                root.unmount();
              }, 0);
            });
          });
        });

        layout.on("stateChanged", () => {
          if (!onLayoutChange) return;

          try {
            if (isInitialized) {
              const nextLayout = parseWindowLayout(layout.toConfig());
              onLayoutChange(nextLayout ?? layout.toConfig());
            }
          } catch (error: any) {
            if (error?.message?.includes("not yet initialised")) {
              return;
            }
            console.warn("Failed to get layout config:", error);
          }
        });

        layout.on("tab", (tab: any) => {
          if (tab._header) {
            tab._header.on("click", () => {
              const componentName = tab._contentItem?.config?.componentName;
              if (componentName && onActiveWindowChange) {
                onActiveWindowChange(componentName);
              }
            });
          }
        });

        const customizeHeaders = () => {
          try {
            const getAllStacks = (item: any): any[] => {
              const stacks: any[] = [];
              if (item.type === "stack") {
                stacks.push(item);
              }
              if (item.contentItems) {
                item.contentItems.forEach((child: any) => {
                  stacks.push(...getAllStacks(child));
                });
              }
              return stacks;
            };

            const stacks = getAllStacks(layout.root);
            stacks.forEach((stack: any) => {
              if (stack.header && stack.header.controlsContainer) {
                stack.header.controlsContainer.on("open", () => {
                  const activeContentItem = stack.getActiveContentItem?.();
                  if (activeContentItem) {
                    const componentName = activeContentItem.config?.componentName;
                    if (componentName && onActiveWindowChange) {
                      onActiveWindowChange(componentName);
                    }
                  }
                });
              }
            });
          } catch (error) {
            console.warn("Failed to customize headers:", error);
          }
        };

        layout.on("initialised", () => {
          customizeHeaders();
          isInitialized = true;
          setLayoutLoaded(true);
        });

        try {
          layout.init();
          layoutRef.current = layout;
        } catch (error: any) {
          console.error("[GoldenLayout] Failed to initialize:", error);
          console.error("[GoldenLayout] Config that failed:", JSON.stringify(config, null, 2));
          throw error;
        }

        handleSplitterHoverRef.current = (e: MouseEvent) => {
          const target = e.target as HTMLElement;
          const buttonContainer = target.closest("[data-splitter-buttons]") as HTMLElement | null;
          if (buttonContainer) {
            return;
          }
          const splitter = target.closest(".lm_splitter") as HTMLElement | null;
          if (splitter) {
            const isHorizontal = splitter.classList.contains("lm_splitter_horizontal");
            setActiveSplitter(splitter, isHorizontal ? "horizontal" : "vertical");
          } else {
            clearHoveredSplitter();
          }
        };

        handleSplitterLeaveRef.current = (e: MouseEvent) => {
          const target = e.target as HTMLElement;
          const relatedTarget = e.relatedTarget as Node | null;
          const splitter = target.closest(".lm_splitter") as HTMLElement | null;
          const buttonContainer = relatedTarget && ((relatedTarget as HTMLElement).closest?.("[data-splitter-buttons]") as HTMLElement | null);
          if (splitter && relatedTarget && splitter.contains(relatedTarget)) {
            return;
          }
          if (buttonContainer) {
            return;
          }
          if (splitter && relatedTarget && (relatedTarget as HTMLElement).closest?.(".lm_splitter") === splitter) {
            return;
          }
          clearHoveredSplitter();
        };

        if (containerRef.current && handleSplitterHoverRef.current && handleSplitterLeaveRef.current) {
          containerRef.current.addEventListener("mouseover", handleSplitterHoverRef.current);
          containerRef.current.addEventListener("mouseout", handleSplitterLeaveRef.current);
        }
      } catch (error) {
        console.error("Failed to load GoldenLayout:", error);
      }
    };

    loadGoldenLayout();

    return () => {
      clearHoveredSplitter();
      if (containerRef.current && handleSplitterHoverRef.current && handleSplitterLeaveRef.current) {
        containerRef.current.removeEventListener("mouseover", handleSplitterHoverRef.current);
        containerRef.current.removeEventListener("mouseout", handleSplitterLeaveRef.current);
      }
      if (layoutRef.current) {
        try {
          layoutRef.current.destroy();
        } catch (error) {
          console.error("Error destroying layout:", error);
        }
        layoutRef.current = null;
        setLayoutLoaded(false);
      }
    };
  }, [windowConfig, layoutState, onLayoutChange, onActiveWindowChange, sketchpadInstance, location, navigate, scopeIds, setActiveSplitter, clearHoveredSplitter]);

  useEffect(() => {
    if (!layoutRef.current || !layoutLoaded) return;

    const updateActiveTab = () => {
      if (!activeWindow) return;
      try {
        const getAllStacks = (item: any): any[] => {
          const stacks: any[] = [];
          if (item.type === "stack") {
            stacks.push(item);
          }
          if (item.contentItems) {
            item.contentItems.forEach((child: any) => {
              stacks.push(...getAllStacks(child));
            });
          }
          return stacks;
        };

        const stacks = getAllStacks(layoutRef.current.root);
        stacks.forEach((stack: any) => {
          const getAllComponents = (item: any): any[] => {
            const components: any[] = [];
            if (item.type === "component") {
              components.push(item);
            }
            if (item.contentItems) {
              item.contentItems.forEach((child: any) => {
                components.push(...getAllComponents(child));
              });
            }
            return components;
          };

          const componentsInStack = getAllComponents(stack);
          componentsInStack.forEach((item: any) => {
            if (item.config?.componentName === activeWindow && stack.setActiveContentItem) {
              stack.setActiveContentItem(item);
            }
          });
        });
      } catch (error) {
        console.warn("Failed to update active tab:", error);
      }
    };

    updateActiveTab();
  }, [activeWindow, layoutLoaded]);

  return (
    <CanvasContext.Provider value={contextValue}>
      <div ref={containerRef} className="h-full w-full">
        {children}
        {hoveredSplitter &&
          hoveredSplitter.element &&
          createPortal(
            <LevelProvider level="temporary">
              <div data-splitter-buttons className="pointer-events-auto absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 bg-temporary border border-element p-single">
                <ActionGroup>
                  {windowConfig.windowKinds.map((windowType) => {
                    const typeId = windowType.id;
                    const direction = hoveredSplitter.direction;
                    const splitterElement = hoveredSplitter.element;
                    if (!splitterElement) {
                      return null;
                    }
                    return (
                      <ActionGroupItem
                        key={typeId}
                        type="button"
                        disabled={!layoutLoaded}
                        onClick={(e: React.MouseEvent) => {
                          e.stopPropagation();
                          if (!splitterElement) {
                          }
                          if (!layoutRef.current) {
                            return;
                          }
                          handleAddWindow(typeId, direction, splitterElement);
                        }}
                        onMouseEnter={() => {
                          hoveredSplitterElementRef.current = splitterElement;
                        }}
                        title={typeof windowType.label === "string" ? windowType.label : typeId}
                        text={typeof windowType.label === "string" ? windowType.label : typeId}
                      />
                    );
                  })}
                </ActionGroup>
              </div>
            </LevelProvider>,
            hoveredSplitter.element,
          )}
      </div>
    </CanvasContext.Provider>
  );
};

// #endregion 📡Canvas

// #region 🕰️App Router
// React Router integration with scope providers and route-based app switching.
/**
 * RouteParamContextShell binds a route param id to a context-bracketing component (e.g. kit tab mount).
 */
const RouteParamContextShell: FC<{ ContextComponent: ComponentType<{ id: string; children: ReactNode }>; paramName: string; children: ReactNode }> = ({ ContextComponent, paramName, children }) => {
  const params = useParams();
  const id = params[paramName];
  if (!id) return <>{children}</>;
  return <ContextComponent id={id}>{children}</ContextComponent>;
};
/**
 * AppRouter holds the data fields for a AppRouter record.
 **/
const AppRouter: FC = () => {
  const [appsInitialized, setAppsInitialized] = useState(false);

  useEffect(() => {
    if (!appsInitialized) {
      void appRegistry
        .initialize()
        .then(() => setAppsInitialized(true))
        .catch((err) => {
          console.error("[DEBUG] appRegistry.initialize failed:", err);
          setAppsInitialized(true);
        });
    }
  }, [appsInitialized]);

  const apps = useMemo(() => {
    if (!appsInitialized) return [];
    const sortedApps = appRegistry.getAllApps();
    return sortedApps;
  }, [appsInitialized]);

  const buildRoute = (app: AppRegistration, segments: RouteSegment[], index: number = 0): ReactNode => {
    if (index >= segments.length) {
      return <Route key={app.id} path="*" element={<app.component />} />;
    }

    const segment = segments[index];
    const paramName = segment.paramName;
    const ContextComponent = segment.contextProvider;
    const isLast = index === segments.length - 1;
    const routePath = index === 0 && !segment.path.startsWith("/") ? `/${segment.path}` : segment.path;

    if (ContextComponent && paramName) {
      return (
        <Route
          key={`${app.id}-${index}`}
          path={routePath}
          element={
            <RouteParamContextShell ContextComponent={ContextComponent} paramName={paramName}>
              {isLast ? <app.component /> : <Outlet />}
            </RouteParamContextShell>
          }
        >
          {!isLast && buildRoute(app, segments, index + 1)}
        </Route>
      );
    }
    return (
      <Route key={`${app.id}-${index}`} path={routePath} element={isLast ? <app.component /> : <Outlet />}>
        {!isLast && buildRoute(app, segments, index + 1)}
      </Route>
    );
  };

  if (!appsInitialized) {
    return <div className="flex h-screen w-screen items-center justify-center bg-neutral-950 text-neutral-200">Loading apps…</div>;
  }

  return (
    <Routes>
      {apps.map((app) => {
        if (app.routeSegments.length === 0) {
          const paths = app.additionalPaths || [];
          return [<Route key={`${app.id}-root`} path="/" element={<app.component />} />, ...paths.map((path) => <Route key={`${app.id}-${path}`} path={path} element={<app.component />} />)];
        }
        return buildRoute(app, app.routeSegments);
      })}
    </Routes>
  );
};

// #endregion 🕰️App Router

// #region 📝Sketchpad Components
// Top-level sketchpad React components for rendering the complete application.
/**
 * ToolbarContextHost holds the data fields for a ToolbarContextHost record.
 **/
const ToolbarContextHost: FC<{ children: ReactNode }> = ({ children }) => {
  const location = useLocation();
  const scopeIds = useMemo(() => {
    const pathMatch = location.pathname.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
    return {
      kit: pathMatch?.[1],
      itemType: pathMatch?.[2],
      item: pathMatch?.[3],
    };
  }, [location.pathname]);

  const { kit, itemType, item } = scopeIds;
  let wrapped = <>{children}</>;

  if (item && kit) {
    if (itemType === "qualities") {
      wrapped = <QualityContextProvider id={item}>{wrapped}</QualityContextProvider>;
    } else if (itemType === "types") {
      wrapped = <TypeContextProvider id={item}>{wrapped}</TypeContextProvider>;
    } else if (itemType === "designs") {
      wrapped = <DesignContextProvider id={item}>{wrapped}</DesignContextProvider>;
    }
  }
  if (kit) {
    wrapped = <KitTabContextProvider id={kit}>{wrapped}</KitTabContextProvider>;
  }

  return wrapped;
};

const PanelTabContent: FC<{ sections: PanelSection[] }> = ({ sections }) => {
  const sortedSections = [...sections].sort((a, b) => (a.order || 0) - (b.order || 0));
  const treeSections = sortedSections.map((section, index) => ({
    id: section.id,
    className: index > 0 ? "mt-single" : undefined,
    defaultOpen: section.defaultOpen ?? index === 0,
    actions: section.actions,
    onPointerEnter: section.onPointerEnter,
    onPointerLeave: section.onPointerLeave,
    onDoubleClick: section.onDoubleClick,
    content: typeof section.content === "function" ? section.content() : section.content,
  }));

  return (
    <TreeStateProvider>
      <Tree className="min-w-0 overflow-hidden" sections={treeSections} />
    </TreeStateProvider>
  );
};

const DynamicPanelTabContent: FC<{ panelKey: PanelKey }> = ({ panelKey }) => {
  const sections = usePanelSections(panelKey);
  return <PanelTabContent sections={sections} />;
};

const UtilityFallbackSettingsContent: FC<{ appType: string }> = ({ appType }) => {
  const appCommands = useAppCommands();
  const panelVisibility = useAppPanelVisibility();
  const showToolbarLabel = useLabel("semio.sketchpad.navbar.panelToggle.toolbar.show");
  const showWorkbenchLabel = useLabel("semio.sketchpad.navbar.panelToggle.workbench.show");
  const showDetailsLabel = useLabel("semio.sketchpad.navbar.panelToggle.details.show");
  const showWindowsLabel = useLabel("semio.sketchpad.navbar.panelToggle.tools.show");
  const togglePanelVisibility = useCallback(
    (panelKey: "toolbar" | "leftSidePanel" | "rightSidePanel" | "details") => {
      appCommands?.togglePanel?.(`semio.sketchpad.app.${appType}.settings.panel.${panelKey}`, panelKey);
    },
    [appCommands, appType],
  );
  return (
    <TreeStateProvider>
      <Tree
        className="min-w-0 overflow-hidden p-double"
        sections={[
          {
            id: `semio.sketchpad.app.${appType}.settings.panel`,
            label: null,
            content: (
              <>
                <Toggle id={`semio.sketchpad.app.${appType}.settings.panel.toolbar`} pressed={!!panelVisibility.toolbar} onPressedChange={() => togglePanelVisibility("toolbar")} text={showToolbarLabel} />
                <Toggle id={`semio.sketchpad.app.${appType}.settings.panel.workbench`} pressed={!!panelVisibility.leftSidePanel} onPressedChange={() => togglePanelVisibility("leftSidePanel")} text={showWorkbenchLabel} />
                <Toggle id={`semio.sketchpad.app.${appType}.settings.panel.windows`} pressed={!!panelVisibility.rightSidePanel} onPressedChange={() => togglePanelVisibility("rightSidePanel")} text={showWindowsLabel} />
                <Toggle id={`semio.sketchpad.app.${appType}.settings.panel.details`} pressed={!!panelVisibility.details} onPressedChange={() => togglePanelVisibility("details")} text={showDetailsLabel} />
              </>
            ),
          },
        ]}
      />
    </TreeStateProvider>
  );
};

const LayoutWrapper: FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const reactNavigate = useReactNavigate();
  const store = useSketchpadStore();
  const tutorialStore = store.tutorialStore();

  const navigation = useNavigation();
  const sketchpadInstance = useSketchpadInstance();
  const desktop = sketchpadInstance?.desktop;
  const [theme] = useTheme();
  const [language] = useLanguage();
  const [device] = useDevice();
  const [isFullscreen] = useFullscreen();
  const isNavbarExpanded = useIsNavbarExpanded();
  const isFooterExpanded = useIsFooterExpanded();
  const panelVisibility = useAppPanelVisibility();
  const appType = useAppType();
  const panelSizes = usePanelSizes();
  const footerItems = useFooterItems();
  const toolbarSections = usePanelSections("toolbar");
  const consoleSections = usePanelSections("console");

  const leftSidePanelTabs = useSidePanelTabs("left");
  const rightSidePanelTabs = useSidePanelTabs("right");

  const [activeLeftTabId, setActiveLeftTabId] = useActiveLeftTabId();
  const [activeRightTabId, setActiveRightTabId] = useActiveRightTabId();
  const wasRightSidePanelVisibleRef = useRef(false);

  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();
  const panelConfigs = usePanelConfigs();

  useEffect(() => {
    const panels = panelConfigs[appType] || [];
    const registeredIds: string[] = [];

    panels.forEach((panel) => {
      const config = panelKindConfigs[panel.kind];
      if (!config) return;

      const tab = {
        id: panel.id,
        icon: config.icon,
        order: 0,
        content: () => (
          <ToolbarContextHost>
            <DynamicPanelTabContent panelKey={panel.kind as PanelKey} />
          </ToolbarContextHost>
        ),
      };

      if (config.position === PanelPosition.LEFT) {
        addSidePanelTab("left", tab);
        registeredIds.push(panel.id);
      } else if (config.position === PanelPosition.RIGHT) {
        addSidePanelTab("right", tab);
        registeredIds.push(panel.id);
      }
    });

    return () => {
      registeredIds.forEach((id) => {
        const panel = panels.find((p) => p.id === id);
        if (!panel) return;
        const config = panelKindConfigs[panel.kind];
        if (!config) return;

        if (config.position === PanelPosition.LEFT) removeSidePanelTab("left", id);
        else if (config.position === PanelPosition.RIGHT) removeSidePanelTab("right", id);
      });
    };
  }, [appType, panelConfigs, addSidePanelTab, removeSidePanelTab]);

  useEffect(() => {
    const isRightSidePanelVisible = !!panelVisibility.rightSidePanel;
    const wasRightSidePanelVisible = wasRightSidePanelVisibleRef.current;
    if (isRightSidePanelVisible && !wasRightSidePanelVisible) {
      const sortedRightTabs = [...rightSidePanelTabs].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
      const detailsTab = sortedRightTabs.find((tab) => tab.id === "semio.sketchpad.navbar.panelToggle.details.show");
      const nextActiveTabId = detailsTab?.id ?? sortedRightTabs[0]?.id;
      if (nextActiveTabId && activeRightTabId !== nextActiveTabId) {
        setActiveRightTabId(nextActiveTabId);
      }
    }
    wasRightSidePanelVisibleRef.current = isRightSidePanelVisible;
  }, [panelVisibility.rightSidePanel, rightSidePanelTabs, activeRightTabId, setActiveRightTabId]);

  useEffect(() => {
    if (appType !== "design") return;
    if (!panelVisibility.rightSidePanel) return;
    const sortedRightTabs = [...rightSidePanelTabs].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
    const detailsTab = sortedRightTabs.find((tab) => tab.id === "semio.sketchpad.navbar.panelToggle.details.show");
    if (!detailsTab) return;
    const activeTabIsUtility = !activeRightTabId;
    if (activeTabIsUtility && activeRightTabId !== detailsTab.id) {
      setActiveRightTabId(detailsTab.id);
    }
  }, [appType, panelVisibility.rightSidePanel, rightSidePanelTabs, activeRightTabId, setActiveRightTabId]);

  const sketchpadCommands = useSketchpadCommands();
  useHotkeys("semio.sketchpad.navbar.copyJsonToClipboard", () => {
    sketchpadCommands.copyJsonToClipboard("semio.sketchpad.hotkey.copyJsonToClipboard");
  });

  useEffect(() => {
    const migratedPath = migratePath(location.pathname);
    if (migratedPath !== location.pathname) {
      reactNavigate(migratedPath, { replace: true });
    }
  }, [location.pathname, reactNavigate]);

  useEffect(() => {
    const fullPath = location.pathname + location.search;
    const currentHistory = store.snapshot().navigationHistory || ["/"];
    const currentIndex = store.snapshot().navigationHistoryIndex ?? 0;
    const currentPath = currentHistory[currentIndex];

    if (currentPath !== fullPath) {
      store.execute("semio.sketchpad.addNavigation", "semio.sketchpad.sync", fullPath);
    } else {
      store.execute("semio.sketchpad.syncNavigation", "semio.sketchpad.sync", fullPath);
    }
  }, [location.pathname, location.search, store]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const handler = () => {
      const active = !!document.fullscreenElement;
      if (active !== isFullscreen) {
        sketchpadCommands.setState("semio.sketchpad.fullscreenChange", { isFullscreen: active });
      }
    };
    document.addEventListener("fullscreenchange", handler);
    return () => document.removeEventListener("fullscreenchange", handler);
  }, [isFullscreen, sketchpadCommands]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    const shouldBeDark = theme === "dark" || (theme === "system" && prefersDark);
    if (shouldBeDark) {
      root.classList.add("dark");
    } else {
      root.classList.remove("dark");
    }
  }, [theme]);

  useEffect(() => {
    if (language) {
      if (i18n.language !== language) {
        i18n
          .changeLanguage(language)
          .then(() => {})
          .catch((err) => {
            console.error("[Language Sync] Failed to change language:", err);
          });
      }
    }
  }, [language]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    if (device === "tablet") {
      root.classList.add("touch");
    } else {
      root.classList.remove("touch");
    }
  }, [device]);

  useEffect(() => {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    if (isFullscreen) {
      root.classList.add("fullscreen");
    } else {
      root.classList.remove("fullscreen");
    }
  }, [isFullscreen]);

  const navigationHistory = useNavigationHistory();
  const currentPath = `${navigation}${location.search}`;
  const [searchParams] = useSearchParams();
  const kits = useKits() ?? [];

  const pathParts = navigation.split("/").filter((p) => p);
  const isUuidPattern = (str: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str);
  const isKitsPath = pathParts[0] === "kits";
  const isDocsPath = pathParts[0] === "docs";
  const kitId = isKitsPath && pathParts[1] ? pathParts[1] : null;
  const secondPart = pathParts[2];
  const thirdPart = pathParts[3];
  const isDesignApp = isKitsPath && secondPart === "designs" && thirdPart && isUuidPattern(thirdPart);
  const isTypeApp = isKitsPath && secondPart === "types" && thirdPart && isUuidPattern(thirdPart);
  const isKitApp = kitId && !isDesignApp && !isTypeApp;

  const kitFromScope = useWipKitOptional();
  const designFromScope = useDesignContext();
  const typeFromScope = useTypeContext();
  const kit: Kit | Kit | null | undefined = (kitFromScope as Kit | Kit | null | undefined) || kits.find((k) => k.id === kitId);
  const kitKind = useKitKind(kitId || "");

  const itemId = isDesignApp || isTypeApp ? thirdPart : null;
  const allDesigns: Design[] = useMemo(() => {
    if (!kit?.designs) return [];
    return (kit.designs as any[]).filter((d): d is Design => typeof d === "object" && d.id !== undefined);
  }, [kit?.designs]);
  const allTypes: Type[] = useMemo(() => {
    if (!kit?.types) return [];
    return (kit.types as any[]).filter((t): t is Type => typeof t === "object" && t.id !== undefined);
  }, [kit?.types]);

  const design = useMemo(() => {
    if (isDesignApp && itemId) {
      return designFromScope || allDesigns.find((d) => d.id === itemId) || null;
    }
    return null;
  }, [isDesignApp, itemId, designFromScope, allDesigns]);

  const type = useMemo(() => {
    if (isTypeApp && itemId) {
      return typeFromScope || allTypes.find((t) => t.id === itemId) || null;
    }
    return null;
  }, [isTypeApp, itemId, typeFromScope, allTypes]);

  const homeKind = !isKitsPath || pathParts.length === 1 ? (searchParams.get("kind") as KitKind | null) : null;
  const homeName = !isKitsPath || pathParts.length === 1 ? searchParams.get("name") : null;
  const homeVersion = !isKitsPath || pathParts.length === 1 ? searchParams.get("version") : null;
  const filteredKind = kitId && !isDesignApp && !isTypeApp ? (searchParams.get("kind") as "designs" | "types" | "qualities" | "files" | "authors" | null) : null;
  const filteredName = kitId && !isDesignApp && !isTypeApp ? searchParams.get("name") : null;

  const upTarget = useMemo(() => {
    const pathWithoutQuery = currentPath.split("?")[0];

    if (homeKind) {
      if (homeVersion !== null && homeName) {
        const params = new URLSearchParams();
        params.set("kind", homeKind);
        params.set("name", homeName);
        return `/?${params.toString()}`;
      }
      if (homeName) {
        const params = new URLSearchParams();
        params.set("kind", homeKind);
        return `/?${params.toString()}`;
      }
      return "/";
    }

    if (pathWithoutQuery === "/") return undefined;
    if (pathWithoutQuery === "/kits") return "/";

    if (isDesignApp && design && typeof design === "object" && "parent" in design) {
      const designObj = design as Design;
      if (designObj.parent) {
        return `/kits/${kitId}/designs/${designObj.parent}`;
      }
      return `/kits/${kitId}?kind=designs`;
    }

    if (isTypeApp && type && typeof type === "object" && "parent" in type) {
      const typeObj = type as Type;
      if (typeObj.parent) {
        return `/kits/${kitId}/types/${typeObj.parent}`;
      }
      return `/kits/${kitId}?kind=types`;
    }

    if (isKitApp) {
      if (filteredKind) {
        const kitObj = kit && typeof kit === "object" && "name" in kit ? (kit as Kit) : null;
        if (kitKind && kitObj) {
          const params = new URLSearchParams();
          params.set("kind", kitKind);
          if (kitObj.name) params.set("name", kitObj.name);
          if (kitObj.version !== undefined && kitObj.version !== null) {
            params.set("version", kitObj.version);
          }
          return `/?${params.toString()}`;
        }
        return `/kits/${kitId}`;
      }
      if (kitId && kitKind) {
        const kitObj = kit && typeof kit === "object" && "name" in kit ? (kit as Kit) : null;
        if (kitObj) {
          const params = new URLSearchParams();
          params.set("kind", kitKind);
          if (kitObj.name) params.set("name", kitObj.name);
          if (kitObj.version !== undefined && kitObj.version !== null) {
            params.set("version", kitObj.version);
          }
          return `/?${params.toString()}`;
        }
        return `/?kind=${kitKind}`;
      }
      return "/";
    }

    return pathWithoutQuery.split("/").slice(0, -1).join("/") || "/";
  }, [currentPath, isDesignApp, isTypeApp, isKitApp, design, type, kitId, filteredKind, filteredName, kitKind, kit, homeKind, homeName, homeVersion]);
  const isAtRoot = currentPath === "/" || (currentPath === "/kits" && !kitId);
  const fullscreenToggleId = isFullscreen ? "semio.sketchpad.navbar.exitFullscreen" : "semio.sketchpad.navbar.fullscreen";

  const navbarItems = useMemo(() => {
    const items: NavbarItem[] = [];
    items.push({
      key: "navigationButtons",
      content: (
        <ButtonGroup id="semio.sketchpad.navbar.navigationButtons">
          <ButtonGroupItem value="back" id="semio.sketchpad.navbar.back" onClick={() => sketchpadCommands.navigateBack("semio.sketchpad.navbar.back")} disabled={!navigationHistory.canGoBack}>
            <NavigateBackIcon size={16} />
          </ButtonGroupItem>
          <ButtonGroupItem value="forward" id="semio.sketchpad.navbar.forward" onClick={() => sketchpadCommands.navigateForward("semio.sketchpad.navbar.forward")} disabled={!navigationHistory.canGoForward}>
            <NavigateForwardIcon size={16} />
          </ButtonGroupItem>
          <ButtonGroupItem
            value="up"
            id="semio.sketchpad.navbar.up"
            onClick={() => {
              if (upTarget) navigate(upTarget);
            }}
            disabled={isAtRoot}
          >
            <NavigateUpIcon size={16} />
          </ButtonGroupItem>
        </ButtonGroup>
      ),
    });
    items.push({ key: "navigation", content: <Navigation />, className: "flex-1 min-w-0" });
    items.push({ key: "search", content: <Search /> });
    items.push({ key: "focus", content: <Focus /> });
    items.push({ key: "panelToggles", content: <PanelToggles /> });
    items.push({
      key: "fullscreenToggle",
      content: (
        <Toggle
          id={fullscreenToggleId}
          pressed={isFullscreen}
          onPressedChange={() => {
            if (typeof document !== "undefined") {
              if (!isFullscreen) {
                const target = document.documentElement;
                if (target && target.requestFullscreen) {
                  const result = target.requestFullscreen();
                  if (result && typeof (result as any).then === "function") {
                    (result as Promise<void>).then(() => sketchpadCommands.toggleFullscreen(fullscreenToggleId)).catch(() => {});
                  } else {
                    sketchpadCommands.toggleFullscreen(fullscreenToggleId);
                  }
                }
              } else {
                if (document.fullscreenElement && document.exitFullscreen) {
                  const result = document.exitFullscreen();
                  if (result && typeof (result as any).then === "function") {
                    (result as Promise<void>).then(() => sketchpadCommands.toggleFullscreen(fullscreenToggleId)).catch(() => {});
                  } else {
                    sketchpadCommands.toggleFullscreen(fullscreenToggleId);
                  }
                }
              }
              return;
            }
            sketchpadCommands.toggleFullscreen(fullscreenToggleId);
          }}
          icon={isFullscreen ? <Minimize2Icon size={16} /> : <Maximize2Icon size={16} />}
        />
      ),
    });
    if (desktop) {
      items.push({
        key: "windowControls",
        className: "ml-single",
        content: (
          <ButtonGroup id="semio.sketchpad.navbar.windowControls">
            <ButtonGroupItem value="minimize" id="semio.sketchpad.navbar.windowControls.minimize" onClick={() => desktop.minimize()}>
              <RemoveIcon size={16} />
            </ButtonGroupItem>
            <ButtonGroupItem value="maximize" id="semio.sketchpad.navbar.windowControls.maximize" onClick={() => desktop.maximize()}>
              <StopIcon size={16} />
            </ButtonGroupItem>
            <ButtonGroupItem value="close" id="semio.sketchpad.navbar.windowControls.close" onClick={() => desktop.close()}>
              <CloseIcon size={16} />
            </ButtonGroupItem>
          </ButtonGroup>
        ),
      });
    }
    return items;
  }, [navigationHistory, upTarget, isAtRoot, navigate, sketchpadCommands, fullscreenToggleId, isFullscreen, desktop]);

  const activeInteraction = useActiveInteraction();
  const panelOpacity = activeInteraction === "dragging" ? 0.3 : 1;
  const rightSidePanelElementSizingClassName = [
    "[&_[data-slot='side-panel-tabs']]:h-medium",
    "[&_[data-slot='side-panel-tab-button']]:px-small",
    "[&_[data-slot='side-panel-tab-button']_svg]:size-small",
    "[&_[data-slot='side-panel-content']]:p-[10px]",
    "[&_[data-slot='tree-item-row']]:min-h-[24px]",
    "[&_[data-slot='tree-item-row']]:py-0",
    "[&_[data-slot='tree-item-row']]:items-center",
    "[&_[data-slot='tree-section-row']]:h-[20px]",
    "[&_[data-slot='tree-section-row']]:py-0",
    "[&_[data-slot='tree-section-row']]:mt-[24px]",
    "[&_[data-slot='tree-section-content']]:gap-y-[6px]",
    "[&_[data-slot='tree-item-content']]:gap-y-[3px]",
    "[&_[data-slslot='input']]:!w-full",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!min-w-0",
    "[&_[data-slot='stepper-group']_[data-slot='input']]:!px-[6px]",
    "[&_[data-slot='slider-row']]:items-center",
    "[&_[data-slot='slider-row']]:gap-x-[8px]",
    "[&_[data-slot='slider-value']]:w-[28px]",
    "[&_[data-slot='slider-value']]:text-right",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!px-0",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!w-[28px]",
    "[&_[data-slot='slider-row']_[data-slot='input']]:!min-w-[28px]",
    "[&_[data-slot='button-group-item']]:h-medium",
    "[&_textarea[data-slot='textarea']]:text-xs",
    "[&_textarea[data-slot='textarea']]:rounded-[3px]",
    "[&_textarea[data-slot='textarea']]:px-[6px]",
    "[&_textarea[data-slot='textarea']]:py-[3px]",
    "[&_textarea[data-slot='textarea']]:min-h-[22px]",
    "[&_[data-collapsed='true'][data-slot='textarea']]:rounded-[3px]",
    "[&_[data-collapsed='true'][data-slot='textarea']]:px-[6px]",
    "[&_[data-collapsed='true'][data-slot='textarea']]:text-xs",
    "[&_[data-collapsed='true'][data-slot='textarea'][data-overflow-layout='single-line']]:!h-[22px]",
    "[&_[role='combobox']]:!h-[22px]",
    "[&_[role='combobox']]:rounded-[3px]",
    "[&_[role='combobox']]:px-[6px]",
    "[&_[role='combobox']]:text-xs",
    "[&_[role='combobox']_svg]:size-[12px]",
  ].join(" ");

  const [activeDragId, setActiveDragId] = useState<string | null>(null);
  const [activeDragData, setActiveDragData] = useState<any>(null);
  const [activeToolbarGroup, setActiveToolbarGroup] = useState<string | null>(null);

  const toolbarToolsZoneRef = useRef<HTMLDivElement>(null);
  const toolbarSettingsZoneRef = useRef<HTMLDivElement>(null);
  const toolbarSettingsContentRef = useRef<HTMLDivElement>(null);
  useSharedLayoutTransition(toolbarToolsZoneRef, "right center", "semio.sketchpad.toolbar.zone.tools");
  // Settings zone spans a fixed right-half band; animate only the w-fit content to keep the band stable.
  useSharedLayoutTransition(toolbarSettingsContentRef, "left center", "semio.sketchpad.toolbar.zone.settings.content");

  const toolbarGroups = useMemo(() => {
    const groups: Record<string, PanelSection[]> = {};
    toolbarSections.forEach((section) => {
      const gid = section.toolbarGroup?.id;
      if (gid) {
        if (!groups[gid]) groups[gid] = [];
        groups[gid].push(section);
      }
    });

    Object.keys(groups).forEach((key) => {
      groups[key].sort((a, b) => (a.toolbarGroup?.order ?? 0) - (b.toolbarGroup?.order ?? 0));
    });
    return groups;
  }, [toolbarSections]);

  const orderedToolbarGroupIds = useMemo(() => {
    const preferredOrder = ["history", "hand", "selection", "filter", "open", "create", "view", "actions"];
    return Object.keys(toolbarGroups).sort((left, right) => {
      const leftOrder = Math.min(...toolbarGroups[left].map((section) => section.toolbarGroup?.order ?? 0));
      const rightOrder = Math.min(...toolbarGroups[right].map((section) => section.toolbarGroup?.order ?? 0));
      if (leftOrder !== rightOrder) return leftOrder - rightOrder;
      const leftPreferredOrder = preferredOrder.indexOf(left);
      const rightPreferredOrder = preferredOrder.indexOf(right);
      return (leftPreferredOrder === -1 ? Number.MAX_SAFE_INTEGER : leftPreferredOrder) - (rightPreferredOrder === -1 ? Number.MAX_SAFE_INTEGER : rightPreferredOrder);
    });
  }, [toolbarGroups]);

  useEffect(() => {
    const firstGroup = orderedToolbarGroupIds.find((groupId) => groupId !== "history" && groupId !== "hand" && toolbarGroups[groupId]);
    setActiveToolbarGroup((prev) => (prev === null || (prev !== null && !toolbarGroups[prev]) ? (firstGroup ?? null) : prev));
  }, [toolbarGroups, orderedToolbarGroupIds]);

  const toolbarGroupsRef = useRef(toolbarGroups);
  toolbarGroupsRef.current = toolbarGroups;
  const toggleToolbarGroup = useCallback((id: string) => {
    setActiveToolbarGroup((prev) => {
      const next = prev === id ? null : id;
      if (next) {
        queueMicrotask(() => {
          const groups = toolbarGroupsRef.current;
          if (groups[next]) {
            for (const section of groups[next]) {
              section.toolbarGroup?.onActivate?.();
            }
          }
        });
      }
      return next;
    });
  }, []);

  const getGroupIcon = useCallback((groupId: string) => {
    switch (groupId) {
      case "hand":
        return <HandIcon className="size-tiny" />;
      case "selection":
        return <MousePointerIcon className="size-tiny" />;
      case "filter":
        return <SearchIcon className="size-tiny" />;
      case "open":
        return <FolderIcon className="size-tiny" />;
      case "create":
        return <AddIcon className="size-tiny" />;
      case "view":
        return <LayoutIcon className="size-tiny" />;
      case "actions":
        return <MoreHorizontalIcon className="size-tiny" />;
      default:
        return <FocusIcon className="size-tiny" />;
    }
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
  );

  const customCollisionDetection = useCallback((args: any) => {
    const pointerCollisions = pointerWithin(args);

    if (pointerCollisions.length > 0) {
      return pointerCollisions;
    }

    const rectCollisions = rectIntersection(args);

    if (rectCollisions.length > 0) {
      return rectCollisions;
    }

    const centerCollisions = closestCenter(args);

    if (centerCollisions && centerCollisions.length > 0) {
      return centerCollisions;
    }
    return [];
  }, []);
  const getTypeOrDesignName = useCallback(() => {
    if (!activeDragData) return null;
    if (activeDragData.type === "type") {
      const kitId = activeDragData.typeId?.split("-")[0];
      const kit = kits.find((k) => k.id.startsWith(kitId));
      const type = kit?.types?.find((t: any) => typeof t === "object" && t.id === activeDragData.typeId) as any;
      return type?.name || "Type";
    } else if (activeDragData.type === "design") {
      const kitId = activeDragData.designId?.split("-")[0];
      const kit = kits.find((k) => k.id.startsWith(kitId));
      const design = kit?.designs?.find((d: any) => typeof d === "object" && d.id === activeDragData.designId) as any;
      return design?.name || "Design";
    }
    return null;
  }, [activeDragData, kits]);
  return (
    <TutorialProvider store={tutorialStore}>
      <GlobalFooterItems />
      <DndContext
        sensors={sensors}
        collisionDetection={customCollisionDetection}
        onDragStart={(event) => {
          setActiveDragId(event.active.id as string);
          setActiveDragData(event.active.data.current);

          sketchpadCommands.setActiveInteraction("semio.sketchpad.drag", "dragging");
        }}
        onDragEnd={(event) => {
          setActiveDragId(null);
          setActiveDragData(null);

          sketchpadCommands.setActiveInteraction("semio.sketchpad.drag", undefined);

          const customEvent = new CustomEvent("design-drag-end", { detail: event });
          window.dispatchEvent(customEvent);
        }}
      >
        <LevelProvider level="base">
          <ToolbarContextHost>
            <LayoutComponent
              className="bg-base text-foreground relative border"
              navbar={<Navbar items={navbarItems} />}
              footer={
                <Footer
                  items={footerItems.map((item) => ({
                    id: item.id,
                    icon: item.icon,
                    text: item.text,
                    content: item.content,
                    order: item.order,
                    onClick: item.onClick,
                  }))}
                  isVisible={isFooterExpanded || !isFullscreen}
                />
              }
              bottomPanel={
                consoleSections.length > 0
                  ? {
                      visible: true,
                      size: panelSizes.consoleHeight,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "consoleHeight", size),
                      sections: consoleSections,
                      panelKey: "console",
                    }
                  : undefined
              }
              leftSidePanel={
                leftSidePanelTabs.length > 0 && panelVisibility.leftSidePanel
                  ? {
                      position: "left" as const,
                      visible: true,
                      size: panelSizes.leftSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "leftSidePanelWidth", size),
                      tabs: leftSidePanelTabs,
                      activeTabId: activeLeftTabId,
                      onActiveTabChange: setActiveLeftTabId,
                    }
                  : undefined
              }
              rightSidePanel={(() => {
                if (panelVisibility.chat) {
                  const chatTab: SidePanelTab = {
                    id: `semio.sketchpad.app.${appType}.chat`,
                    icon: ChatIcon,
                    order: 0,
                    content: () => {
                      switch (appType) {
                        case "home":
                          return (
                            <TreeStateProvider>
                              <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.home.chat.content", label: null, content: <ChatPlaceholder /> }]} />
                            </TreeStateProvider>
                          );
                        case "kit":
                          return <BasicChatPanel id="semio.sketchpad.app.kit.chat" title="Kit" />;
                        case "design":
                          return <BasicChatPanel id="semio.sketchpad.app.design.chat" title="Design" />;
                        case "type":
                          return <BasicChatPanel id="semio.sketchpad.app.type.chat" title="Type" />;
                        case "docs":
                          return <BasicChatPanel id="semio.sketchpad.app.docs.chat" title="Docs" />;
                        default:
                          return <BasicChatPanel id={`semio.sketchpad.app.${appType}.chat`} title={appType} />;
                      }
                    },
                  };
                  return {
                    position: "right" as const,
                    visible: true,
                    size: panelSizes.rightSidePanelWidth,
                    onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "rightSidePanelWidth", size),
                    tabs: [chatTab],
                    activeTabId: chatTab.id,
                    onActiveTabChange: () => {},
                    minSize: 150,
                    maxSize: 500,
                    className: rightSidePanelElementSizingClassName,
                  };
                }
                if (panelVisibility.settings) {
                  const settingsTab: SidePanelTab = {
                    id: `semio.sketchpad.app.${appType}.settings`,
                    icon: SettingsIcon,
                    order: 0,
                    content: () => {
                      switch (appType) {
                        case "home":
                          return (
                            <TreeStateProvider>
                              <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.home.settings.content", label: null, content: <SettingsContent /> }]} />
                            </TreeStateProvider>
                          );
                        case "kit":
                          return (
                            <TreeStateProvider>
                              <Tree
                                className="min-w-0 overflow-hidden p-double"
                                sections={[
                                  {
                                    id: "semio.sketchpad.app.kit.settings.content",
                                    label: null,
                                    content: (
                                      <>
                                        <KitEditorSettingsContent />
                                        <SketchpadSettingsContent />
                                      </>
                                    ),
                                  },
                                ]}
                              />
                            </TreeStateProvider>
                          );
                        case "design":
                          return (
                            <TreeStateProvider>
                              <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.design.settings.content", label: null, content: <DesignSettingsContent /> }]} />
                            </TreeStateProvider>
                          );
                        case "type":
                          return (
                            <TreeStateProvider>
                              <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.type.settings.content", label: null, content: <TypeSettingsContent /> }]} />
                            </TreeStateProvider>
                          );
                        case "docs":
                          return (
                            <TreeStateProvider>
                              <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "semio.sketchpad.app.docs.settings.content", label: null, content: <Settings /> }]} />
                            </TreeStateProvider>
                          );
                        default:
                          return <UtilityFallbackSettingsContent appType={appType} />;
                      }
                    },
                  };
                  return {
                    position: "right" as const,
                    visible: true,
                    size: panelSizes.rightSidePanelWidth,
                    onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "rightSidePanelWidth", size),
                    tabs: [settingsTab],
                    activeTabId: settingsTab.id,
                    onActiveTabChange: () => {},
                    minSize: 150,
                    maxSize: 500,
                    className: rightSidePanelElementSizingClassName,
                  };
                }
                if (rightSidePanelTabs.length > 0 && panelVisibility.rightSidePanel) {
                  return {
                    position: "right" as const,
                    visible: true,
                    size: panelSizes.rightSidePanelWidth,
                    onSizeChange: (size: number) => sketchpadCommands.setPanelSize("semio.sketchpad", "rightSidePanelWidth", size),
                    tabs: rightSidePanelTabs,
                    activeTabId: activeRightTabId,
                    onActiveTabChange: setActiveRightTabId,
                    minSize: 150,
                    maxSize: 500,
                    className: rightSidePanelElementSizingClassName,
                  };
                }
                return undefined;
              })()}
              toolbar={
                panelVisibility.toolbar || appType === "type" || appType === "design" || appType === "feedback" || appType === "kit" || appType === "home" || appType === "docs" ? (
                  toolbarSections.length > 0 ? (
                    <div role="toolbar" id="semio.sketchpad.toolbar" className="pointer-events-none absolute bottom-1.5 left-0 right-0 h-[40px] w-full max-w-full px-2">
                      <div id="semio.sketchpad.toolbar.seam" className="absolute left-1/2 top-0 h-full w-0 -translate-x-1/2 pointer-events-none" aria-hidden />
                      <div ref={toolbarToolsZoneRef} id="semio.sketchpad.toolbar.zone.tools" className="absolute top-0 left-0 h-full max-w-[calc(50vw-1rem)] right-[calc(50%_+_4px)] pointer-events-auto flex items-center justify-end">
                        <LevelProvider level="panel">
                          <ToolbarZone>
                            {toolbarGroups.history && (
                              <ToolbarContextHost>
                                {toolbarGroups.history.map((section) => {
                                  return <ToolbarItem key={section.id}>{typeof section.content === "function" ? section.content() : section.content}</ToolbarItem>;
                                })}
                              </ToolbarContextHost>
                            )}
                            {orderedToolbarGroupIds
                              .filter((groupId) => groupId !== "history")
                              .map((groupId) => {
                                if (!toolbarGroups[groupId]) return null;
                                const isActive = activeToolbarGroup === groupId;

                                return (
                                  <Toggle
                                    key={groupId}
                                    kind="single"
                                    id={`semio.sketchpad.toolbar.group.${groupId}`}
                                    pressed={isActive}
                                    onPressedChange={() => toggleToolbarGroup(groupId)}
                                    icon={getGroupIcon(groupId)}
                                    text={resolveTranslationLabel(i18n.t(`semio.sketchpad.toolbar.parent.${groupId}`))}
                                  />
                                );
                              })}
                          </ToolbarZone>
                        </LevelProvider>
                      </div>

                      {activeToolbarGroup && toolbarGroups[activeToolbarGroup] && (
                        <div ref={toolbarSettingsZoneRef} id="semio.sketchpad.toolbar.zone.settings" className="absolute top-0 left-[calc(50%_+_4px)] right-0 h-full min-w-0 pointer-events-auto flex items-center justify-start">
                          <LevelProvider level="panel">
                            <div ref={toolbarSettingsContentRef} className="flex w-fit max-w-full shrink-0">
                              <ToolbarZone className="w-fit max-w-full shrink-0 flex-nowrap">
                                <ToolbarContextHost>
                                  {toolbarGroups[activeToolbarGroup]?.map((section) => {
                                    return <ToolbarItem key={section.id}>{typeof section.content === "function" ? section.content() : section.content}</ToolbarItem>;
                                  })}
                                </ToolbarContextHost>
                              </ToolbarZone>
                            </div>
                          </LevelProvider>
                        </div>
                      )}
                    </div>
                  ) : (
                    <div id="semio.sketchpad.toolbar" className="hidden" />
                  )
                ) : undefined
              }
              canvas={
                <div className="relative h-full w-full">
                  <AppRouter />
                </div>
              }
            />
          </ToolbarContextHost>
        </LevelProvider>
        <DragOverlay>
          {activeDragId && activeDragData ? (
            <div className="cursor-grabbing">
              <div className="border border-element rounded-full w-small h-small flex items-center justify-center shadow-lg">
                <span className="text-small font-medium select-none">{getTypeOrDesignName()?.substring(0, 2).toUpperCase() || "?"}</span>
              </div>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </TutorialProvider>
  );
};
/**
 * SketchpadInteractionBridge holds the data fields for a SketchpadInteractionBridge record.
 **/
const SketchpadInteractionBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const sketchpadCommands = useSketchpadCommands();
  const activeInteraction = useActiveInteraction();

  const interactionCommands = useMemo(
    () => ({
      setActiveInteraction: (elementId?: string, interactionId?: string) => {
        sketchpadCommands.setActiveInteraction(elementId || "semio.interaction", interactionId);
      },
    }),
    [sketchpadCommands],
  );

  return (
    <InteractionProvider commands={interactionCommands} activeInteraction={activeInteraction}>
      {children}
    </InteractionProvider>
  );
};
/**
 * GlobalNavigationBridge holds the data fields for a GlobalNavigationBridge record.
 **/
const GlobalNavigationBridge: FC<{ children: React.ReactNode }> = ({ children }) => {
  const reactNavigate = useReactNavigate();

  useEffect(() => {
    if (typeof window !== "undefined") {
      (window as any).__SEMIO_NAVIGATE__ = reactNavigate;
    }
    return () => {
      if (typeof window !== "undefined") {
        delete (window as any).__SEMIO_NAVIGATE__;
      }
    };
  }, [reactNavigate]);

  return <>{children}</>;
};
/**
 * SketchpadContent holds the data fields for a SketchpadContent record.
 **/
const SketchpadContent: FC = () => {
  return <LayoutWrapper />;
};
/**
 * Sketchpad holds the data fields for a Sketchpad record.
 **/
/**
 * Host shell: persistence is opened via {@link useAttachBackbone} from `@semio/react` inside kit UI (WIP until JS stores land); factories here only bridge pickers → registry.
 */
const Sketchpad = ({
  id,
  store,
  remote,
  persistenceFactory,
  temporaryKitStoreFactory,
  folderKitStoreFactory,
  fileKitStoreFactory,
  remoteKitStoreFactory,
  desktop,
  initialState,
  importKitUrls,
  embedded,
}: {
  id?: string;
  store?: SketchpadStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  temporaryKitStoreFactory?: SketchpadKitStoreFactory;
  folderKitStoreFactory?: SketchpadKitStoreFactory;
  fileKitStoreFactory?: SketchpadKitStoreFactory;
  remoteKitStoreFactory?: SketchpadKitStoreFactory;
  desktop?: Desktop;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  embedded?: boolean;
}): React.JSX.Element => {
  const initialEntries = useMemo(() => {
    if (!embedded) return undefined;
    if (typeof window !== "undefined" && window.location) {
      return [window.location.pathname + window.location.search];
    }
    return ["/"];
  }, [embedded]);

  const routerContent = (
    <GlobalNavigationBridge>
      <KitStoreProvider>
        <SketchpadInstanceProvider
          id={id}
          store={store}
          remote={remote}
          persistenceFactory={persistenceFactory}
          temporaryKitStoreFactory={temporaryKitStoreFactory}
          folderKitStoreFactory={folderKitStoreFactory}
          fileKitStoreFactory={fileKitStoreFactory}
          remoteKitStoreFactory={remoteKitStoreFactory}
          desktop={desktop}
          initialState={initialState}
          importKitUrls={importKitUrls}
        >
          <SketchpadInteractionBridge>
            <OriginDocumentListener />
            <SketchpadContent />
          </SketchpadInteractionBridge>
        </SketchpadInstanceProvider>
      </KitStoreProvider>
    </GlobalNavigationBridge>
  );

  if (embedded) {
    return (
      <MemoryRouter initialEntries={initialEntries} unstable_useTransitions={false}>
        {routerContent}
      </MemoryRouter>
    );
  }

  return <BrowserRouter unstable_useTransitions={false}>{routerContent}</BrowserRouter>;
};

