// #region 🏗️Design Family Helpers
// Design family helper functions MUST traverse the design hierarchy to collect related design IDs.

/** getDesignFamilyIds holds the data fields for a getDesignFamilyIds record.
 **/
/**
 **/
const getDesignFamilyIds = (kit: Kit, designId: string): Set<string> => {
  const ids = new Set<string>();

  let currentId = designId;
  let current = kit.designs?.find((d) => d.id === currentId);
  while (current?.parent?.id) {
    const parent = kit.designs?.find((d) => d.id === current!.parent!.id);
    if (!parent) break;
    current = parent;
    currentId = parent.id;
  }

  const collectDescendants = (parentId: string) => {
    ids.add(parentId);
    const children = (kit.designs || []).filter((d) => d.parent?.id === parentId);
    children.forEach((child) => collectDescendants(child.id));
  };
  collectDescendants(currentId);

  return ids;
};

