// 📑#region 📌Design
const KitSectionLazy = KitSection;

/**
 * Tracks the current piece, connection, and connector selection state for the Design app.
 **/
export interface DesignAppSelection {
  pieces?: Id[];
  connections?: Id[];
  connectors?: Array<{ piece: Id; connector: Id }>;
  connector?: { piece: Id; designPiece?: Id; connector: Id };
}

/**
 * Normalizes an individual design connector selection record.
 *
 * MUST reject incomplete records and preserve the optional design piece ID.
 **/
const normalizeDesignConnectorRecord = (connector: { piece?: Id; designPiece?: Id; connector?: Id } | undefined): DesignAppSelection["connector"] | undefined => {
  if (!connector?.piece || !connector?.connector) return undefined;
  return connector.designPiece ? { piece: connector.piece, connector: connector.connector, designPiece: connector.designPiece } : { piece: connector.piece, connector: connector.connector };
};

/**
 * Returns the primary selected connector from the design selection shape.
 *
 * MUST normalize both singular and array connector selection representations to one record.
 **/
const getPrimaryDesignConnectorSelection = (selection: DesignAppSelection | undefined): DesignAppSelection["connector"] | undefined => {
  const primary = normalizeDesignConnectorRecord(selection?.connector);
  if (primary) return primary;
  for (const connector of selection?.connectors ?? []) {
    const normalizedConnector = normalizeDesignConnectorRecord(connector);
    if (normalizedConnector) return normalizedConnector;
  }
  return undefined;
};

/**
 * Normalizes the design selection shape into the canonical connector-selection representation.
 *
 * MUST keep the singular and array connector lanes in sync and collapse empty arrays to undefined.
 **/
const normalizeDesignAppSelection = (selection: DesignAppSelection | undefined): DesignAppSelection => {
  const normalizedSelection: DesignAppSelection = {};

  if (selection?.pieces?.length) normalizedSelection.pieces = selection.pieces;
  if (selection?.connections?.length) normalizedSelection.connections = selection.connections;

  const normalizedConnector = getPrimaryDesignConnectorSelection(selection);
  if (normalizedConnector) {
    normalizedSelection.connector = normalizedConnector;
    normalizedSelection.connectors = [normalizedConnector];
  }

  return normalizedSelection;
};

/**
 * Builds a normalized design connector selection payload.
 *
 * MUST keep both singular and array connector lanes in sync while clearing piece and connection selection.
 **/
const createDesignConnectorSelection = (pieceId: Id, connectorId: Id, designPieceId?: Id): DesignAppSelection => {
  const connectorSelection = designPieceId ? { piece: pieceId, connector: connectorId, designPiece: designPieceId } : { piece: pieceId, connector: connectorId };
  return normalizeDesignAppSelection({
    pieces: [],
    connections: [],
    connector: connectorSelection,
    connectors: [connectorSelection],
  });
};

/**
 * Removes connector-specific selection lanes from a design selection.
 *
 * MUST preserve all non-connector selection data.
 **/
const stripDesignConnectorSelection = (selection: DesignAppSelection | undefined): DesignAppSelection => {
  const { connector: _connector, connectors: _connectors, ...rest } = selection ?? {};
  return normalizeDesignAppSelection(rest);
};
/**
 * Diff for added/removed piece IDs in a selection change.
 **/
export interface DesignAppSelectionPiecesDiff {
  added?: Id[];
  removed?: Id[];
}
/**
 * Diff for added/removed connection IDs in a selection change.
 **/
export interface DesignAppSelectionConnectionsDiff {
  added?: Id[];
  removed?: Id[];
}
/**
 * Diff for a selected port change identifying the piece and connector.
 **/
export interface DesignAppSelectionPortDiff {
  piece?: Id;
  designPiece?: Id;
  connector?: Id;
}
/**
 * Composite diff combining pieces, connections, and connector selection changes.
 **/
export interface DesignAppSelectionDiff {
  pieces?: DesignAppSelectionPiecesDiff;
  connections?: DesignAppSelectionConnectionsDiff;
  connector?: DesignAppSelectionPortDiff;
}
/**
 * Enumeration of window kinds available in the Design app.
 **/
export enum DesignAppWindowKind {
  Diagram = "diagram",
  Scene = "scene",
  Settings = "settings",
  Chat = "chat",
}
/**
 * Presence state for a Design app user including cursor, camera, and diagram viewport.
 **/
export interface DesignAppPresence {
  cursor?: Coordinate;
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
}
/**
 * Hover state tracking which pieces, connections, connectors, types, and designs are hovered.
 **/
export interface DesignAppHover {
  pieces?: Id[];
  connections?: Id[];
  connectors?: { piece: Id; designPiece?: Id; connector: Id }[];
  types?: Id[];
  designs?: Id[];
}
/**
 * Extended presence for other collaborators including their display name.
 **/
export interface DesignAppPresenceOther extends DesignAppPresence {
  name: string;
}
/**
 * Complete diff describing all mutable Design app state changes.
 **/
export interface DesignAppDiff {
  selection?: DesignAppSelectionDiff;
  presence?: DesignAppPresence;
  hover?: DesignAppHover;
  fullscreenWindow?: DesignAppFullscreenWindow;
  panelVisibility?: Partial<PanelVisibility>;
  activeTool?: ToolKind;
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
  focusedPieceId?: Id | null;
  selectedRepresentationTags?: Record<Id, string[]>;
  windowLayout?: any;
}
/**
 * Edit record extending KitDiffAppEdit with Design app selection diff.
 **/
export interface DesignAppEdit extends KitDiffAppEdit<DesignAppSelectionDiff> {}
/**
 * Complete runtime state for a Design app instance.
 **/
export interface DesignAppState {
  fullscreenWindow: DesignAppFullscreenWindow;
  panelVisibility: PanelVisibility;
  activeTool?: ToolKind;
  selection?: DesignAppSelection;
  hover?: DesignAppHover;
  presence?: DesignAppPresence;
  others: DesignAppPresenceOther[];
  camera?: Camera;
  diagramCenter?: Coordinate;
  diagramScale?: number;
  focusedPieceId?: Id;
  currentTransactionStackLength?: number;
  selectedRepresentationTags?: Record<Id, string[]>;
  windowLayout?: any;
}

/**
 * Context passed to Design app commands including app state, ID, and design data.
 **/
export interface DesignAppCommandContext extends KitCommandContext {
  designApp: DesignAppState;
  Id: Id;
  design: Design;
}
/**
 * Result returned by Design app commands containing diffs to apply.
 **/
export interface DesignAppCommandResult extends KitDiffAppCommandResult<DesignAppDiff> {
  diff?: DesignAppDiff;
}

// #endregion 📌Types

// #region 💧Commands
// Commands MUST define all executable Design app actions dispatched by keyboard shortcuts and UI interactions.

/**
 * Registry of all named Design app commands mapped to their handler functions.
 **/
export const designAppCommands: Record<string, (context: DesignAppCommandContext, ...args: any[]) => DesignAppCommandResult> = {
  "semio.designApp.selectAll": (context: DesignAppCommandContext): DesignAppCommandResult => {
    const allPieceIds = context.design.pieces?.map((p: Piece) => p.id) || [];
    const allConnectionIds = context.design.connections?.map((c: Connection) => c.id) || [];
    return {
      diff: {
        selection: {
          pieces: {
            added: allPieceIds,
          },
          connections: {
            added: allConnectionIds,
          },
        },
      },
    };
  },
  "semio.designApp.deselectAll": (context: DesignAppCommandContext): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentPieces = currentSelection.pieces || [];
    const currentConnections = currentSelection.connections || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: currentPieces,
          },
          connections: {
            removed: currentConnections,
          },
          connector: {},
        },
      },
    };
  },
  "semio.designApp.deleteSelected": (context: DesignAppCommandContext): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const selectedPieces = currentSelection.pieces || [];
    const selectedConnections = currentSelection.connections || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: selectedPieces,
          },
          connections: {
            removed: selectedConnections,
          },
        },
      },
      kitGraph: {
        op: "removeDesignPiecesAndConnections",
        designId: context.design.id,
        pieceIds: selectedPieces,
        connectionIds: selectedConnections,
      },
    };
  },
  "semio.designApp.hoverPiece": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          pieces: [id],
        },
      },
    };
  },
  "semio.designApp.hoverPieces": (context: DesignAppCommandContext, ids: Id[]): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          pieces: ids,
        },
      },
    };
  },
  "semio.designApp.hoverConnection": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          connections: [id],
        },
      },
    };
  },
  "semio.designApp.hoverConnections": (context: DesignAppCommandContext, ids: Id[]): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          connections: ids,
        },
      },
    };
  },
  "semio.designApp.hoverPort": (context: DesignAppCommandContext, pieceId: Id, connectorId: Id, designPieceId?: Id): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          connectors: [{ piece: pieceId, designPiece: designPieceId, connector: connectorId }],
        },
      },
    };
  },
  "semio.designApp.hoverType": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          types: [id],
        },
      },
    };
  },
  "semio.designApp.hoverTypes": (context: DesignAppCommandContext, ids: Id[]): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          types: ids,
        },
      },
    };
  },
  "semio.designApp.hoverDesign": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          designs: [id],
        },
      },
    };
  },
  "semio.designApp.hoverDesigns": (context: DesignAppCommandContext, ids: Id[]): DesignAppCommandResult => {
    return {
      diff: {
        hover: {
          designs: ids,
        },
      },
    };
  },
  "semio.designApp.clearHover": (context: DesignAppCommandContext): DesignAppCommandResult => {
    return {
      diff: {
        hover: {},
      },
    };
  },
  "semio.designApp.setCamera": (context: DesignAppCommandContext, camera: Camera): DesignAppCommandResult => {
    return {
      diff: {
        camera,
      },
    };
  },
  "semio.designApp.focusPiece": (context: DesignAppCommandContext, pieceId: Id): DesignAppCommandResult => {
    return {
      diff: {
        focusedPieceId: pieceId,
      },
    };
  },
  "semio.designApp.clearFocus": (context: DesignAppCommandContext): DesignAppCommandResult => {
    return {
      diff: {
        focusedPieceId: undefined,
      },
    };
  },
  "semio.designApp.setDiagramCenter": (context: DesignAppCommandContext, center: Coordinate): DesignAppCommandResult => {
    return {
      diff: {
        diagramCenter: center,
      },
    };
  },
  "semio.designApp.setDiagramScale": (context: DesignAppCommandContext, scale: number): DesignAppCommandResult => {
    return {
      diff: {
        diagramScale: scale,
      },
    };
  },
  "semio.designApp.toggleDiagramFullscreen": (context: DesignAppCommandContext): DesignAppCommandResult => {
    const currentFullscreen = context.designApp.fullscreenWindow;
    return {
      diff: {
        fullscreenWindow: currentFullscreen === DesignAppFullscreenWindow.Diagram ? DesignAppFullscreenWindow.None : DesignAppFullscreenWindow.Diagram,
      },
    };
  },
  "semio.designApp.toggleAccesslFullscreen": (context: DesignAppCommandContext): DesignAppCommandResult => {
    const currentFullscreen = context.designApp.fullscreenWindow;
    return {
      diff: {
        fullscreenWindow: currentFullscreen === DesignAppFullscreenWindow.Accessl ? DesignAppFullscreenWindow.None : DesignAppFullscreenWindow.Accessl,
      },
    };
  },
  "semio.designApp.setActiveTool": (context: DesignAppCommandContext, tool: ToolKind): DesignAppCommandResult => {
    return {
      diff: {
        activeTool: tool,
      },
    };
  },
  "semio.designApp.selectPiece": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentPieces = currentSelection.pieces || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: currentPieces,
            added: [id],
          },
          connections: {
            removed: currentSelection.connections || [],
          },
          connector: {},
        },
      },
    };
  },
  "semio.designApp.selectPieces": (context: DesignAppCommandContext, ids: Id[]): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentPieces = currentSelection.pieces || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: currentPieces,
            added: ids,
          },
          connections: {
            removed: currentSelection.connections || [],
          },
          connector: {},
        },
      },
    };
  },
  "semio.designApp.addPieceToSelection": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentPieces = currentSelection.pieces || [];
    if (currentPieces.includes(id)) {
      return { diff: {} };
    }
    return {
      diff: {
        selection: {
          pieces: {
            added: [id],
          },
        },
      },
    };
  },
  "semio.designApp.removePieceFromSelection": (context: DesignAppCommandContext, id: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentPieces = currentSelection.pieces || [];
    if (!currentPieces.includes(id)) {
      return { diff: {} };
    }
    return {
      diff: {
        selection: {
          pieces: {
            removed: [id],
          },
        },
      },
    };
  },
  "semio.designApp.selectConnection": (context: DesignAppCommandContext, connectionId: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentConnections = currentSelection.connections || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: currentSelection.pieces || [],
          },
          connections: {
            removed: currentConnections,
            added: [connectionId],
          },
          connector: {},
        },
      },
    };
  },
  "semio.designApp.addConnectionToSelection": (context: DesignAppCommandContext, connectionId: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentConnections = currentSelection.connections || [];
    if (currentConnections.includes(connectionId)) {
      return { diff: {} };
    }
    return {
      diff: {
        selection: {
          connections: {
            added: [connectionId],
          },
        },
      },
    };
  },
  "semio.designApp.removeConnectionFromSelection": (context: DesignAppCommandContext, connectionId: Id): DesignAppCommandResult => {
    const currentSelection = context.designApp.selection || {};
    const currentConnections = currentSelection.connections || [];
    if (!currentConnections.includes(connectionId)) {
      return { diff: {} };
    }
    return {
      diff: {
        selection: {
          connections: {
            removed: [connectionId],
          },
        },
      },
    };
  },
  "semio.designApp.selectPiecePort": (context: DesignAppCommandContext, piece: Id, connector: Id, designPiece?: Id): DesignAppCommandResult => {
    return {
      diff: {
        selection: {
          pieces: {
            removed: context.designApp.selection?.pieces || [],
          },
          connections: {
            removed: context.designApp.selection?.connections || [],
          },
          connector: {
            piece,
            connector,
            designPiece,
          },
        },
      },
    };
  },
  "semio.designApp.deselectPiecePort": (context: DesignAppCommandContext): DesignAppCommandResult => {
    return {
      diff: {
        selection: {
          connector: {},
        },
      },
    };
  },
  "semio.designApp.addPiece": (context: DesignAppCommandContext, piece: Piece): DesignAppCommandResult => {
    return {
      kitGraph: { op: "addDesignPiece", designId: context.design.id, piece },
    };
  },
  "semio.designApp.addPieces": (context: DesignAppCommandContext, pieces: Piece[]): DesignAppCommandResult => {
    return {
      kitGraph: { op: "addDesignPieces", designId: context.design.id, pieces },
    };
  },
  "semio.designApp.removePiece": (context: DesignAppCommandContext, pieceId: Id): DesignAppCommandResult => {
    return {
      kitGraph: { op: "removeDesignPiece", designId: context.design.id, pieceId },
    };
  },
  "semio.designApp.removePieces": (context: DesignAppCommandContext, pieceIds: Id[]): DesignAppCommandResult => {
    return {
      kitGraph: { op: "removeDesignPieces", designId: context.design.id, pieceIds },
    };
  },
  "semio.designApp.addConnection": (context: DesignAppCommandContext, connection: Connection): DesignAppCommandResult => {
    if (connection.u === undefined || connection.v === undefined) {
      const parentPiece = context.design.pieces?.find((p: Piece) => p.id === connection.connected?.piece?.id);
      const childPiece = context.design.pieces?.find((p: Piece) => p.id === connection.connecting?.piece?.id);
      if (parentPiece?.center && childPiece?.center) {
        connection.u = childPiece.center.u - parentPiece.center.u;
        connection.v = childPiece.center.v - parentPiece.center.v;
      }
    }
    return {
      kitGraph: { op: "addDesignConnection", designId: context.design.id, connection },
    };
  },
  "semio.designApp.addConnections": (context: DesignAppCommandContext, connections: Connection[]): DesignAppCommandResult => {
    return {
      kitGraph: { op: "addDesignConnections", designId: context.design.id, connections },
    };
  },
  "semio.designApp.removeConnection": (context: DesignAppCommandContext, connectionId: Id): DesignAppCommandResult => {
    return {
      kitGraph: { op: "deleteConnection", designId: context.design.id, connectionId },
    };
  },
  "semio.designApp.removeConnections": (context: DesignAppCommandContext, connectionIds: Id[]): DesignAppCommandResult => {
    return {
      kitGraph: { op: "deleteConnections", designId: context.design.id, connectionIds },
    };
  },
  "semio.designApp.updatePiece": (context: DesignAppCommandContext, pieceId: Id, pieceDiff: PieceDiff): DesignAppCommandResult => {
    return {
      kitGraph: { op: "patchPiece", designId: context.design.id, pieceId, diff: pieceDiff },
    };
  },
  "semio.designApp.updatePieces": (context: DesignAppCommandContext, updates: { piece: PieceId; diff: PieceDiff }[]): DesignAppCommandResult => {
    return {
      kitGraph: { op: "patchPieces", designId: context.design.id, updates },
    };
  },
  "semio.designApp.updateConnection": (context: DesignAppCommandContext, connectionId: Id, connectionDiff: ConnectionDiff): DesignAppCommandResult => {
    const connection = context.design.connections?.find((c) => c.id === connectionId);
    if (!connection) {
      return {};
    }
    return {
      kitGraph: { op: "patchConnection", designId: context.design.id, connectionId: String(connectionId), diff: connectionDiff },
    };
  },
  "semio.designApp.updateConnections": (context: DesignAppCommandContext, updates: { connection: ConnectionId; diff: ConnectionDiff }[]): DesignAppCommandResult => {
    const rows = updates.map((u) => {
      const raw = u.connection as any;
      const cid = typeof raw === "string" ? raw : raw?.id != null ? String(raw.id) : "";
      return { id: cid, diff: u.diff };
    });
    return {
      kitGraph: { op: "patchConnectionMany", designId: context.design.id, rows },
    };
  },
  "semio.designApp.clusterPieces": (context: DesignAppCommandContext, pieceIds: Id[]): DesignAppCommandResult => {
    if (!pieceIds || pieceIds.length === 0) {
      return {};
    }
    const designPieceIds = new Set((context.design.pieces || []).map((piece) => piece.id));
    const validPieceIds = pieceIds.filter((id) => designPieceIds.has(id));
    if (validPieceIds.length === 0) {
      return {};
    }
    const existingNames = (context.kit.designs || []).map((d) => d.name);
    const clusterName = generateUniqueName(`${context.design.name} Cluster`, existingNames);
    const currentSelection = context.designApp.selection || {};
    const piecesRemoved = currentSelection.pieces || [];
    const connectionsRemoved = currentSelection.connections || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: piecesRemoved,
          },
          connections: {
            removed: connectionsRemoved,
          },
        },
      },
      kitGraph: {
        op: "clusterPieces",
        designId: context.design.id,
        pieceIds: validPieceIds,
        clusterName,
      },
    };
  },
  "semio.designApp.expandDesign": (context: DesignAppCommandContext, designId: Id): DesignAppCommandResult => {
    if (!designId) {
      return {};
    }
    const referencedDesign = (context.kit.designs || []).find((d) => d.id === designId);
    if (!referencedDesign) {
      return {};
    }
    const currentSelection = context.designApp.selection || {};
    const piecesRemoved = currentSelection.pieces || [];
    const connectionsRemoved = currentSelection.connections || [];
    return {
      diff: {
        selection: {
          pieces: {
            removed: piecesRemoved,
          },
          connections: {
            removed: connectionsRemoved,
          },
        },
      },
      kitGraph: { op: "expandDesign", parentDesignId: context.design.id, nestedDesignId: designId },
    };
  },
};

// #endregion 💧Commands

// #region 🎈Store
// Store MUST implement DesignStore extending PlainKitDiffAppStore with undo/redo, selection diff inversion, and state persistence.

/**
 * Computes the inverse of a Design app selection diff for undo support.
 *MUST return a diff that reverses the given selection diff.
 **/
export const inverseDesignAppSelectionDiff = (selection: DesignAppSelection, diff: DesignAppSelectionDiff): DesignAppSelectionDiff => {
  const inverseDiff: DesignAppSelectionDiff = {};

  if (diff.pieces) {
    inverseDiff.pieces = {};
    if (diff.pieces.added) {
      inverseDiff.pieces.removed = diff.pieces.added;
    }
    if (diff.pieces.removed) {
      inverseDiff.pieces.added = diff.pieces.removed;
    }
  }

  if (diff.connections) {
    inverseDiff.connections = {};
    if (diff.connections.added) {
      inverseDiff.connections.removed = diff.connections.added;
    }
    if (diff.connections.removed) {
      inverseDiff.connections.added = diff.connections.removed;
    }
  }

  if (diff.connector) {
    inverseDiff.connector = {
      piece: selection.connector?.piece,
      designPiece: selection.connector?.designPiece,
      connector: selection.connector?.connector,
    };
  }

  return inverseDiff;
};
/**
 * Checks whether two Design app identifiers refer to the same design.
 **/
export const areSameDesignApp = (designApp: DesignAppId, other: DesignAppId): boolean => designApp.kit === other.kit && designApp.design === other.design;
/**
 * Checks whether a Design app identifier matches any in a list.
 **/
export const hasSameDesignApp = (designApp: DesignAppId, others: DesignAppId[]): boolean => others.some((other) => areSameDesignApp(designApp, other));

/**
 * DesignStore manages Design app state persistence, undo/redo stacks, and Y.js synchronization.
 *MUST extend PlainKitDiffAppStore and synchronize state with the Y.js shared document.
 **/
export class DesignStore extends PlainKitDiffAppStore<DesignAppState, DesignAppDiff, DesignAppSelectionDiff, DesignAppEdit, DesignAppCommandContext, DesignAppCommandResult> {
  private readonly kitId: Id;
  private _draggingPieceIds: Set<string> = new Set();
  get draggingPieceIds(): Set<string> {
    return this._draggingPieceIds;
  }
  setDraggingPieces(ids: Set<string>): void {
    this._draggingPieceIds = ids;
    this.notify();
  }
  clearDraggingPieces(): void {
    if (this._draggingPieceIds.size === 0) return;
    this._draggingPieceIds = new Set();
    this.notify();
  }
  private readonly designId: Id;

  constructor(parent: SketchpadStore, id: DesignAppId, initialState?: DesignAppState) {
    const defaultState: DesignAppState = {
      fullscreenWindow: initialState?.fullscreenWindow || DesignAppFullscreenWindow.None,
      panelVisibility: initialState?.panelVisibility || { toolbar: true, leftSidePanel: false, rightSidePanel: false, details: false },
      activeTool: initialState?.activeTool || ToolKind.SELECTION_NORMAL,
      selection: initialState?.selection,
      hover: initialState?.hover,
      presence: initialState?.presence,
      others: initialState?.others || [],
      camera: initialState?.camera,
      diagramCenter: initialState?.diagramCenter,
      diagramScale: initialState?.diagramScale,
      focusedPieceId: initialState?.focusedPieceId,
      selectedRepresentationTags: initialState?.selectedRepresentationTags || {},
      windowLayout: initialState?.windowLayout,
    };
    super(parent, defaultState);

    this.kitId = id.kit;
    this.designId = id.design;

    Object.entries(designAppCommands).forEach(([commandId, command]) => {
      this.registerCommand(commandId, command);
    });
  }

  kit(): KitHostStore {
    return this.parentStore.kit(this.kitId);
  }

  design(): { snapshot: () => Design } {
    const self = this;
    return {
      snapshot() {
        const k = self.kit().getSnapshot().kit;
        return k.designs?.find((d) => d.id === self.designId) ?? ({ id: self.designId, pieces: [], connections: [] } as Design);
      },
    };
  }

  protected getSelection(): DesignAppSelection {
    return this.state.selection || {};
  }

  protected inverseSelectionDiff(selection: DesignAppSelection, diff: DesignAppSelectionDiff): DesignAppSelectionDiff {
    return inverseDesignAppSelectionDiff(selection, diff);
  }

  protected applySelectionDiff(selectionDiff: DesignAppSelectionDiff): void {
    const currentSelection = this.state.selection || {};
    const newSelection: DesignAppSelection = { ...currentSelection };

    if (selectionDiff.pieces) {
      const currentPieces = new Set(currentSelection.pieces || []);
      if (selectionDiff.pieces.added) {
        selectionDiff.pieces.added.forEach((p) => currentPieces.add(p));
      }
      if (selectionDiff.pieces.removed) {
        selectionDiff.pieces.removed.forEach((p) => currentPieces.delete(p));
      }
      newSelection.pieces = currentPieces.size > 0 ? Array.from(currentPieces) : undefined;
    }

    if (selectionDiff.connections) {
      const currentConnections = new Set(currentSelection.connections || []);
      if (selectionDiff.connections.added) {
        selectionDiff.connections.added.forEach((c) => currentConnections.add(c));
      }
      if (selectionDiff.connections.removed) {
        selectionDiff.connections.removed.forEach((c) => currentConnections.delete(c));
      }
      newSelection.connections = currentConnections.size > 0 ? Array.from(currentConnections) : undefined;
    }

    if (selectionDiff.connector) {
      const connectorSelection = normalizeDesignConnectorRecord(selectionDiff.connector);
      if (connectorSelection) {
        newSelection.connector = connectorSelection;
        newSelection.connectors = [connectorSelection];
      } else {
        newSelection.connector = undefined;
        newSelection.connectors = undefined;
      }
    }

    this.state = { ...this.state, selection: normalizeDesignAppSelection(newSelection) };
    this.notify();
  }

  change(diff: DesignAppDiff): void {
    const newState = { ...this.state };

    if (diff.fullscreenWindow !== undefined) newState.fullscreenWindow = diff.fullscreenWindow;
    if (diff.activeTool !== undefined) newState.activeTool = diff.activeTool;
    if (diff.panelVisibility !== undefined) {
      newState.panelVisibility = { ...newState.panelVisibility, ...diff.panelVisibility };
    }
    if (diff.selection) {
      this.applySelectionDiff(diff.selection);
      return;
    }
    if (diff.hover !== undefined) {
      newState.hover = Object.keys(diff.hover).length === 0 ? undefined : diff.hover;
    }
    if (diff.camera !== undefined) newState.camera = diff.camera;
    if (diff.diagramCenter !== undefined) newState.diagramCenter = diff.diagramCenter;
    if (diff.diagramScale !== undefined) newState.diagramScale = diff.diagramScale;
    if (diff.focusedPieceId !== undefined) {
      newState.focusedPieceId = diff.focusedPieceId === null ? undefined : diff.focusedPieceId;
    }
    if (diff.selectedRepresentationTags !== undefined) {
      newState.selectedRepresentationTags = { ...(newState.selectedRepresentationTags || {}), ...diff.selectedRepresentationTags };
    }
    if (Object.prototype.hasOwnProperty.call(diff, "windowLayout")) {
      newState.windowLayout = (diff as any).windowLayout;
    }

    this.state = newState;
    this.notify();
  }

  async executeCommand<T>(command: string, ...args: any[]): Promise<T> {
    let origin: string | undefined;
    let rest: any[];

    if (typeof args[0] === "string" && args[0].startsWith("semio.sketchpad.")) {
      origin = args[0];
      rest = args.slice(1);
    } else {
      origin = undefined;
      rest = args;
    }

    if (command === "semio.designApp.startNewChange") {
      this.startTransaction();
      return {} as T;
    }
    if (command === "semio.designApp.saveChange") {
      this.finalizeTransaction();
      return {} as T;
    }
    if (command === "semio.designApp.discardChange") {
      this.abortTransaction();
      return {} as T;
    }
    if (command === "semio.designApp.undo") {
      this.undo();
      return {} as T;
    }
    if (command === "semio.designApp.redo") {
      this.redo();
      return {} as T;
    }

    const callback = this.commandRegistry.get(command);
    if (!callback) throw new Error(`Command "${command}" not found in design app store`);

    const kitStore = this.kit();
    const state = this.snapshot();
    const kitState = kitStore.getSnapshot().kit;

    const designStore = this.design();
    const design = designStore.snapshot();
    const actor = this.parentStore.actor;
    let designAppState = state;
    if (actor) {
      const machineKey = `${this.kitId}:${this.designId}`;
      const machineContext = actor.getSnapshot().context;
      const machineDesignApp = machineContext.designApps?.[machineKey];
      if (machineDesignApp) {
        designAppState = { ...state, selection: machineDesignApp.selection };
      }
    }
    const context: DesignAppCommandContext = {
      designApp: designAppState,
      kit: kitState,
      Id: design.id,
      design,
      fileUrls: kitStore.fileUrls,
      origin,
    };
    const result = callback(context, ...rest);
    if (result.diff) {
      this.change(result.diff);
    }
    if (result.kitGraph) {
      const kitRes = await applyKitHostGraphOperation(kitStore, result.kitGraph);
      if (kitRes.ok) {
        (result as any).kitCommandApplied = true;
      }
    }
    this.recordEdit(result);
    if (result.diff?.selection && actor) {
      actor.send({ type: "DESIGN.SET_SELECTION", kitId: this.kitId, designId: this.designId, selection: this.state.selection || {} } as any);
    }
    if (result.diff?.activeTool !== undefined && actor) {
      actor.send({ type: "DESIGN.SET_ACTIVE_TOOL", kitId: this.kitId, designId: this.designId, tool: result.diff.activeTool } as any);
    }
    return result as T;
  }

  execute<T>(command: string, ...rest: any[]): Promise<T> {
    return this.executeCommand(command, ...rest);
  }
}

/**
 * designStoreInitialized holds the data fields for a designStoreInitialized record.
 **/
let designStoreInitialized = false;
/**
 * Initializes the Design app store factory registration.
 *MUST register the DesignStore factory exactly once via registerDesignAppStoreFactory.
 **/
function initializeDesignStore() {
  designStoreInitialized = true;
  registerDesignAppStoreFactory((parent: any, id: any, state: any) => new DesignStore(parent, id, state));
}

// #region 🗝️Design App Plugin Registration
// Design app plugin registration MUST register the Design app plugin with machine actions, guards, and default state.

/**
 * designAppPlugin holds the data fields for a designAppPlugin record.
 **/
const designAppPlugin: AppPlugin = {
  id: "design",
  namespace: "DESIGN",
  machine: {
    actions: {},
    guards: {},
    eventHandlers: {},
    selectors: {},
    createDefaultState: (): DesignAppState => ({
      panelVisibility: { toolbar: true, leftSidePanel: false, rightSidePanel: false, details: false },
      selection: undefined,
      hover: undefined,
      presence: undefined,
      others: [],
      camera: undefined,
      diagramCenter: undefined,
      diagramScale: undefined,
      focusedPieceId: undefined,
      selectedRepresentationTags: {},
      windowLayout: undefined,
      fullscreenWindow: DesignAppFullscreenWindow.None,
      activeTool: ToolKind.SELECTION_NORMAL,
    }),
  },
  registerStores: () => {
    initializeDesignStore();
  },
};

if (typeof window !== "undefined") {
  registerAppPlugin(designAppPlugin);
  registerDesignAppHooks({
    useDesignAppDiff,
    useDesignAppHover,
    useDesignAppIsPieceHovered,
    useDesignAppIsPieceTransitiveHovered,
    useDesignAppIsConnectionHovered,
    useDesignAppSelection,
    useDesignAppIsPieceSelected,
    useDesignAppIsConnectionSelected,
    useDesignAppStore: useDesignStore,
  });
  const designAppEventConfig = {
    namespace: "DESIGN" as const,
    appKey: "designApps" as const,
    getKey: (event: any) => `${event.kitId}:${event.designId}`,
    createDefaultState: createDefaultDesignAppState,
  };
  registerKeyedAppEventHandlers(designAppEventConfig);
  registerEventHandler("DESIGN.SET_SELECTION", {
    action: (context: any, event: any) => {
      const key = designAppEventConfig.getKey(event);
      const apps = context.designApps || {};
      const app = apps[key] || createDefaultDesignAppState();
      return {
        designApps: {
          ...apps,
          [key]: { ...app, selection: normalizeDesignAppSelection(event.selection) },
        },
      };
    },
  });
  registerEventHandler("DESIGN.FOCUS_PIECE", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      return { designApps: { ...context.designApps, [key]: { ...app, focusedPieceId: event.pieceId } } };
    },
  });
  registerEventHandler("DESIGN.SET_DIAGRAM_CENTER", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      return { designApps: { ...context.designApps, [key]: { ...app, diagramCenter: event.center } } };
    },
  });
  registerEventHandler("DESIGN.SET_DIAGRAM_SCALE", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      return { designApps: { ...context.designApps, [key]: { ...app, diagramScale: event.scale } } };
    },
  });
  registerEventHandler("DESIGN.SELECT_REPRESENTATION_TAG", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const tags = app.selectedRepresentationTags[event.typeId] || [];
      if (tags.includes(event.tagId)) return {};
      return { designApps: { ...context.designApps, [key]: { ...app, selectedRepresentationTags: { ...app.selectedRepresentationTags, [event.typeId]: [...tags, event.tagId] } } } };
    },
  });
  registerEventHandler("DESIGN.DESELECT_REPRESENTATION_TAG", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const tags = app.selectedRepresentationTags[event.typeId] || [];
      return { designApps: { ...context.designApps, [key]: { ...app, selectedRepresentationTags: { ...app.selectedRepresentationTags, [event.typeId]: tags.filter((g: Id) => g !== event.tagId) } } } };
    },
  });
  registerEventHandler("DESIGN.SELECT_PIECE", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const baseSelection = stripDesignConnectorSelection(app.selection);
      const pieces = [...(baseSelection.pieces || [])];
      if (!pieces.includes(event.pieceId)) pieces.push(event.pieceId);
      return { designApps: { ...context.designApps, [key]: { ...app, selection: normalizeDesignAppSelection({ ...baseSelection, pieces }) } } };
    },
  });
  registerEventHandler("DESIGN.DESELECT_PIECE", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const baseSelection = stripDesignConnectorSelection(app.selection);
      const pieces = (baseSelection.pieces || []).filter((p: Id) => p !== event.pieceId);
      return { designApps: { ...context.designApps, [key]: { ...app, selection: normalizeDesignAppSelection({ ...baseSelection, pieces }) } } };
    },
  });
  registerEventHandler("DESIGN.SELECT_CONNECTION", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const baseSelection = stripDesignConnectorSelection(app.selection);
      const connections = [...(baseSelection.connections || [])];
      if (!connections.includes(event.connectionId)) connections.push(event.connectionId);
      return { designApps: { ...context.designApps, [key]: { ...app, selection: normalizeDesignAppSelection({ ...baseSelection, connections }) } } };
    },
  });
  registerEventHandler("DESIGN.DESELECT_CONNECTION", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      const baseSelection = stripDesignConnectorSelection(app.selection);
      const connections = (baseSelection.connections || []).filter((c: Id) => c !== event.connectionId);
      return { designApps: { ...context.designApps, [key]: { ...app, selection: normalizeDesignAppSelection({ ...baseSelection, connections }) } } };
    },
  });
  registerEventHandler("DESIGN.SELECT_ALL", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      return { designApps: { ...context.designApps, [key]: { ...app, selection: normalizeDesignAppSelection({ pieces: [], connections: [] }) } } };
    },
  });
  registerEventHandler("DESIGN.DELETE_SELECTED", {
    action: (context: any, event: any) => {
      const key = `${event.kitId}:${event.designId}`;
      const app = context.designApps[key] || createDefaultDesignAppState();
      return { designApps: { ...context.designApps, [key]: { ...app, selection: undefined } } };
    },
  });

  createKeyedChangeHandlers({
    namespace: "DESIGN",
    appKey: "designApps",
    keyFields: ["kitId", "designId"],
    createDefaultState: createDefaultDesignAppState,
  });
}

// #endregion 🗝️Design App Plugin Registration

/**
 * DesignAppShell holds the data fields for a DesignAppShell record.
 **/
type DesignAppShell = { id: string };
/**
 * DesignAppShellContext holds the data fields for a DesignAppShellContext record.
 **/
const DesignAppShellContext = createContext<DesignAppShell | null>(null);
/**
 * DesignAppActorContext holds the data fields for a DesignAppActorContext record.
 **/
const DesignAppActorContext = createContext<any>(null);
/**
 * DesignAppSyncComponent holds the data fields for a DesignAppSyncComponent record.
 **/
const DesignAppSyncComponent = ({ children }: { children: React.ReactNode }) => {
  useDesignAppInitialize();
  useDesignAppYjsToXStateSync();
  return <>{children}</>;
};

// #region 🦀Hooks
// Hooks MUST provide the Design app initialization lifecycle within the React component tree.

/** useDesignAppInitialize holds the data fields for a useDesignAppInitialize record.
 **/
/**
 **/
function useDesignAppInitialize() {
  const actor = useSketchpadActor();
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const kitId = kitScope?.id ?? "";
  const designId = designScope ?? "";
  const initializedKeyRef = useRef<string | null>(null);

  useLayoutEffect(() => {
    if (!kitId || !designId) return;
    const initKey = `${kitId}:${designId}`;
    if (initializedKeyRef.current === initKey) return;
    actor.send({
      type: "DESIGN.INIT",
      kitId,
      designId,
      state: {
        panelVisibility: { toolbar: true, leftSidePanel: false, rightSidePanel: false, details: false },
        selection: undefined,
        hover: undefined,
        camera: undefined,
        fullscreenWindow: DesignAppFullscreenWindow.None,
        selectedRepresentationTags: {},
        change: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      },
    });
    initializedKeyRef.current = initKey;
  }, [actor, kitId, designId]);
}

// #endregion 🦀Store

// #region 🎖️Components
// Components MUST provide Design app scope, actor context, and synchronization wrapper components.

/**
 * Provider component that establishes Design app scope and actor context.
 *MUST wrap children with DesignAppShellContext and DesignAppActorContext providers.
 **/
export const DesignAppShellProvider = (props: { id: string; children: React.ReactNode }) => {
  const value = { id: props.id };
  return React.createElement(DesignAppShellContext.Provider, { value }, React.createElement(DesignAppActorContext.Provider, { value: null }, React.createElement(DesignAppSyncComponent, null, props.children)));
};
/**
 * useDesignAppShell holds the data fields for a useDesignAppShell record.
 **/
const useDesignAppShell = () => useContext(DesignAppShellContext);

/**
 * Returns the current Design app XState actor from context.
 *MUST return the actor from DesignAppActorContext.
 **/
export function useDesignAppActor(): any {
  return useContext(DesignAppActorContext);
}

/**
 * Selects derived state from the Design app store.
 *MUST resolve the DesignStore from the orchestrator and apply the selector.
 **/
export function useDesignStore<T = DesignStore>(selector?: (store: DesignStore) => T, id?: DesignAppId): T | null {
  const store = useSketchpadStore();
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const resolvedKitId = kitScope?.id ?? id?.kit;
  const resolvedDesignId = designScope ?? id?.design;
  if (!resolvedKitId || !resolvedDesignId) {
    return null;
  }
  const designAppStore = store.designApp(resolvedKitId, resolvedDesignId);
  return selector ? selector(designAppStore) : (designAppStore as any);
}

export { useDesignStore as useDesignAppStore };

/**
 * Selects derived state from the Design app XState snapshot.
 *MUST use useSelector to reactively track the Design app state slice.
 **/
export function useDesignApp<T>(selector?: (state: DesignAppState) => T, id?: DesignAppId): T | DesignAppState | null {
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const kitId = kitScope?.id ?? id?.kit ?? "";
  const designId = designScope ?? id?.design ?? "";

  const state = useDesignAppXState(kitId, designId);

  if (!kitId || !designId) return null;

  if (selector) {
    return selector(state as unknown as DesignAppState) as T;
  }
  return state as unknown as DesignAppState;
}

/**
 * EMPTY_SELECTION holds the data fields for a EMPTY_SELECTION record.
 **/
const EMPTY_SELECTION: DesignAppSelection = {};
/**
 * EMPTY_OTHERS holds the data fields for a EMPTY_OTHERS record.
 **/
const EMPTY_OTHERS: DesignAppPresenceOther[] = [];
/**
 * EMPTY_REPRESENTATION_TAGS holds the data fields for a EMPTY_REPRESENTATION_TAGS record.
 **/
const EMPTY_REPRESENTATION_TAGS: Record<Id, string[]> = {};
const DEFAULT_PANEL_VISIBILITY: PanelVisibility = { toolbar: false, details: false, rightSidePanel: false };

/**
 * GranularSelectorFactory holds the data fields for a GranularSelectorFactory record.
 **/
type GranularSelectorFactory<T> = (kitId: Id, designId: Id) => (state: any) => T | undefined;

/**
 * UseDesignAppFieldOptions holds the data fields for a UseDesignAppFieldOptions record.
 **/
interface UseDesignAppFieldOptions<T, TEvent extends { type: string }> {
  createGranularSelector: GranularSelectorFactory<T>;
  fallback: T;
  createCanEvent: (kitId: Id, designId: Id) => TEvent;
  createSendEvent: (kitId: Id, designId: Id, value: T) => TEvent;
  useWildcardFallback?: boolean;
}
/**
 * useDesignAppField holds the data fields for a useDesignAppField record.
 **/
function useDesignAppField<T, TEvent extends { type: string }>(options: UseDesignAppFieldOptions<T, TEvent>): Field<T> {
  const { createGranularSelector, fallback, createCanEvent, createSendEvent, useWildcardFallback = false } = options;
  const actor = useSketchpadActor();
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const kitId = kitScope?.id ?? "";
  const designId = designScope ?? "";
  const granularSelector = useMemo(() => createGranularSelector(kitId, designId), [createGranularSelector, kitId, designId]);
  const rawValue = useSelector(actor, granularSelector);
  const value = rawValue ?? fallback;
  const canEvent = useMemo(() => createCanEvent(kitId, designId), [createCanEvent, kitId, designId]);
  const canSetFromSnapshot = useSelector(actor, (snapshot) => snapshot.can(canEvent as Parameters<typeof snapshot.can>[0]));
  const hasScope = kitId !== "" && designId !== "";
  const canSet = useWildcardFallback ? canSetFromSnapshot || hasScope : canSetFromSnapshot;
  return useMemo(() => createField(value, (next: T) => actor.send(createSendEvent(kitId, designId, next) as Parameters<typeof actor.send>[0]), canSet), [value, actor, createSendEvent, kitId, designId, canSet]);
}

/**
 * Returns a reactive field for the Design app selection state.
 * MUST create a Field wrapping the current selection and setter.
 **/
export function useDesignAppSelectionField(): Field<DesignAppSelection> {
  return useDesignAppField<DesignAppSelection, { type: "DESIGN.SET_SELECTION"; kitId: Id; designId: Id; selection: DesignAppSelection }>({
    createGranularSelector: createDesignSelectionSelector,
    fallback: {},
    createCanEvent: (kitId, designId) => ({ type: "DESIGN.SET_SELECTION", kitId, designId, selection: {} }),
    createSendEvent: (kitId, designId, selection) => ({ type: "DESIGN.SET_SELECTION", kitId, designId, selection }),
    useWildcardFallback: true,
  });
}

