/**
 * Returns a hook result for the Design app hover state.
 *MUST provide the current hover, a setter, and a canSet flag.
 **/
export function useDesignAppHover(): HookResult<DesignAppHover | undefined> {
  const actor = useSketchpadActor();
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const kitId = kitScope?.id ?? "";
  const designId = designScope ?? "";
  const store = useDesignStore(identitySelector) as DesignStore | null;
  const selector = useMemo(() => createDesignHoverSelector(kitId, designId), [kitId, designId]);
  const value = useSelector(actor, selector, areHoverStatesEqual);
  const canSetEvent = useMemo(() => ({ type: "DESIGN.SET_HOVER" as const, kitId, designId, hover: {} }), [kitId, designId]);
  const canSet = useSelector(actor, (snapshot) => snapshot.can(canSetEvent));
  const stableSetterRef = useRef<((hover: DesignAppHover | undefined) => void) | undefined>(undefined);
  stableSetterRef.current = canSet
    ? (hover: DesignAppHover | undefined) => {
        const currentHover = actor.getSnapshot().context.designApps[`${kitId}:${designId}`]?.hover;
        if (areHoverStatesEqual(currentHover, hover)) return;
        store?.change({ hover: hover ?? {} });
        queueMicrotask(() => {
          if (hover && (hover.pieces?.length || hover.connections?.length || hover.connectors?.length || hover.types?.length || hover.designs?.length)) {
            actor.send({ type: "DESIGN.SET_HOVER", kitId, designId, hover });
          } else {
            actor.send({ type: "DESIGN.CLEAR_HOVER", kitId, designId });
          }
        });
      }
    : undefined;
  const setter = useMemo(() => {
    if (!canSet) return undefined;
    return (hover: DesignAppHover | undefined) => stableSetterRef.current?.(hover);
  }, [canSet]);
  return conditionalHookResult(canSet, value, setter);
}

