/**
 * Returns whether a specific piece port is currently selected.
 *MUST check the selection connector state for the given piece-connector pair.
 **/
export function useDesignAppIsPiecePortSelected(pieceId: string, connectorId?: string): boolean {
  const actor = useSketchpadActor();
  const kitScope = useActiveKitTab();
  const designScope = useDesignContext();
  const kitId = kitScope?.id ?? "";
  const designId = designScope ?? "";
  const stableConnectorId = connectorId ?? "";
  const selector = useMemo(() => {
    const key = `${kitId}:${designId}`;
    return (state: { context: SketchpadContext }) => {
      if (!stableConnectorId) return false;
      const selection = state.context.designApps[key]?.selection;
      const primary = getPrimaryDesignConnectorSelection(selection);
      if (primary?.piece === pieceId && primary.connector === stableConnectorId) return true;
      return selection?.connectors?.some((connector) => connector.piece === pieceId && connector.connector === stableConnectorId) ?? false;
    };
  }, [kitId, designId, pieceId, stableConnectorId]);
  return useSelector(actor, selector);
}

